INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们很早以前了住在这个村子里。", "corrected_sentence": "他们很早以前住在这个村子里。", "error_description": "错误在于“了”：它被放在时间词“很早以前”之后、动词“住”之前，不合语法；应删去“了”，说“他们很早以前住在这个村子里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥是很早以前的建的。", "corrected_sentence": "这座桥是很早以前建的。", "error_description": "错误在于多出的“的”：“以前”与“建”之间插入“的”，“很早以前的建的”结构不通；“是……的”句式中只需说“这座桥是很早以前建的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
