INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每天要做的事情。", "primary_collocate": null, "pronunciation": "rì cháng shēng huó", "ipa": "ɻɻ̩˥˩ ʈʂʰɑŋ˧˥ ʂɤŋ˥ xuɔ˧˥", "syllable_count": 4, "sentences": [{"text": "我的日常生活是上班、吃饭、睡觉。", "target_word": "日常生活", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天做饭洗衣，日常生活很忙。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会做饭是日常生活的一件小事。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的日常生活要有人照顾。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在小村子里，日常生活很安静。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢拍下日常生活里的小故事。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日常生活中，多喝水对身体好。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想改变日常生活，每天早点起床。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好汉语，日常生活就方便多了。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放假的时候，我的日常生活很自由。", "target_word": "日常生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "日常生活：每天要做的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2854b20d-fa79-453e-abe6-a6f7a130006c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日常生活", "is_correct": true, "explanation": "正确。上班、吃饭、睡觉是每天要做的事，所以是“日常生活”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是劳动报酬，“我的工资是上班、吃饭、睡觉”说不通。"}, {"text": "假期", "is_correct": false, "explanation": "语义：假期是休息的时间，与“上班”相反，句子前后矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "语义：上班、吃饭、睡觉不是学习任务，“作业”与句意不符。"}], "explanations": {"日常生活": "正确。上班、吃饭、睡觉是每天要做的事，所以是“日常生活”。", "工资": "搭配：“工资”是劳动报酬，“我的工资是上班、吃饭、睡觉”说不通。", "假期": "语义：假期是休息的时间，与“上班”相反，句子前后矛盾。", "作业": "语义：上班、吃饭、睡觉不是学习任务，“作业”与句意不符。"}, "sentence_index": 0, "correct_answer": "日常生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去药店买了一批日常生活。", "explanation": "这里应该用〈用品〉。〈日常生活〉是抽象的生活过程，不能买，应说“日常用品”。"}, {"text": "这次班级组织了一场日常生活，大家一起去郊游。", "explanation": "这里应该用〈活动〉。〈日常生活〉指平时的生活本身，不是可以组织、举行的一场活动。"}, {"text": "这里有一座日常生活。", "explanation": "这里不应该用〈座〉。〈座〉用于山、楼房等大型固定的东西，〈日常生活〉不能这样计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日常生活", "is_correct": true, "explanation": "正确。“日常生活中”指平时每天的生活，多喝水是日常的好习惯。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术期间通常不能随便喝水，与“多喝水对身体好”的语境相反。"}, {"text": "麻醉", "is_correct": false, "explanation": "语义：麻醉期间身体处于昏迷状态，不能喝水，与句中建议矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮中”不是可以多喝水的场合，句意不通。"}], "explanations": {"日常生活": "正确。“日常生活中”指平时每天的生活，多喝水是日常的好习惯。", "手术": "语义：手术期间通常不能随便喝水，与“多喝水对身体好”的语境相反。", "麻醉": "语义：麻醉期间身体处于昏迷状态，不能喝水，与句中建议矛盾。", "月亮": "语义：“月亮中”不是可以多喝水的场合，句意不通。"}, "sentence_index": 6, "correct_answer": "日常生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他报名参加了一门日常生活。", "explanation": "这里应该用〈课程〉。〈日常生活〉不是可以报名的课程，〈门〉不能用来数它。"}, {"text": "他昨天参加了一场日常生活。", "explanation": "这里应该用〈比赛〉。〈日常生活〉是平时的生活，不是可以参加的比赛。"}, {"text": "公司完成了一项日常生活。", "explanation": "这里应该用〈项目〉。〈日常生活〉不是可以完成的项目，〈项〉用于项目、任务等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一个日常生活很规律。", "corrected_sentence": "我的日常生活很规律。", "error_description": "错误形式是“一个日常生活”，正确形式是“日常生活”。“日常生活”是抽象名词，不能用个体量词“一个”修饰，应直接说“我的日常生活很规律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学会开车，我地日常生活就方便多了。", "corrected_sentence": "学会开车，我的日常生活就方便多了。", "error_description": "错误形式是“我地日常生活”，正确形式是“我的日常生活”。修饰名词要用“的”，“地”用于修饰动词或形容词，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f5a9624-f351-4fba-97c8-93bf71d791c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗", "is_correct": true, "explanation": "暗与“亮”构成反义，指光线不足。"}, {"text": "快", "is_correct": false, "explanation": "快与“亮”不构成反义，快指速度高，与光线无关。"}, {"text": "重", "is_correct": false, "explanation": "重与“亮”不构成反义，重指分量大，与光线无关。"}, {"text": "软", "is_correct": false, "explanation": "软与“亮”不构成反义，软描述质地，与光线无关。"}], "correct_answer": "暗", "explanations": {"暗": "暗与“亮”构成反义，指光线不足。", "快": "快与“亮”不构成反义，快指速度高，与光线无关。", "重": "重与“亮”不构成反义，重指分量大，与光线无关。", "软": "软与“亮”不构成反义，软描述质地，与光线无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗", "is_correct": true, "explanation": "暗与“亮”构成反义，指光线不足。"}, {"text": "慢", "is_correct": false, "explanation": "慢与“亮”不构成反义，慢指速度低，与光线无关。"}, {"text": "硬", "is_correct": false, "explanation": "硬与“亮”不构成反义，硬描述质地，与光线无关。"}, {"text": "厚", "is_correct": false, "explanation": "厚与“亮”不构成反义，厚描述物体的厚度，与光线无关。"}], "correct_answer": "暗", "explanations": {"暗": "暗与“亮”构成反义，指光线不足。", "慢": "慢与“亮”不构成反义，慢指速度低，与光线无关。", "硬": "硬与“亮”不构成反义，硬描述质地，与光线无关。", "厚": "厚与“亮”不构成反义，厚描述物体的厚度，与光线无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "亮就是光很强，让人能看清楚东西。", "primary_collocate": null, "pronunciation": "liàng", "ipa": "ljɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "今天的太阳很亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏灯太亮了，我睡不着。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚月光很亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手电筒的光很亮，能看清路。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的光不够亮，看不清字。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间不亮，请你开灯。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗边比较亮，我在那里看书。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的灯很亮，同学们都能看清黑板。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车灯很亮，照得我睁不开眼。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上的光特别亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亮了", "label": "体标"}, {"form": "亮着", "label": "体标"}, {"form": "明亮", "label": "复合"}], "register": "中性", "sense_fingerprint": "光很强、能看清东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亮", "is_correct": true, "explanation": "这是正确答案：亮（liàng），指光很强、能看清东西。"}, {"text": "凉", "is_correct": false, "explanation": "liáng（第二声）与 liàng（第四声）声调不同，意思是凉。"}, {"text": "练", "is_correct": false, "explanation": "liàn 与 liàng 只差韵尾 n/ng，意思是练习。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。"}], "explanations": {"亮": "这是正确答案：亮（liàng），指光很强、能看清东西。", "凉": "liáng（第二声）与 liàng（第四声）声调不同，意思是凉。", "练": "liàn 与 liàng 只差韵尾 n/ng，意思是练习。", "两": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。"}, "sentence_index": null, "correct_answer": "亮"}, "level_3": {"options": [{"text": "亮", "is_correct": true, "explanation": "正确：“今天的太阳很亮”指太阳的光很强，符合语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：太阳不能是甜的，“太阳很甜”说不通。"}, {"text": "响", "is_correct": false, "explanation": "搭配：“响”形容声音，不能用来形容太阳。"}, {"text": "硬", "is_correct": false, "explanation": "语义：太阳不是硬的，“太阳很硬”与句意不合。"}], "explanations": {"亮": "正确：“今天的太阳很亮”指太阳的光很强，符合语境。", "甜": "语义：太阳不能是甜的，“太阳很甜”说不通。", "响": "搭配：“响”形容声音，不能用来形容太阳。", "硬": "语义：太阳不是硬的，“太阳很硬”与句意不合。"}, "sentence_index": 0, "correct_answer": "亮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子很亮，不够用。", "explanation": "这里应该用〈长〉。“亮”形容光，不能形容长短，绳子的长短要用“长”。"}, {"text": "这个西瓜很亮，大家都爱吃。", "explanation": "这里应该用〈甜〉。“亮”形容光，不能用来形容味道，西瓜的味道要用“甜”。"}, {"text": "这箱子很亮，我搬不动。", "explanation": "这里应该用〈重〉。“亮”不能形容重量，箱子的分量要用“重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亮", "is_correct": true, "explanation": "这是正确答案：亮（liàng），指光很强、能看清东西。"}, {"text": "粮", "is_correct": false, "explanation": "liáng（第二声）与 liàng（第四声）声调不同，意思是粮食。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。"}, {"text": "酿", "is_correct": false, "explanation": "niàng 与 liàng 声母 n/l 不同，意思是酿造。"}], "explanations": {"亮": "这是正确答案：亮（liàng），指光很强、能看清东西。", "粮": "liáng（第二声）与 liàng（第四声）声调不同，意思是粮食。", "两": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。", "酿": "niàng 与 liàng 声母 n/l 不同，意思是酿造。"}, "sentence_index": null, "correct_answer": "亮"}, "level_3": {"options": [{"text": "亮", "is_correct": true, "explanation": "正确：“窗边比较亮”指那里光线较强，适合看书。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”用于人或动物的体形，窗边不能说“胖”。"}, {"text": "苦", "is_correct": false, "explanation": "语义：窗边不能是苦的，与看书的情境不合。"}, {"text": "饱", "is_correct": false, "explanation": "语义：窗边不会饱，“窗边比较饱”说不通。"}], "explanations": {"亮": "正确：“窗边比较亮”指那里光线较强，适合看书。", "胖": "体貌：“胖”用于人或动物的体形，窗边不能说“胖”。", "苦": "语义：窗边不能是苦的，与看书的情境不合。", "饱": "语义：窗边不会饱，“窗边比较饱”说不通。"}, "sentence_index": 6, "correct_answer": "亮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脚很亮，走不了路。", "explanation": "这里应该用〈痛〉。“亮”形容光，不能用来形容身体的感觉，脚疼要用“痛”。"}, {"text": "这段路程很亮，我们走了好久。", "explanation": "这里应该用〈远〉。“亮”不能形容距离，路程的长短要用“远”。"}, {"text": "这药很亮，孩子都不肯喝。", "explanation": "这里应该用〈苦〉。“亮”不能形容味道，药的味道要用“苦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户开着，屋里亮很。", "corrected_sentence": "窗户开着，屋里很亮。", "error_description": "程度修饰语语序错误：应为“很亮”，不能说“亮很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把桌子亮擦了。", "corrected_sentence": "他把桌子擦亮了。", "error_description": "结果补语位置错误：“擦亮”是动补结构，应为“擦亮”，不能说“亮擦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
