INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "灯是用来照亮的工具。", "primary_collocate": null, "pronunciation": "dēng", "ipa": "tɤŋ˥", "syllable_count": 1, "sentences": [{"text": "山路很黑，我们需要一盏灯。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里拿着一盏灯。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏灯可以照亮整个房间。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有灯，晚上就看不见路。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一盏新灯。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床边的灯是我最喜欢的。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们提着灯去公园。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏灯不用电也能亮。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把那盏灯放在桌子上。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里停电了，我们点了灯。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盏", "label": "量词"}, {"form": "台灯", "label": "复合"}, {"form": "路灯", "label": "复合"}, {"form": "燈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来照亮的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd4e57f7-af7c-4ea1-9953-f36f2503a567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灯", "is_correct": true, "explanation": "这是正确答案：灯（dēng），指用来照亮的工具。"}, {"text": "凳", "is_correct": false, "explanation": "dèng（第四声）与 dēng（第一声）声调不同，意思是板凳。"}, {"text": "当", "is_correct": false, "explanation": "dāng（第一声）与 dēng 只差韵母 a/e，意思是担任或当作。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dēng 只差韵母 o/e，意思是东边。"}], "explanations": {"灯": "这是正确答案：灯（dēng），指用来照亮的工具。", "凳": "dèng（第四声）与 dēng（第一声）声调不同，意思是板凳。", "当": "dāng（第一声）与 dēng 只差韵母 a/e，意思是担任或当作。", "东": "dōng（第一声）与 dēng 只差韵母 o/e，意思是东边。"}, "sentence_index": null, "correct_answer": "灯"}, "level_3": {"options": [{"text": "灯", "is_correct": true, "explanation": "正确：“一盏灯”可以用来照路，与“山路很黑”相合。"}, {"text": "茶", "is_correct": false, "explanation": "语义：茶不能用来照路，“需要一盏茶”与山路很黑的情境不合。"}, {"text": "酒", "is_correct": false, "explanation": "语义：酒不能用来照亮山路，“需要一盏酒”与山路很黑的情境不合。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤不能照亮山路，与“山路很黑”的情境不合。"}], "explanations": {"灯": "正确：“一盏灯”可以用来照路，与“山路很黑”相合。", "茶": "语义：茶不能用来照路，“需要一盏茶”与山路很黑的情境不合。", "酒": "语义：酒不能用来照亮山路，“需要一盏酒”与山路很黑的情境不合。", "汤": "语义：汤不能照亮山路，与“山路很黑”的情境不合。"}, "sentence_index": 0, "correct_answer": "灯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨了，他撑着灯出门。", "explanation": "这里应该用〈伞〉。撑是用伞遮雨，灯不能撑，拿灯要说“提”。"}, {"text": "妈妈用灯织了一件毛衣。", "explanation": "这里应该用〈毛线〉。织是用毛线做衣服，灯不是织的材料。"}, {"text": "他饿了，用灯煮了一锅饭。", "explanation": "这里应该用〈锅〉。灯是照明工具，不能用来煮饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26728, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "灯", "is_correct": true, "explanation": "这是正确答案：灯（dēng），指用来照亮的工具。"}, {"text": "等", "is_correct": false, "explanation": "děng（第三声）与 dēng（第一声）声调不同，意思是等待。"}, {"text": "瞪", "is_correct": false, "explanation": "dèng（第四声）与 dēng（第一声）声调不同，意思是瞪眼。"}, {"text": "钉", "is_correct": false, "explanation": "dīng（第一声）与 dēng 只差韵母 i/e，意思是钉子。"}], "explanations": {"灯": "这是正确答案：灯（dēng），指用来照亮的工具。", "等": "děng（第三声）与 dēng（第一声）声调不同，意思是等待。", "瞪": "dèng（第四声）与 dēng（第一声）声调不同，意思是瞪眼。", "钉": "dīng（第一声）与 dēng 只差韵母 i/e，意思是钉子。"}, "sentence_index": null, "correct_answer": "灯"}, "level_3": {"options": [{"text": "灯", "is_correct": true, "explanation": "正确：小朋友提着灯去公园，灯是可以提着的照明工具。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能被提着去公园，与“提着”的情境不合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被提着，“提着空气”说不通。"}, {"text": "歌", "is_correct": false, "explanation": "配价：“提”要求可以拿在手里的具体物件，歌不能被提。"}], "explanations": {"灯": "正确：小朋友提着灯去公园，灯是可以提着的照明工具。", "太阳": "语义：太阳不能被提着去公园，与“提着”的情境不合。", "空气": "语义：空气无法被提着，“提着空气”说不通。", "歌": "配价：“提”要求可以拿在手里的具体物件，歌不能被提。"}, "sentence_index": 6, "correct_answer": "灯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，吃了一盏灯。", "explanation": "这里应该用〈饭〉。灯是照明工具，不能吃，吃的要说饭。"}, {"text": "我们买了一块灯。", "explanation": "这里应该用〈盏〉。灯的量词是“盏”，“块”用于块状的东西，不用于灯具。"}, {"text": "我们买了一颗灯。", "explanation": "这里应该用〈盏〉。“颗”用于颗粒状或圆形的小东西，灯不用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里我们在营地点了一支灯。", "corrected_sentence": "夜里我们在营地点了一盏灯。", "error_description": "量词错误：“灯”应该用“盏”计量，“支”用于棍状物、笔、蜡烛等，不能说“一支灯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d10861e-3ecc-466f-9829-225dcfb68c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
