INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面粉是做面包和馒头用的白色粉末。", "primary_collocate": null, "pronunciation": "miàn fěn", "ipa": "mjɛn˥˩ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "厨房里有一包面粉，还有两个鸡蛋。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用面粉做面条，晚上请朋友来吃。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面粉很白，做出来的馒头也很白。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把面粉倒进碗里，慢慢加水。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面粉要放在干的地方，湿了就会坏。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩玩面粉，脸上和手上都是白的。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的面粉一公斤四块钱。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做包子要先用面粉做皮，再放肉。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的面粉卖完了，明天才有新的。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在面粉里加了一点儿糖和油。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一袋面粉", "label": "量词"}, {"form": "一包面粉", "label": "量词"}, {"form": "面粉厂", "label": "复合"}, {"form": "麵粉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做面包、馒头用的白色粉末", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8ddd3f-1e11-496c-a1ad-5495bc12503a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面粉", "is_correct": true, "explanation": "正确：面粉可以用“包”计量，厨房里的一包面粉与句意相符。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不以“包”计量，也不会放在厨房里。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“一包”不搭配石头，厨房里一般不放一包石头。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是包装的粉状食材，与“两个鸡蛋”的做饭场景不合。"}], "explanations": {"面粉": "正确：面粉可以用“包”计量，厨房里的一包面粉与句意相符。", "汽油": "语义：汽油不以“包”计量，也不会放在厨房里。", "石头": "搭配：“一包”不搭配石头，厨房里一般不放一包石头。", "电脑": "语义：电脑不是包装的粉状食材，与“两个鸡蛋”的做饭场景不合。"}, "sentence_index": 0, "correct_answer": "面粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早饭我一般吃面粉和牛奶。", "explanation": "这里应该用〈面包〉。面粉是生的粉，不能直接当早餐吃，早饭吃的是面包。"}, {"text": "奶奶把面粉擀成了薄皮。", "explanation": "这里应该用〈面团〉。擀的是面团，干面粉不能直接擀成面皮，要先加水和成面团。"}, {"text": "这碗面粉加了很多辣椒。", "explanation": "这里应该用〈米粉〉。面粉是原料，不能像米粉那样煮成一碗加辣椒的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面粉", "is_correct": true, "explanation": "正确：面粉按公斤卖，符合“一公斤四块钱”。"}, {"text": "香烟", "is_correct": false, "explanation": "语义：香烟不按公斤计价，与“一公斤四块钱”冲突。"}, {"text": "布料", "is_correct": false, "explanation": "搭配：布料一般按米计价，“一公斤”不搭配布料。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油一般按升卖，超市里的汽油也不按公斤计价。"}], "explanations": {"面粉": "正确：面粉按公斤卖，符合“一公斤四块钱”。", "香烟": "语义：香烟不按公斤计价，与“一公斤四块钱”冲突。", "布料": "搭配：布料一般按米计价，“一公斤”不搭配布料。", "汽油": "语义：汽油一般按升卖，超市里的汽油也不按公斤计价。"}, "sentence_index": 6, "correct_answer": "面粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了三只面粉，准备做包子。", "explanation": "量词用错。〈只〉多用于动物或成对物品中的一个，面粉要用〈袋〉或〈斤〉计量。"}, {"text": "我买了一张面粉，准备做蛋糕。", "explanation": "量词用错。〈张〉多用于纸、桌子等扁平的东西，面粉要用〈袋〉或〈斤〉计量。"}, {"text": "我买了一根面粉，准备做面包。", "explanation": "量词用错。〈根〉多用于细长的东西，面粉要用〈袋〉或〈斤〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "面粉好和了，可以开始做馒头了。", "corrected_sentence": "面粉和好了，可以开始做馒头了。", "error_description": "补语位置错误：结果补语“好”要放在动词“和”后面，应说“和好了”，不能说“好和了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家面粉厂每天能磨出几朵面粉。", "corrected_sentence": "那家面粉厂每天能磨出几袋面粉。", "error_description": "量词错误：面粉要用“袋”计量，“朵”多用于花、云等，应为“磨出几袋面粉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '918f171c-e601-48c6-ab62-ef128fd25419') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26736, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆除", "is_correct": true, "explanation": "正确：“拆除”指把已经建成的建筑或设施拆掉，与“建造”的意思相反。"}, {"text": "保护", "is_correct": false, "explanation": "“保护”指使人或事物免受伤害，与“建造”不构成反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指大家交换意见，与“建造”无关，不是反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指到外地游览，与“建造”不构成反义关系。"}], "correct_answer": "拆除", "explanations": {"拆除": "正确：“拆除”指把已经建成的建筑或设施拆掉，与“建造”的意思相反。", "保护": "“保护”指使人或事物免受伤害，与“建造”不构成反义关系。", "讨论": "“讨论”指大家交换意见，与“建造”无关，不是反义词。", "旅行": "“旅行”指到外地游览，与“建造”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26736, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆除", "is_correct": true, "explanation": "正确：“拆除”指把已经建成的建筑或设施拆掉，与“建造”的意思相反。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指使损坏的东西恢复正常，与“建造”不构成反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "“写作”指创作文字作品，与“建造”无关，不是反义词。"}, {"text": "种植", "is_correct": false, "explanation": "“种植”指栽种植物，与“建造”无关，不是反义词。"}], "correct_answer": "拆除", "explanations": {"拆除": "正确：“拆除”指把已经建成的建筑或设施拆掉，与“建造”的意思相反。", "修理": "“修理”指使损坏的东西恢复正常，与“建造”不构成反义关系。", "写作": "“写作”指创作文字作品，与“建造”无关，不是反义词。", "种植": "“种植”指栽种植物，与“建造”无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26736, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修建房屋、桥梁、船只等大型工程。", "primary_collocate": null, "pronunciation": "jiàn zào", "ipa": "tɕjɛn˥˩ tsɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他们在河上建造了一座桥。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在建造一座新学校。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷自己建造了这所房子。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座塔建造了三年。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想在山上建造一个小花园。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘大船是在海边建造的。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的城市要建造一个大公园。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子建造得很结实。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友用沙子建造了一座城堡。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里准备建造一所医院。", "target_word": "建造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "建造了", "label": "体标"}, {"form": "建造着", "label": "体标"}, {"form": "建造过", "label": "体标"}], "register": "中性", "sense_fingerprint": "建造|action|修建房屋、桥梁、船只等大型工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c39c2f0b-1c7d-4288-9529-c42fc1d1b19a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建造", "is_correct": true, "explanation": "正确：“建造”指修建桥梁、房屋等大型物体，与“在河上”和“桥”相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱一座桥”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“桥”这样的建筑物不相容。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是文字，不能说“读一座桥”。"}], "explanations": {"建造": "正确：“建造”指修建桥梁、房屋等大型物体，与“在河上”和“桥”相符。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱一座桥”。", "吃": "语义：“吃”指进食，与“桥”这样的建筑物不相容。", "读": "搭配：“读”的对象是文字，不能说“读一座桥”。"}, "sentence_index": 0, "correct_answer": "建造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国建造了外交关系。", "explanation": "这里应该用〈建立〉。“建造”用于房屋、桥梁等实体工程，建立关系、制度要用“建立”。"}, {"text": "这家工厂建造了三辆汽车。", "explanation": "这里应该用〈制造〉。“建造”用于大型建筑或工程，生产汽车、机器要用“制造”。"}, {"text": "他们建造了良好的学习氛围。", "explanation": "这里应该用〈营造〉。“营造”用于氛围、环境，“建造”只用于具体的建筑和工程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建造", "is_correct": true, "explanation": "正确：“建造”与“一个大公园”搭配，指修建大型设施，与“城市要……”相符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写一个公园”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与“公园”这样的场所不相容。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或身体，不能说“洗一个公园”。"}], "explanations": {"建造": "正确：“建造”与“一个大公园”搭配，指修建大型设施，与“城市要……”相符。", "写": "搭配：“写”的对象是文字，不能说“写一个公园”。", "喝": "语义：“喝”指饮用，与“公园”这样的场所不相容。", "洗": "搭配：“洗”的对象是衣物或身体，不能说“洗一个公园”。"}, "sentence_index": 6, "correct_answer": "建造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府建造了一部新法律。", "explanation": "这里应该用〈制定〉。法律、规章要“制定”，“建造”只用于实体工程。"}, {"text": "学校建造了一场比赛。", "explanation": "这里应该用〈举办〉。比赛、活动要“举办”，“建造”不用于活动。"}, {"text": "他建造了一首歌。", "explanation": "这里应该用〈创作〉。“建造”指修建房屋、桥梁等实体工程，写歌要用“创作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座大楼建造很牢固。", "corrected_sentence": "这座大楼建造得很牢固。", "error_description": "“建造”后面的补语要用“得”连接，应说“建造得很牢固”，不能省略“得”说“建造很牢固”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们正在建造了一座新医院。", "corrected_sentence": "工人们正在建造一座新医院。", "error_description": "“正在”表示动作正在进行，“了”表示动作完成，两者不能同时用在同一个动作上。这里应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
