INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26738, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西吸进里面去。", "primary_collocate": null, "pronunciation": "xī shōu", "ipa": "ɕi˥ ʂou˥", "syllable_count": 2, "sentences": [{"text": "海绵能吸收很多水。", "target_word": "吸收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物的根吸收水和养分。", "target_word": "吸收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布吸收了桌上的水。", "target_word": "吸收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色的衣服吸收太阳的热。", "target_word": "吸收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体吸收了食物里的营养。", "target_word": "吸收", "complexity_tier": "T3", "furigana": "shēntǐ xīshōu le shíwù lǐ de yíngyǎng。", "sentence_source": "generated"}, {"text": "土地吸收了昨晚的雨水。", "target_word": "吸收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸吸收水很快。", "target_word": "吸收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厚毛巾吸收水的能力很强。", "target_word": "吸收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶子吸收着阳光。", "target_word": "吸收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子吸收不了这么多水。", "target_word": "吸收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸收了", "label": "体标"}, {"form": "吸收着", "label": "体标"}, {"form": "吸收过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西吸进里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4177ca5c-ed1d-4b04-aa07-385752d02c3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸收", "is_correct": true, "explanation": "吸收：指把水吸进内部，与“海绵”和“水”搭配，是正确答案。"}, {"text": "生产", "is_correct": false, "explanation": "语义：海绵不能生产水，生产指制造出新的东西。"}, {"text": "饮", "is_correct": false, "explanation": "语域：“饮”偏书面，且海绵没有饮水的动作，与句子的语域不合。"}, {"text": "制造", "is_correct": false, "explanation": "语义：海绵不能制造水，“制造”指造出新的东西。"}], "explanations": {"吸收": "吸收：指把水吸进内部，与“海绵”和“水”搭配，是正确答案。", "生产": "语义：海绵不能生产水，生产指制造出新的东西。", "饮": "语域：“饮”偏书面，且海绵没有饮水的动作，与句子的语域不合。", "制造": "语义：海绵不能制造水，“制造”指造出新的东西。"}, "sentence_index": 0, "correct_answer": "吸收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "磁铁吸收了桌上的铁钉。", "explanation": "这里应该用〈吸引〉。磁铁对铁钉的作用是吸引，“吸收”指把物质吸进内部，不能用于磁力。"}, {"text": "公司吸收了五十名新员工。", "explanation": "这里应该用〈录用〉。“吸收”在此表示接纳新成员，不是把东西吸进里面去的本义。"}, {"text": "吸盘能吸收在墙上。", "explanation": "这里应该用〈吸附〉。吸盘贴在墙上靠的是附着，“吸收”指吸进内部，不能说“吸收在墙上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸收", "is_correct": true, "explanation": "吸收：指纸把水吸进去，与“纸”和“水”搭配，是正确答案。"}, {"text": "反射", "is_correct": false, "explanation": "语义：反射用于光、热、声音，纸不能反射水。"}, {"text": "制作", "is_correct": false, "explanation": "搭配：“制作”的对象是物品，不能说“制作水”来形容纸的作用。"}, {"text": "散发", "is_correct": false, "explanation": "搭配：“散发”用于气味、热量，不能用于吸水。"}], "explanations": {"吸收": "吸收：指纸把水吸进去，与“纸”和“水”搭配，是正确答案。", "反射": "语义：反射用于光、热、声音，纸不能反射水。", "制作": "搭配：“制作”的对象是物品，不能说“制作水”来形容纸的作用。", "散发": "搭配：“散发”用于气味、热量，不能用于吸水。"}, "sentence_index": 6, "correct_answer": "吸收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水汽吸收成了雨。", "explanation": "这里应该用〈凝结〉。水汽变成雨要用“凝结”，“吸收”不能表示这种变化。"}, {"text": "工人们吸收了很多废纸。", "explanation": "这里应该用〈收集〉。收集废纸是把分散的东西聚到一起，“吸收”指吸进内部，不能这样用。"}, {"text": "管道把石油吸收到了工厂。", "explanation": "这里应该用〈输送〉。管道运送石油要用“输送”，管道不能“吸收”石油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毛巾很快就吸收地水。", "corrected_sentence": "毛巾很快就吸收了水。", "error_description": "错误：“地”用于修饰动词的状语，不能放在动词后修饰宾语；“吸收地水”应改为“吸收水”，句中加“了”会更自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种棉布吸收的很快。", "corrected_sentence": "这种棉布吸收得很快。", "error_description": "补语错误：动词后表示程度的补语要用“得”，“吸收的很快”错误，正确形式为“吸收得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0b14b86-4dcf-4ad2-830b-fc3605394ef0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
