INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26750, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很大很大。", "primary_collocate": null, "pronunciation": "dà dà de", "ipa": "ta˥˩ ta˥˩ tə", "syllable_count": 3, "sentences": [{"text": "这只熊猫有大大的黑眼圈。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在纸上画了一个大大的太阳。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手大大的，能抓住三个苹果。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边有一座大大的灯塔。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子打开大大的礼物盒，笑了。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上飘着大大的白云。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里种着一棵大大的苹果树。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她戴着一副大大的眼镜。", "target_word": "大大的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个南瓜大大的，一个人抱不动。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上写了大大的“好”字。", "target_word": "大大的", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "重叠式形容词，强调形状或尺寸很大，常用来描述具体事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab33c06f-7df9-4a5c-b347-e98431a3920c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26750, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大大的", "is_correct": true, "explanation": "正确答案。dà dà de 即“很大很大”。"}, {"text": "哒哒的", "is_correct": false, "explanation": "dā dā de 与 dà dà de 只有声调不同（第一声与第四声），意思是拟声词。"}, {"text": "嗒嗒的", "is_correct": false, "explanation": "dā dā de 与 dà dà de 只有声调不同（第一声与第四声），意思是拟声词。"}, {"text": "答答的", "is_correct": false, "explanation": "dá dá de 与 dà dà de 只有声调不同（第二声与第四声），意思是湿漉漉的样子。"}], "explanations": {"大大的": "正确答案。dà dà de 即“很大很大”。", "哒哒的": "dā dā de 与 dà dà de 只有声调不同（第一声与第四声），意思是拟声词。", "嗒嗒的": "dā dā de 与 dà dà de 只有声调不同（第一声与第四声），意思是拟声词。", "答答的": "dá dá de 与 dà dà de 只有声调不同（第二声与第四声），意思是湿漉漉的样子。"}, "sentence_index": null, "correct_answer": "大大的"}, "level_3": {"options": [{"text": "大大的", "is_correct": true, "explanation": "正确答案。形容熊猫眼圈很大，符合句意。"}, {"text": "冷冷的", "is_correct": false, "explanation": "语义：“冷”形容温度，与描写黑眼圈的语境不合。"}, {"text": "软软的", "is_correct": false, "explanation": "语义：“软”形容质地，黑眼圈不能用来描述为“软”的。"}, {"text": "甜甜的", "is_correct": false, "explanation": "搭配：“甜”不能用来形容“黑眼圈”，这一搭配不自然。"}], "explanations": {"大大的": "正确答案。形容熊猫眼圈很大，符合句意。", "冷冷的": "语义：“冷”形容温度，与描写黑眼圈的语境不合。", "软软的": "语义：“软”形容质地，黑眼圈不能用来描述为“软”的。", "甜甜的": "搭配：“甜”不能用来形容“黑眼圈”，这一搭配不自然。"}, "sentence_index": 0, "correct_answer": "大大的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项改革大大地提高了效率。", "explanation": "这里的“大大地”是副词，表示程度很深，不是形容词“大大的”的“很大”义。"}, {"text": "我们大大地感谢你的帮助。", "explanation": "这里的“大大地”是副词，表示程度很深，不是形容词“大大的”的“很大”义。"}, {"text": "这次考试大大地减轻了我的压力。", "explanation": "这里的“大大地”是副词，表示程度很深，不是形容词“大大的”的“很大”义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大大的", "is_correct": true, "explanation": "正确答案。形容苹果树很大，符合句意。"}, {"text": "冷冷的", "is_correct": false, "explanation": "语义：“冷”形容温度，与描写苹果树的语境不合。"}, {"text": "硬硬的", "is_correct": false, "explanation": "语义：“硬”形容质地，不用来描述树的大小。"}, {"text": "薄薄的", "is_correct": false, "explanation": "搭配：“薄”形容扁平物体的厚度小，不能用来形容树。"}], "explanations": {"大大的": "正确答案。形容苹果树很大，符合句意。", "冷冷的": "语义：“冷”形容温度，与描写苹果树的语境不合。", "硬硬的": "语义：“硬”形容质地，不用来描述树的大小。", "薄薄的": "搭配：“薄”形容扁平物体的厚度小，不能用来形容树。"}, "sentence_index": 6, "correct_answer": "大大的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大大地松了一口气。", "explanation": "这里的“大大地”是副词，表示程度很深，不是形容词“大大的”的“很大”义。"}, {"text": "我们大大地减少了浪费。", "explanation": "这里的“大大地”是副词，表示程度很深，不是形容词“大大的”的“很大”义。"}, {"text": "这部电影大大地打动了我。", "explanation": "这里的“大大地”是副词，表示程度很深，不是形容词“大大的”的“很大”义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
