INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26756, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西或人跟着动起来。", "primary_collocate": null, "pronunciation": "dài dòng", "ipa": "tai⁵¹ tʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "妈妈的歌声带动孩子们跳起舞来。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大轮子带动小轮子一起转。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先跳起来，带动大家一起跳。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风带动树叶，树叶沙沙响。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流带动了河上的小木船。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "链条带动后轮，自行车就走了。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先做动作，带动全班同学一起做操。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐一响，就带动大家动起来了。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电机带动风扇转起来。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人拍手，带动了周围的人也拍手。", "target_word": "带动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带动了", "label": "体标"}, {"form": "带动着", "label": "体标"}, {"form": "带动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使物体或人跟着动起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26756, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带动", "is_correct": true, "explanation": "正确答案：带动（dài dòng），使东西或人跟着动起来。"}, {"text": "大洞", "is_correct": false, "explanation": "dà 与 dài 声调相同，只差韵母 -i，意思是“大洞”。"}, {"text": "耐冻", "is_correct": false, "explanation": "nài 与 dài 声母不同（n 与 d），声调相同，意思是“耐冻”。"}, {"text": "带痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t 与 d），声调相同，意思是“带着疼痛”。"}, {"text": "带通", "is_correct": false, "explanation": "tōng（第一声）与 dòng（第四声）声母和声调都不同，意思是“带通”，属于专业用语。"}], "explanations": {"带动": "正确答案：带动（dài dòng），使东西或人跟着动起来。", "大洞": "dà 与 dài 声调相同，只差韵母 -i，意思是“大洞”。", "耐冻": "nài 与 dài 声母不同（n 与 d），声调相同，意思是“耐冻”。", "带痛": "tòng 与 dòng 声母不同（t 与 d），声调相同，意思是“带着疼痛”。", "带通": "tōng（第一声）与 dòng（第四声）声母和声调都不同，意思是“带通”，属于专业用语。"}, "sentence_index": null, "correct_answer": "带动"}, "level_3": {"options": [{"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”与后半句“孩子们跳起舞来”矛盾，歌声阻止就跳不起来了。"}, {"text": "带动", "is_correct": true, "explanation": "“妈妈的歌声带动孩子们跳起舞来”表示歌声使孩子们跟着动起来，符合句意。"}, {"text": "禁止", "is_correct": false, "explanation": "搭配：“禁止”的主语应是有权力的人或规定，不能说“歌声禁止孩子们跳舞”。"}, {"text": "压制", "is_correct": false, "explanation": "语义：“压制”与“跳起舞来”的结果矛盾，压制住了就不会跳舞。"}], "explanations": {"阻止": "语义：“阻止”与后半句“孩子们跳起舞来”矛盾，歌声阻止就跳不起来了。", "带动": "“妈妈的歌声带动孩子们跳起舞来”表示歌声使孩子们跟着动起来，符合句意。", "禁止": "搭配：“禁止”的主语应是有权力的人或规定，不能说“歌声禁止孩子们跳舞”。", "压制": "语义：“压制”与“跳起舞来”的结果矛盾，压制住了就不会跳舞。"}, "sentence_index": 0, "correct_answer": "带动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人带动了那堆旧木头。", "explanation": "这里应该用〈搬走〉。带动表示使东西跟着动起来，不表示把东西搬走。"}, {"text": "他带动着行李箱走进车站。", "explanation": "这里应该用〈拖〉。带动不是人用手拉着东西走，人拉着行李走要用拖。"}, {"text": "他带动了那只生病的小猫。", "explanation": "这里应该用〈抱〉。带动是使东西或人跟着动起来，把小猫抱起来是用手托着带离原处，不能说“带动”小猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26756, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "带动", "is_correct": true, "explanation": "正确答案：带动（dài dòng），使东西或人跟着动起来。"}, {"text": "抬动", "is_correct": false, "explanation": "tái 与 dài 声母不同（t 与 d），声调也不同（第二声与第四声），意思是“抬起来移动”。"}, {"text": "大动", "is_correct": false, "explanation": "dà 与 dài 声调相同，只差韵母 -i，意思是“大幅度、大动作”。"}, {"text": "再动", "is_correct": false, "explanation": "zài 与 dài 声母不同（z 与 d），声调相同，意思是“再次行动”。"}], "explanations": {"带动": "正确答案：带动（dài dòng），使东西或人跟着动起来。", "抬动": "tái 与 dài 声母不同（t 与 d），声调也不同（第二声与第四声），意思是“抬起来移动”。", "大动": "dà 与 dài 声调相同，只差韵母 -i，意思是“大幅度、大动作”。", "再动": "zài 与 dài 声母不同（z 与 d），声调相同，意思是“再次行动”。"}, "sentence_index": null, "correct_answer": "带动"}, "level_3": {"options": [{"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”与“带动全班同学一起做操”的意思矛盾，老师不会忽视同学。"}, {"text": "带动", "is_correct": true, "explanation": "“老师先做动作，带动全班同学一起做操”表示老师带头使同学动起来，符合句意。"}, {"text": "阻拦", "is_correct": false, "explanation": "语义：“阻拦”与“一起做操”矛盾，阻拦同学就做不成操了。"}, {"text": "唆使", "is_correct": false, "explanation": "语域：“唆使”带贬义，多用于坏事，与老师带领做操的语境不合。"}], "explanations": {"忽视": "语义：“忽视”与“带动全班同学一起做操”的意思矛盾，老师不会忽视同学。", "带动": "“老师先做动作，带动全班同学一起做操”表示老师带头使同学动起来，符合句意。", "阻拦": "语义：“阻拦”与“一起做操”矛盾，阻拦同学就做不成操了。", "唆使": "语域：“唆使”带贬义，多用于坏事，与老师带领做操的语境不合。"}, "sentence_index": 6, "correct_answer": "带动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士每天细心带动了病历。", "explanation": "这里应该用〈整理〉。带动是使东西或人跟着动起来，不能用来说整理病历；整理病历要用“整理”。"}, {"text": "警察带动了这起案件。", "explanation": "这里应该用〈调查〉。带动不能用来说查案，查清事情要用调查。"}, {"text": "他认真带动这个问题。", "explanation": "这里应该用〈思考〉。带动表示使人或物跟着动，不能用来说对问题的思索，这里应该用思考。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根皮带了带动机器的齿轮转动。", "corrected_sentence": "这根皮带带动机器的齿轮转动。", "error_description": "“了”多余：“带动”前不能加“了”，应去掉，写成“这根皮带带动机器的齿轮转动”；若要表示完成，“了”应放在“带动”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "发动机带动了整台机器了转起来。", "corrected_sentence": "发动机带动了整台机器转起来。", "error_description": "多出一个“了”：“整台机器”与“转起来”之间不能再加“了”，应删去，写作“发动机带动了整台机器转起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
