INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26764, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "供电就是给电。", "primary_collocate": null, "pronunciation": "gōng diàn", "ipa": "kʊŋ⁵⁵ tjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "电站给小镇供电。", "target_word": "供电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨天，这里不能供电。", "target_word": "供电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太阳能板可以给房子供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上六点开始供电。", "target_word": "供电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们靠风力给村子供电。", "target_word": "供电", "complexity_tier": "T3", "furigana": "tā men kào fēng lì gěi cūn zi gōng diàn。", "sentence_source": "generated"}, {"text": "电站每天都给学校供电，不会停。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在修线路，所以今天不供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大电站为很多城市供电。", "target_word": "供电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台机器能给手机供电吗？", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的小房子靠太阳供电。", "target_word": "供电", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "供电了", "label": "体标"}, {"form": "供电系统", "label": "复合"}, {"form": "供電", "label": "繁体"}], "register": "中性", "sense_fingerprint": "给某个地方或东西送电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f88850e-622b-426b-b7db-fbf12d98ab7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "供电", "is_correct": true, "explanation": "正确答案。“供电”指给某地送电，电站给小镇送电，句意正合。"}, {"text": "供水", "is_correct": false, "explanation": "语义：电站供给的是电，不是水，句子的意思不通。"}, {"text": "耗电", "is_correct": false, "explanation": "搭配：“耗电”是消耗电能，不能用“给小镇”引出受益对象。"}, {"text": "输油", "is_correct": false, "explanation": "语义：输送的是油，与电站无关，不能表示给小镇送电。"}], "explanations": {"供电": "正确答案。“供电”指给某地送电，电站给小镇送电，句意正合。", "供水": "语义：电站供给的是电，不是水，句子的意思不通。", "耗电": "搭配：“耗电”是消耗电能，不能用“给小镇”引出受益对象。", "输油": "语义：输送的是油，与电站无关，不能表示给小镇送电。"}, "sentence_index": 0, "correct_answer": "供电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "居民们每天晚上都供电。", "explanation": "这里应该用〈用电〉。供电是供应方的工作，居民是用电的一方，不能说居民供电。"}, {"text": "学生们要少供电，出门要随手关灯。", "explanation": "这里应该用〈节电〉。节电是减少用电，学生是用电的一方，不能用“供电”；供电是供应方的工作。"}, {"text": "手机快没电了，我得去供电。", "explanation": "这里应该用〈充电〉。给手机补充电能用“充电”，“供电”指电站或电网向用户送电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供电", "is_correct": true, "explanation": "正确答案。修线路时要停止供电，“今天不供电”说的就是今天没有电。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：修线路与下雨没有因果关系，“所以今天不下雨”句意不通。"}, {"text": "充值", "is_correct": false, "explanation": "搭配：“充值”用于话费或账户，不能用来表示修线路时停止的服务。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与修线路无关，不能表示因为修线路而今天不做的事。"}], "explanations": {"供电": "正确答案。修线路时要停止供电，“今天不供电”说的就是今天没有电。", "下雨": "语义：修线路与下雨没有因果关系，“所以今天不下雨”句意不通。", "充值": "搭配：“充值”用于话费或账户，不能用来表示修线路时停止的服务。", "唱歌": "语义：唱歌与修线路无关，不能表示因为修线路而今天不做的事。"}, "sentence_index": 6, "correct_answer": "供电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水厂每天给居民供电一千吨水。", "explanation": "这里应该用〈供水〉。“供电”的对象是电力，不能用于水；“供水”才是向居民输送自来水。"}, {"text": "超市每天给居民供电蔬菜。", "explanation": "这里应该用〈供应〉。供电的对象是电力，不能用于蔬菜；“供应”可以带食物或物资。"}, {"text": "他每周给杂志供电。", "explanation": "这里应该用〈供稿〉。“供稿”是向报刊投稿，“供电”指向用户输送电力，不能用于杂志。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老电站每天都城市供电。", "corrected_sentence": "这座老电站每天都给城市供电。", "error_description": "“供电”前漏了引出受益对象的“给”，应说“给城市供电”，不能说“城市供电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电站给小镇了供电。", "corrected_sentence": "电站给小镇供电。", "error_description": "体标位置错误：“了”不能放在动词“供电”之前，应去掉，说“电站给小镇供电”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
