INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26766, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沙漠是地上有大片沙子和很少水的地方。", "primary_collocate": null, "pronunciation": "shā mò", "ipa": "ʂa˥ mo˥˩", "syllable_count": 2, "sentences": [{"text": "我们在电视上看到了一片大沙漠。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的沙子很多，水却很少。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去沙漠旅行时，我们带了很多水。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里没有河，也没有大树。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骆驼常常在沙漠里走很远的路。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳照在沙漠上，沙子热得烫脚。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想有一天去沙漠看星星。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠的风很大，沙子会打到脸上。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在沙漠中走了两天才看到水。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠很干，那里的人最爱喝水。", "target_word": "沙漠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "沙漠化", "label": "复合"}], "register": "中性", "sense_fingerprint": "有大片沙子、水很少的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙漠", "is_correct": true, "explanation": "“沙漠”指大片沙地，可以在电视上看到，与“一片大”的描述相符。"}, {"text": "指甲", "is_correct": false, "explanation": "语义：指甲很小，不能说“一片大指甲”，与“一片大”的描述矛盾。"}, {"text": "胡同", "is_correct": false, "explanation": "语义：胡同是狭窄的小巷，与“一片大”的描述矛盾。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是小件家具，不能说“一片大书桌”，与“一片大”的描述矛盾。"}], "explanations": {"沙漠": "“沙漠”指大片沙地，可以在电视上看到，与“一片大”的描述相符。", "指甲": "语义：指甲很小，不能说“一片大指甲”，与“一片大”的描述矛盾。", "胡同": "语义：胡同是狭窄的小巷，与“一片大”的描述矛盾。", "书桌": "语义：书桌是小件家具，不能说“一片大书桌”，与“一片大”的描述矛盾。"}, "sentence_index": 0, "correct_answer": "沙漠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋子里的沙漠慢慢融化，地上全是水。", "explanation": "这里应该用〈冰块〉。冰块会融化成水；沙漠是干燥的沙石地带，不会融化，这里的“沙漠”用法不对。"}, {"text": "袋子里装满了沙漠，我们拎着走了一路。", "explanation": "这里应该用〈沙子〉。沙子可以装进袋子，沙漠是地区，不能被装进袋子里。"}, {"text": "昨晚的沙漠刮倒了好几棵树。", "explanation": "这里应该用〈沙尘暴〉。沙尘暴是挟带沙尘的强风，能刮倒树；沙漠只是地区，不会刮树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙漠", "is_correct": true, "explanation": "“沙漠”是适合看星星的开阔地带，与“去……看星星”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是室内做饭的地方，看不到星星，与“看星星”的目的矛盾。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁在地下隧道中，看不到星空，与“看星星”的目的矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是厨房里储存食物的电器，里面看不到星星，与“看星星”的目的矛盾。"}], "explanations": {"沙漠": "“沙漠”是适合看星星的开阔地带，与“去……看星星”的语境相符。", "厨房": "语义：厨房是室内做饭的地方，看不到星星，与“看星星”的目的矛盾。", "地铁": "语义：地铁在地下隧道中，看不到星空，与“看星星”的目的矛盾。", "冰箱": "语义：冰箱是厨房里储存食物的电器，里面看不到星星，与“看星星”的目的矛盾。"}, "sentence_index": 6, "correct_answer": "沙漠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿极了，就跑去啃沙漠。", "explanation": "“啃”的对象应是食物，沙漠是地区，不能啃，这里的“沙漠”用法不对。"}, {"text": "我们每天驾驶沙漠去上学。", "explanation": "“驾驶”的对象应是车辆，沙漠不是交通工具，这里的“沙漠”用法不对。"}, {"text": "妹妹冷了，就把沙漠披在身上。", "explanation": "“披”的对象应是衣物或被子，沙漠不能披，这里的“沙漠”用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处是一大只沙漠，看不到尽头。", "corrected_sentence": "远处是一大片沙漠，看不到尽头。", "error_description": "“沙漠”的量词应该用“片”，写成“只”是错误的。“只”多用于动物，指一大片地面要用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于逃出了一沙漠。", "corrected_sentence": "他们终于逃出了一片沙漠。", "error_description": "“沙漠”前的量词漏掉了。“一”后面要接量词，“沙漠”的量词应是“片”，应写作“一片沙漠”，不能直接说“一沙漠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
