INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26768, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "有一点像，不是完全一样。", "primary_collocate": null, "pronunciation": "yǒu diǎn xiàng", "ipa": "jou²¹⁴ tjɛn²¹⁴ ɕjaŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这朵云有点像一只兔子。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟画的猫有点像老虎。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路的样子有点像他爷爷。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌有点像我小时候听过的那首。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子有点像碗，又比碗小。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的声音有点像歌星。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那栋楼的样子有点像一本打开的书。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字写出来有点像，要看清楚。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和他哥哥有点像，但眼睛不一样。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的脾气有点像他爸爸。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有点儿像", "label": "儿化"}], "register": "口语", "sense_fingerprint": "有一点像但不完全一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26768, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有点像", "is_correct": true, "explanation": "正确：本词是「有点像」，表示有一点像但不完全一样。"}, {"text": "有点香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是「有点香」。"}, {"text": "有点亮", "is_correct": false, "explanation": "liàng 与 xiàng 声母不同（l 与 x），意思是「有点亮」。"}, {"text": "有点想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是「有点想」。"}, {"text": "有点样", "is_correct": false, "explanation": "yàng 与 xiàng 声母不同（y 与 x），意思是「有点样子」。"}], "explanations": {"有点像": "正确：本词是「有点像」，表示有一点像但不完全一样。", "有点香": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是「有点香」。", "有点亮": "liàng 与 xiàng 声母不同（l 与 x），意思是「有点亮」。", "有点想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是「有点想」。", "有点样": "yàng 与 xiàng 声母不同（y 与 x），意思是「有点样子」。"}, "sentence_index": null, "correct_answer": "有点像"}, "level_3": {"options": [{"text": "有点像", "is_correct": true, "explanation": "正确：「有点像」表示有一点像，与「这朵云」和「一只兔子」的描述相符。"}, {"text": "养", "is_correct": false, "explanation": "搭配：云不能养兔子，「这朵云养一只兔子」搭配不当。"}, {"text": "吃", "is_correct": false, "explanation": "语义：云不会吃兔子，句子说不通。"}, {"text": "打", "is_correct": false, "explanation": "语义：云不会打兔子，「这朵云打一只兔子」说不通。"}], "explanations": {"有点像": "正确：「有点像」表示有一点像，与「这朵云」和「一只兔子」的描述相符。", "养": "搭配：云不能养兔子，「这朵云养一只兔子」搭配不当。", "吃": "语义：云不会吃兔子，句子说不通。", "打": "语义：云不会打兔子，「这朵云打一只兔子」说不通。"}, "sentence_index": 0, "correct_answer": "有点像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两首歌完全一样，有点像。", "explanation": "这里不能用〈有点像〉。它表示有一点像、不是完全相同，这句说的是完全相同，二者矛盾。"}, {"text": "这两片树叶一模一样，有点像。", "explanation": "这里不能用〈有点像〉。它表示有一点像，这句说的是完全相同，与之矛盾。"}, {"text": "这张卡片分毫不差，有点像。", "explanation": "这里不能用〈有点像〉。它表示有一点像，这句说的是没有任何差别的完全相同，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有点像", "is_correct": true, "explanation": "正确：「有点像」表示有一点像，与「那栋楼的样子」和「一本打开的书」的描述相符。"}, {"text": "认得", "is_correct": false, "explanation": "语义：「认得」指认识，「楼的样子认得一本书」说不通。"}, {"text": "借", "is_correct": false, "explanation": "配价：「借」需要能借东西的施事，「楼的样子借一本书」不成立。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」需要书写者，楼不能写书，句子说不通。"}], "explanations": {"有点像": "正确：「有点像」表示有一点像，与「那栋楼的样子」和「一本打开的书」的描述相符。", "认得": "语义：「认得」指认识，「楼的样子认得一本书」说不通。", "借": "配价：「借」需要能借东西的施事，「楼的样子借一本书」不成立。", "写": "语义：「写」需要书写者，楼不能写书，句子说不通。"}, "sentence_index": 6, "correct_answer": "有点像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个杯子毫无差别，有点像。", "explanation": "这里不能用〈有点像〉。它表示有一点像，这句说的是完全相同，与之矛盾。"}, {"text": "这张照片就是我本人，有点像。", "explanation": "这里不能用〈有点像〉。它表示有一点像，这句说的是同一个人，完全相同，与之矛盾。"}, {"text": "他和他哥哥是同一个人，有点像。", "explanation": "这里不能用〈有点像〉。它表示有一点像，这句说的是完全一样的人，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的字不有点像爸爸写的。", "corrected_sentence": "他的字有点像爸爸写的。", "error_description": "否定词多余：“有点像”是肯定形式，前面不能加“不”，应去掉“不”，写成“有点像爸爸写的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长大以后有点像了他爸爸。", "corrected_sentence": "他长大以后有点像他爸爸。", "error_description": "“了”多余：“有点像”后面直接接宾语时不加“了”，应去掉“了”，写成“有点像他爸爸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
