INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大地平平的，没有山，也没有高大的树林。", "primary_collocate": null, "pronunciation": "píng yuán", "ipa": "pʰiŋ˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "平原一眼看不到山。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这片平原一望无际，没有山也没有高树。", "target_word": "平原", "complexity_tier": "T3", "furigana": "zhè piàn píng yuán yī wàng wú jì，méi yǒu shān yě méi yǒu gāo shù。", "sentence_source": "generated"}, {"text": "平原上没有高树。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢在平原上骑车。", "target_word": "平原", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "平原上风很大，也没有树。", "target_word": "平原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走了一天，还是平原，看不到山。", "target_word": "平原", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小住在平原，没见过高山。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车在平原上走，窗外一直是平平的大地。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平原那么大，站着也能看到很远的地方。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里人第一次到平原，觉得天特别大。", "target_word": "平原", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片平原", "label": "量词"}, {"form": "平原地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "平坦开阔、无山无高树的大地（强调一望无际的平）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92b8e895-07d2-430a-a35a-f19f0da65d06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平原", "is_correct": true, "explanation": "正确答案。“平原一眼看不到山”符合平原没有山的特点。"}, {"text": "山区", "is_correct": false, "explanation": "语义：山区到处是山，与“一眼看不到山”矛盾。"}, {"text": "山谷", "is_correct": false, "explanation": "搭配：山谷是两山之间的低地，不能与“一眼看不到山”这样的说法搭配。"}, {"text": "高山", "is_correct": false, "explanation": "语义：高山本身就是山，不能说“高山一眼看不到山”。"}], "explanations": {"平原": "正确答案。“平原一眼看不到山”符合平原没有山的特点。", "山区": "语义：山区到处是山，与“一眼看不到山”矛盾。", "山谷": "搭配：山谷是两山之间的低地，不能与“一眼看不到山”这样的说法搭配。", "高山": "语义：高山本身就是山，不能说“高山一眼看不到山”。"}, "sentence_index": 0, "correct_answer": "平原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草地的尽头有一座平原。", "explanation": "量词“座”用于山、楼等，平原应用〈片〉。"}, {"text": "平原上的山峰一个接一个，连绵不断。", "explanation": "这里应该用〈山区〉。平原没有山，不能说平原上有连绵的山峰。"}, {"text": "他爬上平原，俯瞰整个城市。", "explanation": "这里应该用〈高塔〉。“爬上”指向高处，平原平坦，不能说爬上平原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平原", "is_correct": true, "explanation": "正确答案。“他从小住在平原，没见过高山”符合平原地区没有高山的情况。"}, {"text": "山村", "is_correct": false, "explanation": "语义：山村位于山中，住在那里常能看见高山，与“没见过高山”矛盾。"}, {"text": "峡谷", "is_correct": false, "explanation": "语义：峡谷两侧是山壁，住在峡谷的人不可能没见过高山。"}, {"text": "雪山", "is_correct": false, "explanation": "搭配：“住在”后一般接地点，不能说“住在雪山”，雪山是山峰，不适合居住。"}], "explanations": {"平原": "正确答案。“他从小住在平原，没见过高山”符合平原地区没有高山的情况。", "山村": "语义：山村位于山中，住在那里常能看见高山，与“没见过高山”矛盾。", "峡谷": "语义：峡谷两侧是山壁，住在峡谷的人不可能没见过高山。", "雪山": "搭配：“住在”后一般接地点，不能说“住在雪山”，雪山是山峰，不适合居住。"}, "sentence_index": 6, "correct_answer": "平原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋前长着一棵平原。", "explanation": "量词“棵”用于树木，平原应用〈片〉。"}, {"text": "翻过平原，就能看到大海。", "explanation": "这里应该用〈高山〉。“翻过”需要有障碍，平原没有山，不能说翻过平原。"}, {"text": "他潜入平原寻找贝壳。", "explanation": "这里应该用〈海底〉。“潜入”指进入水下，平原是陆地，不能说潜入平原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一只平原上露营。", "corrected_sentence": "我们在一片平原上露营。", "error_description": "量词错误：「只」用于动物等，不能计量平原，平原应用量词「片」。正确说法是「一片平原」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "牧民们赶着羊群走过一座平原。", "corrected_sentence": "牧民们赶着羊群走过一片平原。", "error_description": "量词错误：量词“座”用于山、楼等，平原应用“片”。正确说法是“一片平原”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "骤然", "is_correct": true, "explanation": "与“缓缓”形成反义：突然发生，与一点一点地渐变正好相反。"}, {"text": "轻轻", "is_correct": false, "explanation": "“轻轻”形容动作的轻柔，与渐变与否没有反义关系。"}, {"text": "悄悄", "is_correct": false, "explanation": "“悄悄”形容不让人察觉，与变化的快慢无关。"}, {"text": "偶尔", "is_correct": false, "explanation": "“偶尔”说的是频率，与渐变过程不构成反义。"}], "correct_answer": "骤然", "explanations": {"骤然": "与“缓缓”形成反义：突然发生，与一点一点地渐变正好相反。", "轻轻": "“轻轻”形容动作的轻柔，与渐变与否没有反义关系。", "悄悄": "“悄悄”形容不让人察觉，与变化的快慢无关。", "偶尔": "“偶尔”说的是频率，与渐变过程不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "骤然", "is_correct": true, "explanation": "与“缓缓”形成反义：突然发生，与一点一点地渐变正好相反。"}, {"text": "轻声", "is_correct": false, "explanation": "“轻声”说的是声音的大小，与变化的快慢无关。"}, {"text": "连连", "is_correct": false, "explanation": "“连连”表示接连不断，说的是次数，与渐变过程不构成反义。"}, {"text": "默默", "is_correct": false, "explanation": "“默默”形容不声不响，与变化的快慢无关。"}], "correct_answer": "骤然", "explanations": {"骤然": "与“缓缓”形成反义：突然发生，与一点一点地渐变正好相反。", "轻声": "“轻声”说的是声音的大小，与变化的快慢无关。", "连连": "“连连”表示接连不断，说的是次数，与渐变过程不构成反义。", "默默": "“默默”形容不声不响，与变化的快慢无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "慢慢地，一点点地动或者变化。", "primary_collocate": null, "pronunciation": "huǎn huǎn", "ipa": "xwan˨˩˦ xwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "月亮缓缓移动。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雾缓缓散开。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水位缓缓上升。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "云在天上缓缓地飘。", "target_word": "缓缓", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天缓缓黑了。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气温缓缓下降了。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的病缓缓好转，一个月后就出院了。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪缓缓落在屋顶上，也落在树上。", "target_word": "缓缓", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济缓缓恢复，人们的生活也好起来。", "target_word": "缓缓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳把冰缓缓化成了水。", "target_word": "缓缓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一点一点地移动或变化（强调渐变过程）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92b8e895-07d2-430a-a35a-f19f0da65d06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缓缓", "is_correct": true, "explanation": "“缓缓”表示一点一点地移动，与月亮慢慢移动的情景相合。"}, {"text": "一动不动", "is_correct": false, "explanation": "语义：“一动不动”表示静止，与“移动”的动态相矛盾。"}, {"text": "瞬间", "is_correct": false, "explanation": "语义：“瞬间”说转眼之间完成，与渐进的移动过程不符。"}, {"text": "倒着", "is_correct": false, "explanation": "搭配：月亮“倒着移动”不符合天体运行的常识，句子说不通。"}], "explanations": {"缓缓": "“缓缓”表示一点一点地移动，与月亮慢慢移动的情景相合。", "一动不动": "语义：“一动不动”表示静止，与“移动”的动态相矛盾。", "瞬间": "语义：“瞬间”说转眼之间完成，与渐进的移动过程不符。", "倒着": "搭配：月亮“倒着移动”不符合天体运行的常识，句子说不通。"}, "sentence_index": 0, "correct_answer": "缓缓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手机缓缓碎了一地。", "explanation": "“缓缓”表示逐渐发生的变化，碎裂是瞬间完成的，不能这样用。"}, {"text": "灯泡缓缓爆炸了。", "explanation": "爆炸是瞬间的，不是一点一点的变化，“缓缓”在这里不适用。"}, {"text": "杯子缓缓摔在地上。", "explanation": "摔落是瞬间的动作，“缓缓”表示的渐变过程在这里不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缓缓", "is_correct": true, "explanation": "“缓缓”表示病情一点一点地好转，与“一个月后出院”的过程相合。"}, {"text": "拼命", "is_correct": false, "explanation": "搭配：病情是自然好转的，不能「拼命」好转；「拼命」指人主动用力，与病情变化不合。"}, {"text": "骤然", "is_correct": false, "explanation": "语义：“骤然”说突然发生，与渐进的好转不合。"}, {"text": "故意", "is_correct": false, "explanation": "搭配：病不会「故意」好转，「故意」指有意识地去做，与病情的自然变化不合。"}], "explanations": {"缓缓": "“缓缓”表示病情一点一点地好转，与“一个月后出院”的过程相合。", "拼命": "搭配：病情是自然好转的，不能「拼命」好转；「拼命」指人主动用力，与病情变化不合。", "骤然": "语义：“骤然”说突然发生，与渐进的好转不合。", "故意": "搭配：病不会「故意」好转，「故意」指有意识地去做，与病情的自然变化不合。"}, "sentence_index": 6, "correct_answer": "缓缓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的封面缓缓是红色的。", "explanation": "“缓缓”只用于动作或变化的过程，“是红色”是静态状态，不能搭配。"}, {"text": "他的考试成绩一夜之间缓缓提高了。", "explanation": "“缓缓”表示一点点的渐变，“一夜之间”表示极短时间内完成，二者的时间义相互矛盾，成绩的变化不是逐步发生的。"}, {"text": "门缓缓被一脚踢开。", "explanation": "踢开是瞬间动作，不是一点一点的变化，“缓缓”不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外的雪缓缓的停了。", "corrected_sentence": "窗外的雪缓缓停了。", "error_description": "“缓缓”是副词，直接修饰动词，中间不加“的”；错写成“缓缓的停”，应为“缓缓停了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜色很缓缓降临，天边渐渐暗了。", "corrected_sentence": "夜色缓缓降临，天边渐渐暗了。", "error_description": "“缓缓”是副词，本身已表示渐进的慢速，不能再受“很”修饰；错写成“很缓缓降临”，应删去“很”，为“缓缓降临”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡无光", "is_correct": true, "explanation": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”形容空间的宽度，与光彩的明暗无关，不是反义词。"}, {"text": "潮湿", "is_correct": false, "explanation": "“潮湿”形容含水分多的状态，与光亮没有对立关系。"}, {"text": "温热", "is_correct": false, "explanation": "“温热”说的是温度，与“光彩闪耀”不构成反义。"}], "correct_answer": "暗淡无光", "explanations": {"暗淡无光": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。", "狭窄": "“狭窄”形容空间的宽度，与光彩的明暗无关，不是反义词。", "潮湿": "“潮湿”形容含水分多的状态，与光亮没有对立关系。", "温热": "“温热”说的是温度，与“光彩闪耀”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗淡无光", "is_correct": true, "explanation": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。"}, {"text": "沉重", "is_correct": false, "explanation": "“沉重”形容重量或心情，与光彩的明暗无关，不是反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与光亮没有对立关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”形容反应慢，与“光彩闪耀”不构成反义。"}], "correct_answer": "暗淡无光", "explanations": {"暗淡无光": "与“熠熠生辉”形成反义：光彩暗淡，没有光亮，正好相反。", "沉重": "“沉重”形容重量或心情，与光彩的明暗无关，不是反义词。", "柔软": "“柔软”形容质地，与光亮没有对立关系。", "迟钝": "“迟钝”形容反应慢，与“光彩闪耀”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "亮闪闪的，像星星一样发光。", "primary_collocate": null, "pronunciation": "yì yì shēng huī", "ipa": "i˥˩ i˥˩ ʂɤŋ˥ xweɪ˥", "syllable_count": 4, "sentences": [{"text": "夜里的海面熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小河里的水熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的银首饰在灯下熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T3", "furigana": "tā de yín shǒushi zài dēng xià yì yì shēng huī", "sentence_source": "generated"}, {"text": "孩子的眼睛像星星，熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河面上的灯光熠熠生辉，像星星一样。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了雪，树上的冰熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王冠上的宝石在灯下熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草地上的露水在早上熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "擦过以后，银杯熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把铜钟擦得熠熠生辉。", "target_word": "熠熠生辉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "成语：亮闪闪、像星星般发光（强调一闪一闪）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92b8e895-07d2-430a-a35a-f19f0da65d06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熠熠生辉", "is_correct": true, "explanation": "形容夜里海面反射出一闪一闪的亮光，与“夜里”的情境相合。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：夜里的海面不会是“滚烫”的，这样说与句中的情境相冲突。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：海面是水体，不能用“干燥”来形容。"}, {"text": "光秃秃", "is_correct": false, "explanation": "体貌：“光秃秃”多用于草木、山地的外观，不能用于海面。"}], "explanations": {"熠熠生辉": "形容夜里海面反射出一闪一闪的亮光，与“夜里”的情境相合。", "滚烫": "语义：夜里的海面不会是“滚烫”的，这样说与句中的情境相冲突。", "干燥": "语义：海面是水体，不能用“干燥”来形容。", "光秃秃": "体貌：“光秃秃”多用于草木、山地的外观，不能用于海面。"}, "sentence_index": 0, "correct_answer": "熠熠生辉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜晚的虫鸣熠熠生辉，很动听。", "explanation": "「熠熠生辉」指光亮，虫鸣是声音，不能这样形容。"}, {"text": "厨房里的饭香熠熠生辉。", "explanation": "「熠熠生辉」只形容光亮，饭香是气味，这里用错了。"}, {"text": "这碗粥的温度熠熠生辉。", "explanation": "温度是冷热的感受，不是光，「熠熠生辉」在这里不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熠熠生辉", "is_correct": true, "explanation": "形容宝石在灯下闪闪发光，与王冠的华贵形象相合。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：王冠上的宝石与“破旧”的意思矛盾，句子要表达的是光彩。"}, {"text": "粗糙", "is_correct": false, "explanation": "体貌：表面粗糙的宝石不会在灯下闪光，这样描写与句意不符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”与“在灯下”的干亮景象相矛盾。"}], "explanations": {"熠熠生辉": "形容宝石在灯下闪闪发光，与王冠的华贵形象相合。", "破旧": "语义：王冠上的宝石与“破旧”的意思矛盾，句子要表达的是光彩。", "粗糙": "体貌：表面粗糙的宝石不会在灯下闪光，这样描写与句意不符。", "潮湿": "语义：“潮湿”与“在灯下”的干亮景象相矛盾。"}, "sentence_index": 6, "correct_answer": "熠熠生辉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的叹息熠熠生辉，让屋子里安静下来。", "explanation": "「熠熠生辉」指光亮，叹息是声音，这里用错了对象。"}, {"text": "山谷里的回声熠熠生辉。", "explanation": "回声是声音，「熠熠生辉」描写的是光彩，属于错用。"}, {"text": "他的心跳熠熠生辉，很有力。", "explanation": "心跳是身体的节律，看不见，「熠熠生辉」只用于光亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖面上的月光把熠熠生辉，很美。", "corrected_sentence": "湖面上的月光熠熠生辉，很美。", "error_description": "“把”字句误用：「熠熠生辉」是不及物的形容性词语，不能放在“把”后作动词，应说「湖面上的月光熠熠生辉，很美」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车灯照过，玻璃窗很熠熠生辉。", "corrected_sentence": "车灯照过，玻璃窗熠熠生辉。", "error_description": "程度副词“很”不能修饰「熠熠生辉」这类固定四字形容语，应说「车灯照过，玻璃窗熠熠生辉」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
