INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不同的东西混在一起，分不开了。", "primary_collocate": null, "pronunciation": "jiāo zhī", "ipa": "tɕjɑʊ˥˥ ʈʂʅ˥˥", "syllable_count": 2, "sentences": [{"text": "梦和现实交织在一起，我分不清了。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心里，爱和恨交织在一起。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音和灯光交织成一片。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心情很复杂，高兴和难过交织着。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花香和茶香交织在一起，很好闻。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去和现在在这里交织，分不开了。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼里，泪水和笑容交织着。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上的云和雾交织在一起，看不清山。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的故事里，真话和假话交织在一起。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "痛苦和幸福交织在她的生活里。", "target_word": "交织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交织着", "label": "体标"}, {"form": "交织了", "label": "体标"}, {"form": "交织过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不同的东西混在一起而难以分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5f59174-23ab-4b8b-9546-74dc82c078e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：交织 jiāo zhī，意思是不同的东西混在一起，分不开。"}, {"text": "脚趾", "is_correct": false, "explanation": "脚趾 jiǎozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是脚趾。"}, {"text": "角质", "is_correct": false, "explanation": "角质 jiǎozhì（第三声、第四声）与 jiāo zhī（第一声、第一声）声调不同，意思是角质层。"}, {"text": "校址", "is_correct": false, "explanation": "校址 jiàozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是学校的地址。"}, {"text": "姜汁", "is_correct": false, "explanation": "姜汁 jiāngzhī 的韵母（-ang）与 jiāo 的韵母（-ao）不同，意思是姜的汁液。"}], "explanations": {"交织": "正确：交织 jiāo zhī，意思是不同的东西混在一起，分不开。", "脚趾": "脚趾 jiǎozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是脚趾。", "角质": "角质 jiǎozhì（第三声、第四声）与 jiāo zhī（第一声、第一声）声调不同，意思是角质层。", "校址": "校址 jiàozhǐ 的两个音节声调都与 jiāo zhī 不同，意思是学校的地址。", "姜汁": "姜汁 jiāngzhī 的韵母（-ang）与 jiāo 的韵母（-ao）不同，意思是姜的汁液。"}, "sentence_index": null, "correct_answer": "交织"}, "level_3": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：“交织”表示梦与现实混在一起、难以分开，与“我分不清了”相符。"}, {"text": "对照", "is_correct": false, "explanation": "语义：“对照”指放在一起比较异同，与“我分不清了”不符。"}, {"text": "区分", "is_correct": false, "explanation": "语义：“区分”指分清差异，与“我分不清了”正相反。"}, {"text": "分开", "is_correct": false, "explanation": "搭配：“分开”与“在一起”搭配矛盾，不能说“分开在一起”。"}], "explanations": {"交织": "正确：“交织”表示梦与现实混在一起、难以分开，与“我分不清了”相符。", "对照": "语义：“对照”指放在一起比较异同，与“我分不清了”不符。", "区分": "语义：“区分”指分清差异，与“我分不清了”正相反。", "分开": "搭配：“分开”与“在一起”搭配矛盾，不能说“分开在一起”。"}, "sentence_index": 0, "correct_answer": "交织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰块在热水里交织成了水。", "explanation": "这里应该用〈融化〉。冰块变成水是融化；交织指不同的东西混在一起，不表示固体变为液体。"}, {"text": "茶水在锅里交织。", "explanation": "这里应该用〈沸腾〉。茶水受热翻滚是沸腾，交织不表示液体受热翻滚。"}, {"text": "他的手机在桌上交织。", "explanation": "这里应该用〈震动〉。手机在桌上持续颤动是震动；交织指不同的东西混在一起，不用来描述物体的振动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26780, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：交织 jiāo zhī，意思是不同的东西混在一起，分不开。"}, {"text": "娇妻", "is_correct": false, "explanation": "娇妻 jiāoqī 的第二音节声母 q 与 zh 不同，意思是受宠爱的妻子。"}, {"text": "胶质", "is_correct": false, "explanation": "胶质 jiāozhì 的第二音节声调为第四声，与 zhī 不同，意思是胶状物质。"}, {"text": "教职", "is_correct": false, "explanation": "教职 jiàozhí 的两个音节声调都与 jiāo zhī 不同，意思是教学工作的职务。"}, {"text": "胶纸", "is_correct": false, "explanation": "胶纸 jiāozhǐ 的第二音节声调为第三声，与 zhī 不同，意思是带胶的纸。"}], "explanations": {"交织": "正确：交织 jiāo zhī，意思是不同的东西混在一起，分不开。", "娇妻": "娇妻 jiāoqī 的第二音节声母 q 与 zh 不同，意思是受宠爱的妻子。", "胶质": "胶质 jiāozhì 的第二音节声调为第四声，与 zhī 不同，意思是胶状物质。", "教职": "教职 jiàozhí 的两个音节声调都与 jiāo zhī 不同，意思是教学工作的职务。", "胶纸": "胶纸 jiāozhǐ 的第二音节声调为第三声，与 zhī 不同，意思是带胶的纸。"}, "sentence_index": null, "correct_answer": "交织"}, "level_3": {"options": [{"text": "交织", "is_correct": true, "explanation": "正确：“交织着”表示泪水和笑容混在一起，与“着”搭配自然。"}, {"text": "沉淀", "is_correct": false, "explanation": "搭配：“沉淀”多用于液体中的颗粒，笑容和泪水不能沉淀。"}, {"text": "分隔", "is_correct": false, "explanation": "语义：“分隔”指隔开，与“泪水和笑容”混在一起相反。"}, {"text": "隔绝", "is_correct": false, "explanation": "语义：“隔绝”指彼此断开、不相通，与“交织”的相互穿插矛盾。"}], "explanations": {"交织": "正确：“交织着”表示泪水和笑容混在一起，与“着”搭配自然。", "沉淀": "搭配：“沉淀”多用于液体中的颗粒，笑容和泪水不能沉淀。", "分隔": "语义：“分隔”指隔开，与“泪水和笑容”混在一起相反。", "隔绝": "语义：“隔绝”指彼此断开、不相通，与“交织”的相互穿插矛盾。"}, "sentence_index": 6, "correct_answer": "交织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架上的书交织得整整齐齐。", "explanation": "这里应该用〈排列〉。书整齐地摆放是排列；交织指不同的东西混在一起，不表示摆放有序。"}, {"text": "这只猫在窗台上交织。", "explanation": "这里应该用〈打盹〉。猫在窗台上小睡是打盹；交织指不同的东西混在一起，不用来描述动物的睡眠。"}, {"text": "孩子们在草地上交织。", "explanation": "这里应该用〈嬉戏〉。孩子们玩耍是嬉戏；交织不用来描述人的游玩动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喜悦和担忧交织他心里。", "corrected_sentence": "喜悦和担忧交织在他心里。", "error_description": "错误形式：“交织他心里”。正确形式：“交织在他心里”。表示处所时要用“在”引出，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两种颜色交织一幅画。", "corrected_sentence": "两种颜色交织成一幅画。", "error_description": "错误形式：“交织一幅画”。正确形式：“交织成一幅画”。“交织”后面要用“成”引出结果，再接宾语“一幅画”，不能直接带宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f54d054-d37c-4297-9a6c-5421c342f1c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "像小鸟一样跳起来飞。", "primary_collocate": null, "pronunciation": "fēi yuè", "ipa": "fei˥ yɛ˥˩", "syllable_count": 2, "sentences": [{"text": "小鸟从树枝飞跃到另一棵树上。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只麻雀飞跃过矮墙。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟轻轻一跳，飞跃到了窗台上。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟看到猫，马上飞跃到高处。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞跃过小河，到了对岸。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸽子飞跃过篱笆，落进院子里。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麻雀飞跃上屋顶，叽叽地叫。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟从地上飞跃到桌子上吃米。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿飞跃过水沟，不怕弄湿脚。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞跃过石头，往树林里去了。", "target_word": "飞跃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞跃了", "label": "体标"}, {"form": "飞跃过", "label": "体标"}, {"form": "飛躍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "本义：小鸟跳起来飞过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6965bde7-6897-4797-b880-940007ee84e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞跃", "is_correct": true, "explanation": "飞跃指小鸟跳起来飞过去，与“从树枝到另一棵树上”的动作相符。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：漂浮指随水或空气浮动，不能表示小鸟有目的地移动到另一棵树。"}, {"text": "游", "is_correct": false, "explanation": "语义：游指在水中或水面行进，与小鸟在树间移动的情景不符。"}, {"text": "跑", "is_correct": false, "explanation": "语义：跑指用腿快速行进，句中的小鸟是飞到另一棵树上，“跑到另一棵树上”句意不通。"}], "explanations": {"飞跃": "飞跃指小鸟跳起来飞过去，与“从树枝到另一棵树上”的动作相符。", "漂浮": "语义：漂浮指随水或空气浮动，不能表示小鸟有目的地移动到另一棵树。", "游": "语义：游指在水中或水面行进，与小鸟在树间移动的情景不符。", "跑": "语义：跑指用腿快速行进，句中的小鸟是飞到另一棵树上，“跑到另一棵树上”句意不通。"}, "sentence_index": 0, "correct_answer": "飞跃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头太重了，飞跃不起来。", "explanation": "这里应该用〈搬〉。飞跃指小鸟跳起来飞过去，石头不会飞，应说“搬不起来”。"}, {"text": "小鸟在天空中飞跃了一整天。", "explanation": "这里应该用〈飞行〉。飞行指持续地在空中飞，飞跃指一下子跳过去，不能说飞了一整天。"}, {"text": "他在大街上飞跃了一圈，见人就打招呼。", "explanation": "这里应该用〈走〉。飞跃指像小鸟一样跳起来飞过去，不能用来说在街上走一圈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞跃", "is_correct": true, "explanation": "飞跃指麻雀跳起来飞过去，与“上屋顶”的动作相符。"}, {"text": "跌", "is_correct": false, "explanation": "语义：跌指摔落，与麻雀主动跳上屋顶的动作相反。"}, {"text": "滚", "is_correct": false, "explanation": "语义：滚指翻转打滚，不能表示麻雀跳上屋顶。"}, {"text": "滑", "is_correct": false, "explanation": "搭配：滑多指在平面上滑行，不说鸟“滑上屋顶”。"}], "explanations": {"飞跃": "飞跃指麻雀跳起来飞过去，与“上屋顶”的动作相符。", "跌": "语义：跌指摔落，与麻雀主动跳上屋顶的动作相反。", "滚": "语义：滚指翻转打滚，不能表示麻雀跳上屋顶。", "滑": "搭配：滑多指在平面上滑行，不说鸟“滑上屋顶”。"}, "sentence_index": 6, "correct_answer": "飞跃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在公路上飞跃，很快就到了。", "explanation": "这里应该用〈飞驰〉。飞驰指快速行驶，飞跃指跳跃式越过，不用于汽车在路上行驶。"}, {"text": "孩子在操场上飞跃，跑得很快。", "explanation": "这里应该用〈飞奔〉。飞奔指快跑，飞跃指跳起来越过，不用于一般的快跑。"}, {"text": "树叶从树上飞跃下来，落在地上。", "explanation": "这里应该用〈飘落〉。飘落指轻轻地落下，飞跃指一下子跳过去，不说树叶飞跃下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只麻雀从屋顶飞跃了过院墙，落在树上。", "corrected_sentence": "一只麻雀从屋顶飞跃过院墙，落在树上。", "error_description": "错误在多出的“了”：“了”不能放在“过”之前，应删去“了”，说“飞跃过院墙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟飞跃了过小河，到了对岸。", "corrected_sentence": "小鸟飞跃过了小河，到了对岸。", "error_description": "错误在“了”和“过”的顺序。应说“飞跃过了”，“过”紧跟动词，“了”放在后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
