INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "讲一个英雄或伟大故事的长诗。", "primary_collocate": null, "pronunciation": "shǐ shī", "ipa": "ʂɻ̩˨˩˦ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "史诗是一种很长的诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常给我讲史诗里的故事。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首史诗讲的是一位国王的故事。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用三天读完了一部史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "史诗的主人公通常是英雄。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的图书馆有很多史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手在台上唱着一首史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部史诗里有龙，也有勇敢的战士。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在课堂上讨论这部史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位诗人想写一首关于海的史诗。", "target_word": "史诗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "史詩", "label": "繁体"}, {"form": "英雄史诗", "label": "复合"}, {"form": "部", "label": "量词"}, {"form": "首", "label": "量词"}], "register": "中性", "sense_fingerprint": "史诗|英雄故事的长诗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92b8e895-07d2-430a-a35a-f19f0da65d06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "史诗", "is_correct": true, "explanation": "正确答案。史诗（shǐ shī）指讲述英雄或伟大故事的长诗。"}, {"text": "石狮", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是石头做的狮子。"}, {"text": "试试", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，第二音节 shi 读轻声，意思是试一下。"}, {"text": "死尸", "is_correct": false, "explanation": "sǐ 与 shǐ 的声母不同（s 与 sh），声调相同，意思是尸体。"}, {"text": "史书", "is_correct": false, "explanation": "shū 与 shī 韵母不同（ū 与 ī），其余相同，意思是记载历史的书。"}], "explanations": {"史诗": "正确答案。史诗（shǐ shī）指讲述英雄或伟大故事的长诗。", "石狮": "shí（第二声）与 shǐ（第三声）声调不同，后一音节相同，意思是石头做的狮子。", "试试": "shì（第四声）与 shǐ（第三声）声调不同，第二音节 shi 读轻声，意思是试一下。", "死尸": "sǐ 与 shǐ 的声母不同（s 与 sh），声调相同，意思是尸体。", "史书": "shū 与 shī 韵母不同（ū 与 ī），其余相同，意思是记载历史的书。"}, "sentence_index": null, "correct_answer": "史诗"}, "level_3": {"options": [{"text": "史诗", "is_correct": true, "explanation": "正确答案。“史诗是一种很长的诗”，指讲述英雄故事的长篇叙事诗。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是散文体的叙事作品，不是诗，与“一种很长的诗”不符。"}, {"text": "散文", "is_correct": false, "explanation": "语义：散文不是诗体，与“一种很长的诗”的说法冲突。"}, {"text": "日记", "is_correct": false, "explanation": "搭配：“一种很长的诗”不能与“日记”搭配，日记是私人的日常记录。"}], "explanations": {"史诗": "正确答案。“史诗是一种很长的诗”，指讲述英雄故事的长篇叙事诗。", "小说": "语义：小说是散文体的叙事作品，不是诗，与“一种很长的诗”不符。", "散文": "语义：散文不是诗体，与“一种很长的诗”的说法冲突。", "日记": "搭配：“一种很长的诗”不能与“日记”搭配，日记是私人的日常记录。"}, "sentence_index": 0, "correct_answer": "史诗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的汤里加了一点史诗。", "explanation": "这里把“史诗”当成了食材，词义不符。史诗是叙事长诗，不能加进汤里。"}, {"text": "他买了一只史诗。", "explanation": "量词“只”用于单个动物，不能用来计量史诗；这里应该用〈部〉或〈首〉。"}, {"text": "记者每天都写一首史诗。", "explanation": "这里应该用〈新闻〉。新闻报道的是当天的事实，史诗是长篇叙事诗，不能当作每日新闻来写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26786, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "史诗", "is_correct": true, "explanation": "正确答案。史诗（shǐ shī）指讲述英雄或伟大故事的长诗。"}, {"text": "时事", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是时事（当前发生的事）。"}, {"text": "实事", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是实际的事情。"}, {"text": "世事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是世上的事情。"}, {"text": "失事", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是发生事故。"}], "explanations": {"史诗": "正确答案。史诗（shǐ shī）指讲述英雄或伟大故事的长诗。", "时事": "shí（第二声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是时事（当前发生的事）。", "实事": "shí（第二声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是实际的事情。", "世事": "shì（第四声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是世上的事情。", "失事": "shī（第一声）与 shǐ（第三声）声调不同，后一音节 shì 与 shī 也不同，意思是发生事故。"}, "sentence_index": null, "correct_answer": "史诗"}, "level_3": {"options": [{"text": "史诗", "is_correct": true, "explanation": "正确答案。“歌手在台上唱着一首史诗”，指演唱讲述英雄故事的长诗。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：说明书是产品的使用说明，不是可以演唱的诗，与“唱着”不相符。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单记录的是费用，不是诗，不能用来演唱。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱记录做菜的步骤，不是诗，不能拿来演唱。"}], "explanations": {"史诗": "正确答案。“歌手在台上唱着一首史诗”，指演唱讲述英雄故事的长诗。", "说明书": "语义：说明书是产品的使用说明，不是可以演唱的诗，与“唱着”不相符。", "账单": "语义：账单记录的是费用，不是诗，不能用来演唱。", "食谱": "语义：食谱记录做菜的步骤，不是诗，不能拿来演唱。"}, "sentence_index": 6, "correct_answer": "史诗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一首史诗煮熟吃了。", "explanation": "语义：史诗是诗作，不是食物，不能煮熟来吃。"}, {"text": "这把椅子是一部史诗。", "explanation": "类别错误：椅子是家具，不是诗作，不能说“是一部史诗”。"}, {"text": "书桌上摆着一把史诗。", "explanation": "量词“把”用于有柄的器具，史诗应用〈部〉或〈首〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷每晚给我念一个史诗。", "corrected_sentence": "爷爷每晚给我念一首史诗。", "error_description": "量词错误：“史诗”是诗作，应用量词“首”或“部”，不能用“个”。正确说法是“一首史诗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校组织同学们朗读一篇史诗。", "corrected_sentence": "学校组织同学们朗读一首史诗。", "error_description": "量词错误：“篇”用于文章，“史诗”是诗作，应用量词“首”或“部”。正确说法是“一首史诗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
