INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体动起来带的能量。", "primary_collocate": null, "pronunciation": "dòng néng", "ipa": "tʊŋ˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小球动起来，就有动能。", "target_word": "动能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "车开得越快，动能越大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风吹着风车转，风车得到了动能。", "target_word": "动能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车下坡时，车的动能越来越大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动能大的东西，撞到人会很疼。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石头从山上滚下来，动能很大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水流有很大的动能，推动了小水车。", "target_word": "动能", "complexity_tier": "T3", "furigana": "shuǐliú yǒu hěn dà de dòngnéng, tuīdòng le xiǎo shuǐchē.", "sentence_source": "generated"}, {"text": "球停了，球的动能就没有了。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑步的时候，我的身体有动能。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩跑得快，动能比走路时大。", "target_word": "动能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西动起来所带的能量，通俗说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c7e75e3-72ef-41eb-a7d0-3ec13fec9d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动能", "is_correct": true, "explanation": "正确。小球运动起来，就具有动能。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会因为运动而产生，“动起来就有颜色”与事实不符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：小球动起来不会产生味道，这个说法不合理。"}, {"text": "疼痛", "is_correct": false, "explanation": "配价：“疼痛”需要有感觉的主体，小球没有感觉，不能说“就有疼痛”。"}], "explanations": {"动能": "正确。小球运动起来，就具有动能。", "颜色": "语义：颜色不会因为运动而产生，“动起来就有颜色”与事实不符。", "味道": "语义：小球动起来不会产生味道，这个说法不合理。", "疼痛": "配价：“疼痛”需要有感觉的主体，小球没有感觉，不能说“就有疼痛”。"}, "sentence_index": 0, "correct_answer": "动能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆电动车的电池里有很多动能。", "explanation": "这里应该用〈能量〉。电池里储存的是化学能，动能指运动物体的能量，不能说电池里有很多动能。"}, {"text": "我跑步的速度很快，动能也很快。", "explanation": "这里应该用〈速率〉。动能是能量的大小，只能说大或小，表示运动快慢的量要用速率，不能说动能快。"}, {"text": "这碗热汤的动能很大，喝了很暖和。", "explanation": "这里应该用〈热量〉。热汤的热度来自热量，动能只能表示运动物体的能量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动能", "is_correct": true, "explanation": "正确。水流具有动能，所以能推动小水车。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度本身不能推动物体，句中“推动了小水车”需要能量来承担。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状是事物的外观，不能推动小水车，句中“推动”需要能量。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能直接推动小水车，这里的“推动”需要能量。"}], "explanations": {"动能": "正确。水流具有动能，所以能推动小水车。", "温度": "语义：温度本身不能推动物体，句中“推动了小水车”需要能量来承担。", "形状": "语义：形状是事物的外观，不能推动小水车，句中“推动”需要能量。", "声音": "语义：声音不能直接推动小水车，这里的“推动”需要能量。"}, "sentence_index": 6, "correct_answer": "动能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑了一个小时，动能还是很好。", "explanation": "这里应该用〈体力〉。动能指运动物体的能量，跑步后人还有没有力气要用体力。"}, {"text": "这杯水的动能很高，烫得不能喝。", "explanation": "这里应该用〈温度〉。水的冷热要用温度来说，动能指运动物体的能量。"}, {"text": "这座山的动能很高，有三千米。", "explanation": "这里应该用〈高度〉。山是静止的，没有动能，说山的高低要用高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他抛出去的铅球有很长的动能。", "corrected_sentence": "他抛出去的铅球有很大的动能。", "error_description": "形容词搭配错误：“动能”说的是能量的大小，应说“很大的动能”，不能用“长”来形容。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小球从桌上滚落，获得了一只动能。", "corrected_sentence": "小球从桌上滚落，获得了一点动能。", "error_description": "量词错误：“动能”是抽象的量，数量常用“点”来计量；“只”多用于动物或单件器物，不用于抽象的能量。错误在于量词“只”，应为“一点动能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
