INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西弄成碎末或粉末。", "primary_collocate": null, "pronunciation": "niǎn mó", "ipa": "njɛn˨˩˦ mwo˧˥", "syllable_count": 2, "sentences": [{"text": "她用小石臼碾磨芝麻，香味很浓。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些盐粒碾磨得更细一点。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用工具碾磨干辣椒，做辣椒粉。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他碾磨过茶叶，会做抹茶。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别把种子碾磨得太碎。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头太硬，很难碾磨成粉末。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药片太大，请碾磨成粉再喝。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有人在碾磨胡椒。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小机器专门用来碾磨香料。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人把豆子放在石碾上碾磨。", "target_word": "碾磨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碾磨了", "label": "完成体"}, {"form": "碾磨着", "label": "持续体"}, {"form": "碾磨过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把香料、种子、石头等弄成碎末或粉末", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摘", "is_correct": false, "explanation": "语义：摘是采下果实或叶子，不能用小石臼完成。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮需要锅和水，小石臼不能用来煮芝麻。"}, {"text": "碾磨", "is_correct": true, "explanation": "碾磨：用石臼把芝麻压碎磨成粉，与“香味很浓”的结果相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与固体的芝麻搭配。"}], "explanations": {"摘": "语义：摘是采下果实或叶子，不能用小石臼完成。", "煮": "语义：煮需要锅和水，小石臼不能用来煮芝麻。", "碾磨": "碾磨：用石臼把芝麻压碎磨成粉，与“香味很浓”的结果相符。", "喝": "搭配：“喝”不能与固体的芝麻搭配。"}, "sentence_index": 0, "correct_answer": "碾磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把剪刀钝了，要碾磨一下才好用。", "explanation": "这里应该用〈磨〉。磨剪刀是使刃口变锋利，碾磨是把香料、种子压成粉末，剪刀不能这样处理。"}, {"text": "压路机把路面碾磨得很平整。", "explanation": "这里应该用〈碾压〉。碾压指用重物滚压使路面平整，碾磨指压成粉末，路面不会变成粉末。"}, {"text": "他碾磨过茶叶的历史。", "explanation": "这里应该用〈研究〉。研究可用于历史、问题，碾磨只能用于把实物压成粉末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切", "is_correct": false, "explanation": "语义：切只能把药片切成块，不能磨成细粉。"}, {"text": "碾磨", "is_correct": true, "explanation": "碾磨：压碎磨成粉，才能“再喝”，与“药片太大”的语境相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬只能把药片咬碎成块，不能使其变成粉末。"}, {"text": "站", "is_correct": false, "explanation": "配价：站是不及物动词，不能带宾语“药片”，也不能用于此结构。"}], "explanations": {"切": "语义：切只能把药片切成块，不能磨成细粉。", "碾磨": "碾磨：压碎磨成粉，才能“再喝”，与“药片太大”的语境相符。", "咬": "语义：咬只能把药片咬碎成块，不能使其变成粉末。", "站": "配价：站是不及物动词，不能带宾语“药片”，也不能用于此结构。"}, "sentence_index": 6, "correct_answer": "碾磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶用擀面杖把面团碾磨成薄饼。", "explanation": "这里应该用〈擀〉。擀是用擀面杖把面团压成薄饼，碾磨是把东西压成粉末。"}, {"text": "不小心把水碾磨了。", "explanation": "这里应该用〈泼〉。水是液体，不能碾磨成粉，应说“泼”或“洒”。"}, {"text": "工人用砂纸把铁器碾磨得很光亮。", "explanation": "这里应该用〈抛光〉。抛光是使表面光滑发亮，碾磨是把东西压成粉末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用研钵把花椒碾磨了成粉。", "corrected_sentence": "妈妈用研钵把花椒碾磨成粉。", "error_description": "“了”位置错误：「碾磨了成粉」中“了”插在结果补语“成”之前，应去掉，正确为「碾磨成粉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前碾磨着花椒，味道很香。", "corrected_sentence": "我以前碾磨过花椒，味道很香。", "error_description": "“着”用错。“以前”表示过去的经历，应用经历体标记“过”；“着”表示动作持续，与“以前”矛盾。正确形式为“碾磨过花椒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然力是指大自然中存在的力量，比如风、雨水和太阳的热。", "primary_collocate": null, "pronunciation": "zì rán lì", "ipa": "tsɨ˥˩ ʐan˧˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "大风和大雨都是自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳的热是一种自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然力可以让风车转起来。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里的水一直流，也是自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的石头被自然力慢慢磨小了。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该尊重自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然力让种子发芽，长成大树。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，自然力很大。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人不能完全控制自然力。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人靠自然力晒盐。", "target_word": "自然力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大自然中的力量，如风、雨水、太阳的热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6965bde7-6897-4797-b880-940007ee84e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然力", "is_correct": true, "explanation": "自然力指大自然中的力量，风和雨正属于此类，是唯一能填入的词。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：大风和大雨不是桌子，“大风和大雨都是桌子”语义不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：大风和大雨不是诗歌，句子语义不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：大风和大雨不是电脑，“都是电脑”语义不通。"}], "explanations": {"自然力": "自然力指大自然中的力量，风和雨正属于此类，是唯一能填入的词。", "桌子": "语义：大风和大雨不是桌子，“大风和大雨都是桌子”语义不通。", "诗歌": "语义：大风和大雨不是诗歌，句子语义不通。", "电脑": "语义：大风和大雨不是电脑，“都是电脑”语义不通。"}, "sentence_index": 0, "correct_answer": "自然力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的自然力很大，一个人能搬动石头。", "explanation": "这里应该用〈力气〉。自然力指大自然的力量，不指人的力气。"}, {"text": "他忙了一整天，已经没有自然力了。", "explanation": "这里应该用〈精力〉。自然力指自然界的力量，不指人的精力。"}, {"text": "这位画家很有自然力，作品很多人喜欢。", "explanation": "这里应该用〈才华〉。自然力指自然界的力量，不指人的才华。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然力", "is_correct": true, "explanation": "自然力指大自然中的力量，阳光、雨水等自然条件让种子发芽，正是这一意义，是唯一能填入的词。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不能让种子发芽，“教室让种子发芽”语义不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能让种子发芽，句子语义不通。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“让……发芽”需要水分、阳光等自然条件，“螺丝”与之不搭配。"}], "explanations": {"自然力": "自然力指大自然中的力量，阳光、雨水等自然条件让种子发芽，正是这一意义，是唯一能填入的词。", "教室": "语义：教室不能让种子发芽，“教室让种子发芽”语义不通。", "书包": "语义：书包不能让种子发芽，句子语义不通。", "螺丝": "搭配：“让……发芽”需要水分、阳光等自然条件，“螺丝”与之不搭配。"}, "sentence_index": 6, "correct_answer": "自然力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他靠自然力赢得了比赛。", "explanation": "这里应该用〈天赋〉。自然力指自然界的力量，不指人的天赋。"}, {"text": "他的自然力很强，队员们都服他。", "explanation": "这里应该用〈实力〉。自然力指自然界的力量，不指人的实力。"}, {"text": "这位老师傅的自然力很好，做的家具很精致。", "explanation": "这里应该用〈手艺〉。自然力指自然界的力量，不指人的手艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一台自然力把水推向岸边。", "corrected_sentence": "一股自然力把水推向岸边。", "error_description": "量词错误：“自然力”是抽象的力量，应说“一股”；“台”用于机器，不能用来数自然力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几种自然力们一起把这块石头磨小了。", "corrected_sentence": "几种自然力一起把这块石头磨小了。", "error_description": "错误形式：“自然力们”；正确形式：“自然力”。“们”只附在指人或有生命的名词后，抽象的“自然力”不能加“们”，数量已由“几种”表示，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
