INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "煤是一种黑色的石头，可以烧火取暖。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "冬天，奶奶在炉子里放了几块煤。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤是黑色的，摸一下手就黑了。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷家用煤烧火取暖。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块煤很大，能烧一晚上。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他蹲在地上捡煤。", "target_word": "煤", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小时候，我家的院子里堆着很多煤。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤烧起来很热，但是烟很大。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买了一袋煤回家。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有煤了，我们得去买一些。", "target_word": "煤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些煤放在门外，别弄脏地板。", "target_word": "煤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "袋", "label": "量词"}, {"form": "煤炭", "label": "复合"}, {"form": "煤油", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以烧火取暖的黑色石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f88850e-622b-426b-b7db-fbf12d98ab7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。听到的是“煤”（méi），指可以烧火取暖的黑色石头。"}, {"text": "妹", "is_correct": false, "explanation": "妹（mèi）与 méi 声调不同（第四声与第二声），意思是妹妹。"}, {"text": "美", "is_correct": false, "explanation": "美（měi）与 méi 声调不同（第三声与第二声），意思是美丽。"}, {"text": "门", "is_correct": false, "explanation": "门（mén）与 méi 韵母不同（en 与 ei），意思是门。"}], "explanations": {"煤": "正确答案。听到的是“煤”（méi），指可以烧火取暖的黑色石头。", "妹": "妹（mèi）与 méi 声调不同（第四声与第二声），意思是妹妹。", "美": "美（měi）与 méi 声调不同（第三声与第二声），意思是美丽。", "门": "门（mén）与 méi 韵母不同（en 与 ei），意思是门。"}, "sentence_index": null, "correct_answer": "煤"}, "level_3": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。“放了几块”后面要接烧火用的块状燃料，即“煤”。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰放进炉子里无法取暖，与“在炉子里”取暖的语境矛盾。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：玻璃一般不放进炉子里，与“炉子”和取暖的情境不搭配。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不会放进炉子里，与冬天取暖的情景不符。"}], "explanations": {"煤": "正确答案。“放了几块”后面要接烧火用的块状燃料，即“煤”。", "冰": "语义：冰放进炉子里无法取暖，与“在炉子里”取暖的语境矛盾。", "玻璃": "搭配：玻璃一般不放进炉子里，与“炉子”和取暖的情境不搭配。", "黑板": "语义：黑板不会放进炉子里，与冬天取暖的情景不符。"}, "sentence_index": 0, "correct_answer": "煤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一只煤。", "explanation": "这里应该用〈块〉。“只”用于小动物或成对东西中的一个，煤是块状固体，不能用“只”。"}, {"text": "爷爷买了一瓶煤。", "explanation": "这里应该用〈块〉或〈袋〉。“瓶”用于液体，煤是固体，不能说一瓶煤。"}, {"text": "他家买了一台煤。", "explanation": "这里应该用〈块〉或〈袋〉。“台”用于机器或电器，煤不是机器，不能用“台”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煤", "is_correct": true, "explanation": "正确答案。“烧起来很热，但是烟很大”描述的是煤这种燃料。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不会烧起来，也不会冒烟，句子说的不是水。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不能烧，也不会“烧起来很热”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“烧”需要燃料，不能说空气烧起来，与“烧”不搭配。"}], "explanations": {"煤": "正确答案。“烧起来很热，但是烟很大”描述的是煤这种燃料。", "水": "语义：水不会烧起来，也不会冒烟，句子说的不是水。", "墨水": "语义：墨水不能烧，也不会“烧起来很热”。", "空气": "搭配：“烧”需要燃料，不能说空气烧起来，与“烧”不搭配。"}, "sentence_index": 6, "correct_answer": "煤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "煤很软，可以像面团一样捏成小人。", "explanation": "这里应该用〈硬〉。煤是坚硬的矿物，不能说软，也不能像面团一样捏成形。"}, {"text": "煤是一种会飞的鸟，每天在天上唱歌。", "explanation": "这里应该用〈石头〉。煤是矿物，不是鸟，既不会飞，也不会唱歌。"}, {"text": "这块煤很嫩，适合做成沙拉。", "explanation": "这里应该用〈蔬菜〉。煤是矿物，不是食物，不能说嫩或拿来做沙拉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈又在炉子里加了一个煤。", "corrected_sentence": "妈妈又在炉子里加了一块煤。", "error_description": "“煤”是块状固体，应用量词“块”，不能说“一个煤”，应说“一块煤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只煤要放在门外。", "corrected_sentence": "这块煤要放在门外。", "error_description": "“只”用于小动物或成对东西中的一个，煤是块状固体，不能用“只”计量，应改为“这块煤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
