INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "太空是地球外面很远很远的地方，那里黑黑的，没有空气。", "primary_collocate": null, "pronunciation": "tài kōng", "ipa": "tʰai˥˩ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "太空黑黑的，一点空气也没有。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他梦见自己一个人飘在太空里。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想坐飞船去太空看看。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空离我们很远，要飞很长时间。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子画了一张太空的图，上面有星星和月亮。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空里很安静，听不到一点声音。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了太空的故事。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从地球到太空，火箭要飞好几分钟。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的小狗坐着飞船到太空去了。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空里没有风，也没有雨。", "target_word": "太空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "太空人", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球外面很远、黑黑的、没有空气的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd87c5817-34a3-497b-90f4-3778d20342d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26800, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”指地球大气层以外的宇宙空间，与听到的读音相符。"}, {"text": "天空", "is_correct": false, "explanation": "tiān（第一声）与 tài（第四声）韵母不同，意思是天空，指地面上方的天，不是宇宙空间。"}, {"text": "卖空", "is_correct": false, "explanation": "mài（第四声）与 tài 声母不同，意思是卖空，是一种金融操作，不指宇宙空间。"}, {"text": "太公", "is_correct": false, "explanation": "gōng 与 kōng 声母不同，意思是祖父或对老人的敬称，不指宇宙空间。"}], "explanations": {"太空": "“太空”指地球大气层以外的宇宙空间，与听到的读音相符。", "天空": "tiān（第一声）与 tài（第四声）韵母不同，意思是天空，指地面上方的天，不是宇宙空间。", "卖空": "mài（第四声）与 tài 声母不同，意思是卖空，是一种金融操作，不指宇宙空间。", "太公": "gōng 与 kōng 声母不同，意思是祖父或对老人的敬称，不指宇宙空间。"}, "sentence_index": null, "correct_answer": "太空"}, "level_3": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”黑黑的、没有空气，符合地球外空间的特点，与“没有空气”的描述相符。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野里有空气，不会“一点空气也没有”，与句中描述矛盾。"}, {"text": "大气", "is_correct": false, "explanation": "语义：大气本身含有空气，与“一点空气也没有”矛盾。"}, {"text": "灶台", "is_correct": false, "explanation": "语义：灶台是厨房里做饭的台子，周围充满空气，与“一点空气也没有”矛盾。"}], "explanations": {"太空": "“太空”黑黑的、没有空气，符合地球外空间的特点，与“没有空气”的描述相符。", "田野": "语义：田野里有空气，不会“一点空气也没有”，与句中描述矛盾。", "大气": "语义：大气本身含有空气，与“一点空气也没有”矛盾。", "灶台": "语义：灶台是厨房里做饭的台子，周围充满空气，与“一点空气也没有”矛盾。"}, "sentence_index": 0, "correct_answer": "太空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们在太空挖出了很多煤。", "explanation": "这里应该用〈地下〉。煤埋在地下，要到地下去挖；太空是地球外面的宇宙空间，不会有煤层，这里的“太空”用法不对。"}, {"text": "太空中飘着几朵白云，很好看。", "explanation": "这里应该用〈天空〉。白云飘在天空中，太空没有空气，不会有云，这里的“太空”用法不对。"}, {"text": "鸟群在太空中盘旋，叫声很响亮。", "explanation": "这里应该用〈空中〉。鸟在空中盘旋，太空没有空气，鸟无法在那里活动，这里的“太空”用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太空", "is_correct": true, "explanation": "“太空”的故事是常见的童话或科普题材，与“老师给我们讲了……的故事”相符。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是物体所占空间的大小，不是可以讲故事的对象，与句意不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是冷热的程度，不是可以讲故事的对象，与句意不符。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度是运动快慢的量，不是可以讲故事的对象，与句意不符。"}], "explanations": {"太空": "“太空”的故事是常见的童话或科普题材，与“老师给我们讲了……的故事”相符。", "体积": "语义：体积是物体所占空间的大小，不是可以讲故事的对象，与句意不符。", "温度": "语义：温度是冷热的程度，不是可以讲故事的对象，与句意不符。", "速度": "语义：速度是运动快慢的量，不是可以讲故事的对象，与句意不符。"}, "sentence_index": 6, "correct_answer": "太空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他渴得厉害，就跑去喝太空。", "explanation": "“喝”的对象应是液体，太空是宇宙空间，不能喝，这里的“太空”用法不对。"}, {"text": "我们每天驾驶太空去上班。", "explanation": "“驾驶”的对象应是车辆或船，太空不是交通工具，这里的“太空”用法不对。"}, {"text": "妹妹冷了，就把太空披在身上。", "explanation": "“披”的对象应是衣物或被子，太空不能披，这里的“太空”用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抬头望去，一只太空黑沉沉的。", "corrected_sentence": "抬头望去，一片太空黑沉沉的。", "error_description": "“太空”的量词应该用“片”，写成“只”是错误的。“只”多用于动物，指一片广阔的空间要用“片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞船终于飞了上太空。", "corrected_sentence": "飞船终于飞上了太空。", "error_description": "补语“上”和“了”的位置错了。应写作“飞上了太空”，“上”紧跟在动词“飞”后面，“了”放在补语后；“飞了上太空”的语序是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cc9322c-6a59-4c34-9c16-477cf5e7fb21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
