INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "谷物是人们常吃的粮食，比如大米、小米和麦子。", "primary_collocate": null, "pronunciation": "gǔ wù", "ipa": "ku˨˩˦ u˥˩", "syllable_count": 2, "sentences": [{"text": "大米和小米都是谷物。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家每天都吃谷物做的饭。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的一排架子上摆着各种谷物。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子早上喝牛奶，吃谷物片。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的主要谷物是小麦和玉米。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种谷物煮熟以后很香。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿飞到地里吃谷物。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷种了很多谷物，自己吃不完。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谷物价格上涨了，面包也贵了。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，多吃谷物对身体好。", "target_word": "谷物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一袋谷物", "label": "量词"}, {"form": "一堆谷物", "label": "量词"}, {"form": "穀物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大米、小米、麦子等人们日常吃的粮食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是副食，不是人们常吃的粮食。"}, {"text": "零食", "is_correct": false, "explanation": "搭配：“都是”后接的类别不能是零食，大米和小米不属于零食。"}, {"text": "谷物", "is_correct": true, "explanation": "谷物：大米、小米等人们常吃的粮食，与句子的类别一致。"}, {"text": "调料", "is_correct": false, "explanation": "语义：调料是用来调味的，不是主食粮食。"}], "explanations": {"蔬菜": "语义：蔬菜是副食，不是人们常吃的粮食。", "零食": "搭配：“都是”后接的类别不能是零食，大米和小米不属于零食。", "谷物": "谷物：大米、小米等人们常吃的粮食，与句子的类别一致。", "调料": "语义：调料是用来调味的，不是主食粮食。"}, "sentence_index": 0, "correct_answer": "谷物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "棉花是重要的谷物。", "explanation": "这里应该用〈作物〉。棉花是经济作物，不属于谷物，谷物指大米、小米、麦子等粮食。"}, {"text": "黄瓜是常见的谷物。", "explanation": "这里应该用〈蔬菜〉。黄瓜是蔬菜，不属于人们常吃的粮食类谷物。"}, {"text": "妈妈炖汤时放了一点谷物作调料。", "explanation": "这里应该用〈调料〉。谷物指大米、小米、麦子等粮食，不是调味品，不能用作调料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能被鸟儿吃，“吃玩具”不成立。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“吃”不能与“空气”搭配，鸟儿吃的是食物。"}, {"text": "谷物", "is_correct": true, "explanation": "谷物：鸟儿在地里常啄食的粮食，与“吃”搭配。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是动物的食物。"}], "explanations": {"玩具": "语义：玩具不能被鸟儿吃，“吃玩具”不成立。", "空气": "搭配：“吃”不能与“空气”搭配，鸟儿吃的是食物。", "谷物": "谷物：鸟儿在地里常啄食的粮食，与“吃”搭配。", "汽油": "语义：汽油是燃料，不是动物的食物。"}, "sentence_index": 6, "correct_answer": "谷物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "红薯属于谷物。", "explanation": "这里应该用〈薯类〉。红薯是块根作物，不属于禾本科谷物。"}, {"text": "牛奶是常见的谷物。", "explanation": "这里应该用〈饮料〉。牛奶是饮品，不属于谷物。"}, {"text": "鸡蛋属于谷物。", "explanation": "这里应该用〈蛋类〉。鸡蛋是禽蛋，不属于谷物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈买了两只谷物。", "corrected_sentence": "妈妈买了两袋谷物。", "error_description": "量词用错。谷物应用“袋”计量，“只”用于动物，正确形式为“两袋谷物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民种的谷物们长势很好。", "corrected_sentence": "农民种的谷物长势很好。", "error_description": "“们”用错。“们”只用于指人，不能加在“谷物”后面，正确形式为“农民种的谷物”，“谷物们”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
