INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沼泽是很湿很软的地，上面长着草，容易陷进去。", "primary_collocate": null, "pronunciation": "zhǎo zé", "ipa": "tʂɑʊ˨˩˦ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "沼泽很软，一脚踩下去就会陷进去。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，前面是沼泽，不要往里走。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沼泽上面长着高高的草。", "target_word": "沼泽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鞋掉进了沼泽里，找不到了。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片沼泽离我家很远。", "target_word": "沼泽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在书里看过沼泽的照片。", "target_word": "沼泽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沼泽里的泥很黑，也很湿。", "target_word": "沼泽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "牛走进沼泽，出不来了。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走路的时候，我们绕开了沼泽。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说沼泽里有很多小虫子。", "target_word": "沼泽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片沼泽", "label": "量词"}, {"form": "沼泽地", "label": "复合"}, {"form": "沼澤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又湿又软、长着草、人容易陷进去的地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沼泽", "is_correct": true, "explanation": "正确：沼泽是又湿又软、人容易陷进去的地，与“很软，一脚踩下去就会陷进去”相符。"}, {"text": "岩石", "is_correct": false, "explanation": "语义：岩石坚硬，不会因为一脚踩下去而陷进去。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“很软”不能用来形容钢铁。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块踩上去会碎裂或滑动，不是“陷进去”的软地。"}], "explanations": {"沼泽": "正确：沼泽是又湿又软、人容易陷进去的地，与“很软，一脚踩下去就会陷进去”相符。", "岩石": "语义：岩石坚硬，不会因为一脚踩下去而陷进去。", "钢铁": "搭配：“很软”不能用来形容钢铁。", "冰块": "语义：冰块踩上去会碎裂或滑动，不是“陷进去”的软地。"}, "sentence_index": 0, "correct_answer": "沼泽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前面有一座沼泽，我们绕着走。", "explanation": "这里量词应该用〈片〉。〈座〉用于山、楼房等，沼泽是一片低洼的地，不能用“座”。"}, {"text": "雨后，院子里积着好几个沼泽。", "explanation": "这里应该用〈水洼〉。水洼是地面上的小片积水，沼泽是大片长期积水的低洼地带，不能指院子里的小积水。"}, {"text": "他把沼泽装进瓶子里，带回了家。", "explanation": "这里应该用〈泥〉或〈水〉。沼泽是一片地，不能装进瓶子里带回家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沼泽", "is_correct": true, "explanation": "正确：沼泽里的泥又黑又湿，与“沼泽里的泥很黑，也很湿”相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干燥，不会有很湿的泥。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：天空中不会有泥，“天空里的泥”不搭配。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：宇宙里没有泥土，与“泥很黑、很湿”不符。"}], "explanations": {"沼泽": "正确：沼泽里的泥又黑又湿，与“沼泽里的泥很黑，也很湿”相符。", "沙漠": "语义：沙漠干燥，不会有很湿的泥。", "天空": "搭配：天空中不会有泥，“天空里的泥”不搭配。", "宇宙": "语义：宇宙里没有泥土，与“泥很黑、很湿”不符。"}, "sentence_index": 6, "correct_answer": "沼泽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把沼泽切成一块块，放进锅里煮。", "explanation": "这里应该用〈食材〉。沼泽是低洼的地，不是可以切块下锅的东西。"}, {"text": "屋子旁边有一间沼泽，很吓人。", "explanation": "这里量词应该用〈片〉。〈间〉用于房屋，沼泽是一片地，不能用“间”。"}, {"text": "这块沼泽是用木头做的，很结实。", "explanation": "这里应该用〈木头〉。沼泽是低洼的湿地，不是木头做的，不能说很结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子旁边有一只沼泽。", "corrected_sentence": "村子旁边有一片沼泽。", "error_description": "“沼泽”是一片地，量词应用“片”，不用“只”；“只”用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客的相机掉进了沼泽上。", "corrected_sentence": "游客的相机掉进了沼泽里。", "error_description": "“掉进”后面要用“里”表示落入的范围，“沼泽上”指表面，不能说“掉进沼泽上”，应说“掉进沼泽里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
