INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很久很久以前，动物或植物死了，它们的身体变成了石头，这就是化石。", "primary_collocate": null, "pronunciation": "huà shí", "ipa": "xwa˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这块石头里有一只小鱼的化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多恐龙化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去山上找化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化石是很久以前的动物变成的石头。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在河边捡到了一块像树叶的化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块化石上能看到一只虫子的样子。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用化石研究古代的植物。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友有一块很漂亮的贝壳化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些化石有几千万年的历史。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸送给我一块三叶虫化石。", "target_word": "化石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}], "register": "中性", "sense_fingerprint": "很久以前的动植物变成的石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6965bde7-6897-4797-b880-940007ee84e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "化石", "is_correct": true, "explanation": "正确答案：化石，指很久以前的动植物变成的石头。"}, {"text": "画室", "is_correct": false, "explanation": "声调：画室 huàshì 与化石 huà shí 只有第二个音节不同（第四声与第二声），画室指画画的房间。"}, {"text": "画师", "is_correct": false, "explanation": "声调：画师 huàshī 与化石 huà shí 只有第二个音节不同（第一声与第二声），画师指画家。"}, {"text": "滑石", "is_correct": false, "explanation": "声调：滑石 huáshí 与化石 huà shí 只有第一个音节不同（第二声与第四声），滑石是一种矿物。"}], "explanations": {"化石": "正确答案：化石，指很久以前的动植物变成的石头。", "画室": "声调：画室 huàshì 与化石 huà shí 只有第二个音节不同（第四声与第二声），画室指画画的房间。", "画师": "声调：画师 huàshī 与化石 huà shí 只有第二个音节不同（第一声与第二声），画师指画家。", "滑石": "声调：滑石 huáshí 与化石 huà shí 只有第一个音节不同（第二声与第四声），滑石是一种矿物。"}, "sentence_index": null, "correct_answer": "化石"}, "level_3": {"options": [{"text": "化石", "is_correct": true, "explanation": "正确：化石指很久以前的小鱼变成的石头，与“石头里有一只小鱼”的语境相符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：石头里的小鱼是天然形成的，不是玩具，句意不通。"}, {"text": "食物", "is_correct": false, "explanation": "语义：石头里的小鱼不是可以吃的食物，与“石头里”的语境相矛盾。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“小鱼的电话”不成词组，不能表示石头里小鱼的遗留物。"}], "explanations": {"化石": "正确：化石指很久以前的小鱼变成的石头，与“石头里有一只小鱼”的语境相符。", "玩具": "语义：石头里的小鱼是天然形成的，不是玩具，句意不通。", "食物": "语义：石头里的小鱼不是可以吃的食物，与“石头里”的语境相矛盾。", "电话": "搭配：“小鱼的电话”不成词组，不能表示石头里小鱼的遗留物。"}, "sentence_index": 0, "correct_answer": "化石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在河边喝了一些化石。", "explanation": "这里应该用〈水〉。化石是石头，不能喝，“喝”的对象应是水。"}, {"text": "这座博物馆收藏着很多唐代的化石。", "explanation": "这里应该用〈文物〉。化石是很久以前的动植物变成的石头，唐代的器物属于文物，不能称为化石。"}, {"text": "这批化石是古人用来烧制陶罐的原料。", "explanation": "这里应该用〈黏土〉。化石是动植物变成的石头，不能用来烧制陶罐，古人烧陶用的是黏土。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26810, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "化石", "is_correct": true, "explanation": "正确答案：化石，指很久以前的动植物变成的石头。"}, {"text": "花市", "is_correct": false, "explanation": "声调：花市 huāshì 与化石 huà shí 两个音节的声调都不同，花市指卖花的市场。"}, {"text": "画书", "is_correct": false, "explanation": "韵母：画书 huàshū 与化石 huà shí 只有第二个音节的韵母不同（ū 与 i），画书指画册。"}, {"text": "华氏", "is_correct": false, "explanation": "声调：华氏 huáshì 与化石 huà shí 两个音节的声调都不同，华氏是温度单位。"}], "explanations": {"化石": "正确答案：化石，指很久以前的动植物变成的石头。", "花市": "声调：花市 huāshì 与化石 huà shí 两个音节的声调都不同，花市指卖花的市场。", "画书": "韵母：画书 huàshū 与化石 huà shí 只有第二个音节的韵母不同（ū 与 i），画书指画册。", "华氏": "声调：华氏 huáshì 与化石 huà shí 两个音节的声调都不同，华氏是温度单位。"}, "sentence_index": null, "correct_answer": "化石"}, "level_3": {"options": [{"text": "化石", "is_correct": true, "explanation": "正确：科学家可以通过化石研究古代植物，符合句意。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能用来研究古代的植物。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“用牛奶研究”不成立，牛奶不是研究古代植物的手段。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是用来储存食物的电器，不能用来研究古代的植物。"}], "explanations": {"化石": "正确：科学家可以通过化石研究古代植物，符合句意。", "沙发": "语义：沙发是家具，不能用来研究古代的植物。", "牛奶": "搭配：“用牛奶研究”不成立，牛奶不是研究古代植物的手段。", "冰箱": "语义：冰箱是用来储存食物的电器，不能用来研究古代的植物。"}, "sentence_index": 6, "correct_answer": "化石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套家具是用化石做的。", "explanation": "这里应该用〈木头〉。化石是石头，不能用来做家具。"}, {"text": "这台化石坏了，需要修理。", "explanation": "这里应该用〈电器〉。化石是动植物变成的石头，不能指需要修理的机器。"}, {"text": "木匠用化石锯木头。", "explanation": "这里应该用〈工具〉。化石是动植物留下的遗迹，不能用来锯木头；应使用工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在山里捡到了一只化石。", "corrected_sentence": "我在山里捡到了一块化石。", "error_description": "量词错误：化石应用量词“块”，“只”用于动物，这里应改为“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把一只化石放进了展柜。", "corrected_sentence": "老师把一块化石放进了展柜。", "error_description": "量词错误：化石应用量词“块”，“只”用于动物，这里应改为“块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '320003e0-3b31-4639-b087-589cb24455de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
