INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把空气或液体弄走。", "primary_collocate": null, "pronunciation": "chōu pái", "ipa": "ʈʂʰoʊ˥ pʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "浴室里装了风扇，用来抽排湿气。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用管子抽排游泳池里的水。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要先抽排瓶里的空气，再盖上盖子。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下车库的积水需要尽快抽排。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用大风机抽排车间里的烟。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能抽排鱼缸里的脏水。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，工人开始抽排路上的水。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室的柜子会自动抽排气体。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盆里的水抽排完了。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的病房需要不断抽排空气。", "target_word": "抽排", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽排了", "label": "完成体"}, {"form": "抽排着", "label": "持续体"}, {"form": "抽排过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把空气、湿气或脏水等从某处弄走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽排", "is_correct": true, "explanation": "正确：抽排指把空气、湿气弄走，与风扇的用途相符。"}, {"text": "加热", "is_correct": false, "explanation": "语义：风扇是把湿气排走，不是把它加热。"}, {"text": "堆积", "is_correct": false, "explanation": "搭配：“堆积”指聚拢在一起，不能和“用来……湿气”的排除用途搭配。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：湿气不能被点燃，风扇也不是用来点火的。"}], "explanations": {"抽排": "正确：抽排指把空气、湿气弄走，与风扇的用途相符。", "加热": "语义：风扇是把湿气排走，不是把它加热。", "堆积": "搭配：“堆积”指聚拢在一起，不能和“用来……湿气”的排除用途搭配。", "点燃": "语义：湿气不能被点燃，风扇也不是用来点火的。"}, "sentence_index": 0, "correct_answer": "抽排"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人很快抽排了管道的故障。", "explanation": "这里应该用〈排除〉。抽排只指弄走空气或液体，不能用于故障。"}, {"text": "他把屋子抽排干净了。", "explanation": "这里应该用〈收拾〉。抽排的对象是空气或液体，不能用于屋子。"}, {"text": "他从书架上抽排了一本书。", "explanation": "这里应该用〈抽出〉。抽排指把空气、液体弄走，不能用来拿取书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽排", "is_correct": true, "explanation": "正确：抽排指把积水弄走，与雨后处理路面积水的语境相符。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：煮沸是加热水至沸腾，不是处理路上的积水。"}, {"text": "饮用", "is_correct": false, "explanation": "语义：路上的积水不能饮用，“饮用”与语境不符。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”用于给植物供水，不能用于路面积水。"}], "explanations": {"抽排": "正确：抽排指把积水弄走，与雨后处理路面积水的语境相符。", "煮沸": "语义：煮沸是加热水至沸腾，不是处理路上的积水。", "饮用": "语义：路上的积水不能饮用，“饮用”与语境不符。", "浇灌": "搭配：“浇灌”用于给植物供水，不能用于路面积水。"}, "sentence_index": 6, "correct_answer": "抽排"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把心里的怒气抽排出来了。", "explanation": "这里应该用〈发泄〉。抽排只用于弄走空气或液体，不能用于情绪。"}, {"text": "师傅很快抽排好了坏掉的椅子。", "explanation": "这里应该用〈修理〉。抽排不能用于修理家具。"}, {"text": "妈妈抽排了生病的孩子。", "explanation": "这里应该用〈照顾〉。抽排只用于空气、液体，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人连夜把积水抽排了干净了。", "corrected_sentence": "工人连夜把积水抽排干净了。", "error_description": "了的位置错误：“抽排”和补语“干净”之间多出了一个“了”，应为「抽排干净了」。结果补语“干净”要紧跟动词，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把湿气抽排了屋外。", "corrected_sentence": "他们把湿气抽排到了屋外。", "error_description": "去向要用介词“到”引出：“抽排”后直接接处所词不通，应为“抽排到了屋外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
