INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地上堆起来的水", "primary_collocate": null, "pronunciation": "jī shuǐ", "ipa": "tɕi˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "下雨后，地上有一大片积水。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的鞋踩进积水里，全湿了。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上的积水让车开得很慢。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳出来，积水很快就干了。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看见操场上有积水，没去踢球。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子里的积水要排到下水道去。", "target_word": "积水", "complexity_tier": "T3", "furigana": "yuàn zi lǐ de jī shuǐ yào pái dào xià shuǐ dào qù", "sentence_source": "generated"}, {"text": "积水里有一片落叶。", "target_word": "积水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们喜欢在积水里跳。", "target_word": "积水", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地下车库里有积水，大家要小心。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天下大雨，今天街上还有积水。", "target_word": "积水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一摊积水", "label": "量词"}, {"form": "一片积水", "label": "量词"}, {"form": "積水", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地上聚在一起、排不走的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "积水", "is_correct": true, "explanation": "正确。下雨后地上积聚的水可以铺成一大片。"}, {"text": "雪", "is_correct": false, "explanation": "语义：下雨后不会下雪，地上不会是雪。"}, {"text": "火焰", "is_correct": false, "explanation": "语义：雨后的地上不会有一大片火焰。"}, {"text": "尘土", "is_correct": false, "explanation": "搭配：“下雨后”的地上多是水或泥，与“一大片尘土”不搭。"}], "explanations": {"积水": "正确。下雨后地上积聚的水可以铺成一大片。", "雪": "语义：下雨后不会下雪，地上不会是雪。", "火焰": "语义：雨后的地上不会有一大片火焰。", "尘土": "搭配：“下雨后”的地上多是水或泥，与“一大片尘土”不搭。"}, "sentence_index": 0, "correct_answer": "积水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "跑完步，他的额头上全是积水。", "explanation": "这里应该用〈汗水〉。积水是地上积聚的水，不会从人的额头上冒出来。"}, {"text": "听到消息，她的眼里涌出了积水。", "explanation": "这里应该用〈泪水〉。积水是地上的水，不会从眼睛里涌出。"}, {"text": "大雨过后，积水冲毁了路边的房子。", "explanation": "这里应该用〈洪水〉。洪水是奔流的大水，能冲毁房屋；积水静止不流，不能“冲毁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "积水", "is_correct": true, "explanation": "正确。积水里可以漂着落叶。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实心的，里面不会有落叶。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字是抽象符号，里面不会有落叶。"}, {"text": "云层", "is_correct": false, "explanation": "语义：云层在天上，不会装着地上的落叶。"}], "explanations": {"积水": "正确。积水里可以漂着落叶。", "石头": "语义：石头是实心的，里面不会有落叶。", "数字": "语义：数字是抽象符号，里面不会有落叶。", "云层": "语义：云层在天上，不会装着地上的落叶。"}, "sentence_index": 6, "correct_answer": "积水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口的积水很厚，我们花了一上午才扫完。", "explanation": "这里应该用〈积雪〉。积雪可以堆得很厚；积水应说“深”，不说“厚”。"}, {"text": "山里的积水很甜，孩子们都抢着喝。", "explanation": "这里应该用〈泉水〉。泉水是从地下涌出的清水，可以直接喝；积水积在地面，不能喝，也不能说“甜”。"}, {"text": "早上草地上挂满了积水。", "explanation": "这里应该用〈露水〉。露水附着在草叶上；积水积在地面，不会挂在草上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停后，操场上有一只积水，大家要小心。", "corrected_sentence": "雨停后，操场上有一片积水，大家要小心。", "error_description": "量词错误：“积水”是地面上的水，不能用“只”（“只”多用于动物），应为“一片积水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口的台阶上有一根积水，小心滑倒。", "corrected_sentence": "门口的台阶上有一摊积水，小心滑倒。", "error_description": "量词错误：「一根积水」应为「一摊积水」。“根”用于细长的东西，积水要用“摊”或“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
