INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过机器零件把动力从一个地方传到另一个地方。", "primary_collocate": null, "pronunciation": "jī xiè chuán dòng", "ipa": "tɕi˥ ɕjɛ˥˩ tʂʰwan˧˥ twʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "机械传动靠齿轮把动力传过去。", "target_word": "机械传动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具车用的是简单的机械传动。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风车的机械传动把风力变成磨面的力。", "target_word": "机械传动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课上，我们看了机械传动的小模型。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机械传动需要油，不然零件会坏。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手表里面也有机械传动。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对机械传动很感兴趣，所以去读了机械专业。", "target_word": "机械传动", "complexity_tier": "T3", "furigana": "tā duì jī xiè chuán dòng hěn gǎn xìngqù, suǒ yǐ qù dú le jī xiè zhuān yè", "sentence_source": "generated"}, {"text": "水车用机械传动带动磨盘。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮带坏了，机械传动就停了。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机械传动的好处是结实，不容易坏。", "target_word": "机械传动", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "机械传动系统", "label": "复合"}, {"form": "機械傳動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "靠机器零件把动力从一处传到另一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f2cad4d-5806-43f6-8a3e-713804406461') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机械传动", "is_correct": true, "explanation": "正确。机械传动靠齿轮把动力传过去，句子通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不靠齿轮传递动力。"}, {"text": "友情", "is_correct": false, "explanation": "语义：友情不能靠齿轮把动力传过去。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“靠齿轮”只用于机械装置，不说温度靠齿轮传动。"}], "explanations": {"机械传动": "正确。机械传动靠齿轮把动力传过去，句子通顺。", "空气": "语义：空气不靠齿轮传递动力。", "友情": "语义：友情不能靠齿轮把动力传过去。", "温度": "搭配：“靠齿轮”只用于机械装置，不说温度靠齿轮传动。"}, "sentence_index": 0, "correct_answer": "机械传动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都坚持机械传动，身体很好。", "explanation": "这里应该用〈运动〉。机械传动指靠机器零件传递动力，不能用来指人的锻炼。"}, {"text": "院子里的机械传动长高了。", "explanation": "这里应该用〈树〉。树会长高，机械传动是传递动力的过程，不会“长高”。"}, {"text": "机械传动很喜欢听音乐，每天都要唱几首。", "explanation": "这里应该用〈人〉。机械传动是传递动力的装置，不会听音乐、唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机械传动", "is_correct": true, "explanation": "正确。他对机械传动感兴趣，所以去读了机械专业。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：对烹饪感兴趣，不会去读机械专业。"}, {"text": "考古", "is_correct": false, "explanation": "语义：对考古感兴趣，和“去读机械专业”的因果不通。"}, {"text": "园艺", "is_correct": false, "explanation": "搭配：“对……感兴趣”后接的是学科或爱好，园艺与机械专业的逻辑不合。"}], "explanations": {"机械传动": "正确。他对机械传动感兴趣，所以去读了机械专业。", "烹饪": "语义：对烹饪感兴趣，不会去读机械专业。", "考古": "语义：对考古感兴趣，和“去读机械专业”的因果不通。", "园艺": "搭配：“对……感兴趣”后接的是学科或爱好，园艺与机械专业的逻辑不合。"}, "sentence_index": 6, "correct_answer": "机械传动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里，机械传动把整个房间照亮了。", "explanation": "这里应该用〈电灯〉。电灯能发光，机械传动只是传递动力，不能“照亮”房间。"}, {"text": "机械传动开着，凉风吹了进来。", "explanation": "这里应该用〈窗户〉。窗户可以打开，凉风才能从窗户吹进来；机械传动是传递动力的过程，不能“开”。"}, {"text": "机械传动从山上流下来，汇成了小溪。", "explanation": "这里应该用〈水〉。水能流动、汇成小溪；机械传动是传递动力的过程，不能像水那样流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风车的机械传动了坏，磨面就停了。", "corrected_sentence": "风车的机械传动坏了，磨面就停了。", "error_description": "了的位置错误：「传动了坏」应为「传动坏了」。结果补语“坏”后面要接“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他修好了一只机械传动。", "corrected_sentence": "他修好了一套机械传动。", "error_description": "量词错误：机械传动是一整套装置，应用“套”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b5e0cc-c682-430b-baf2-a66a83f12ed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
