INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26822, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容东西很厚、很重，或者说话、做事很稳重。", "primary_collocate": null, "pronunciation": "hòu zhòng", "ipa": "xoʊ˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这本词典又大又厚重，我拿不动。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的被子很厚重，盖着很暖和。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬来一个厚重的木箱子。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张叔叔做事厚重，从来不着急。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥为人厚重，不爱开玩笑。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇铁门太厚重了，小孩推不动。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着一件厚重的外衣走进来。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的石头很厚重，走上去很稳。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音厚重，让人觉得很可靠。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板做事厚重，客人都信任他。", "target_word": "厚重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "厚重感", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容东西又厚又重，或做事说话稳重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb351630-da49-476b-8754-b40ebd05cc45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厚重", "is_correct": true, "explanation": "正确答案。“又大又厚重”说明词典分量大，与“我拿不动”相合。"}, {"text": "轻薄", "is_correct": false, "explanation": "语义：轻薄指又轻又薄，与“我拿不动”的分量相矛盾。"}, {"text": "轻盈", "is_correct": false, "explanation": "语义：轻盈指轻巧，与“我拿不动”的分量相矛盾。"}, {"text": "稳重", "is_correct": false, "explanation": "搭配：稳重多用于人的性格，不用于形容词典。"}], "explanations": {"厚重": "正确答案。“又大又厚重”说明词典分量大，与“我拿不动”相合。", "轻薄": "语义：轻薄指又轻又薄，与“我拿不动”的分量相矛盾。", "轻盈": "语义：轻盈指轻巧，与“我拿不动”的分量相矛盾。", "稳重": "搭配：稳重多用于人的性格，不用于形容词典。"}, "sentence_index": 0, "correct_answer": "厚重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣很厚重，适合春天穿。", "explanation": "这里应该用〈轻薄〉。厚重指又厚又重，春天穿的毛衣应说轻薄。"}, {"text": "这道题很厚重，我很快就做完了。", "explanation": "这里应该用〈轻松〉。厚重不用于形容题目的难易，且与“很快就做完”矛盾。"}, {"text": "这个小妹妹很厚重，整天蹦蹦跳跳。", "explanation": "这里应该用〈活泼〉。厚重表示稳重，与“蹦蹦跳跳”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厚重", "is_correct": true, "explanation": "正确答案。“厚重的外衣”指外衣又厚又重，与“穿着”相合。"}, {"text": "稳健", "is_correct": false, "explanation": "搭配：稳健多用于做事或步伐，不用于形容外衣。"}, {"text": "沉稳", "is_correct": false, "explanation": "搭配：沉稳多用于人的神态或性格，不用于形容外衣。"}, {"text": "深厚", "is_correct": false, "explanation": "搭配：深厚多用于感情、基础，不用于形容外衣。"}], "explanations": {"厚重": "正确答案。“厚重的外衣”指外衣又厚又重，与“穿着”相合。", "稳健": "搭配：稳健多用于做事或步伐，不用于形容外衣。", "沉稳": "搭配：沉稳多用于人的神态或性格，不用于形容外衣。", "深厚": "搭配：深厚多用于感情、基础，不用于形容外衣。"}, "sentence_index": 6, "correct_answer": "厚重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只箱子很厚重，老板一只手就提起来了。", "explanation": "这里应该用〈轻便〉。厚重指分量大，与“一只手就提起来”矛盾。"}, {"text": "他的步子很厚重，像一阵风一样快。", "explanation": "这里应该用〈轻快〉。厚重形容稳重或分量，不形容步子轻快。"}, {"text": "这个笑话很厚重，大家听了都笑了。", "explanation": "这里应该用〈好笑〉。厚重不用于形容笑话，笑话应说好笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子厚重很，搬起来很费劲。", "corrected_sentence": "这个箱子厚重得很，搬起来很费劲。", "error_description": "错误形式：厚重很。正确形式：厚重得很。形容词后表示程度要用“得很”，不能只说“形容词+很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块石板很厚重地，两个人才抬得动。", "corrected_sentence": "这块石板很厚重，两个人才抬得动。", "error_description": "错误形式：厚重地。正确形式：很厚重。“厚重”作谓语时不加“地”，前面要用程度副词“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动式", "is_correct": true, "explanation": "反义：被动式指等人推动、不主动做事，主动式指主动做事，二者相反"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与做事态度无关"}, {"text": "石头", "is_correct": false, "explanation": "无关：“石头”是自然物，与被动式没有反义关系"}, {"text": "星星", "is_correct": false, "explanation": "无关：“星星”是天体，与被动式没有反义关系"}], "correct_answer": "主动式", "explanations": {"主动式": "反义：被动式指等人推动、不主动做事，主动式指主动做事，二者相反", "河流": "无关：“河流”是地理事物，与做事态度无关", "石头": "无关：“石头”是自然物，与被动式没有反义关系", "星星": "无关：“星星”是天体，与被动式没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主动式", "is_correct": true, "explanation": "反义：被动式指等人推动、不主动做事，主动式指主动做事，二者相反"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具，与做事态度无关"}, {"text": "天空", "is_correct": false, "explanation": "无关：“天空”是自然景物，与被动式没有反义关系"}, {"text": "花朵", "is_correct": false, "explanation": "无关：“花朵”是植物的一部分，与被动式没有反义关系"}], "correct_answer": "主动式", "explanations": {"主动式": "反义：被动式指等人推动、不主动做事，主动式指主动做事，二者相反", "桌子": "无关：“桌子”是家具，与做事态度无关", "天空": "无关：“天空”是自然景物，与被动式没有反义关系", "花朵": "无关：“花朵”是植物的一部分，与被动式没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事不主动，总等别人安排或推动的工作、处事方式。", "primary_collocate": null, "pronunciation": "bèi dòng shì", "ipa": "pei˥˩ tʊŋ˥˩ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "他的工作方式是被动式，总等别人安排。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被动式的学习，只会等老师教。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她习惯了被动式的处事方式，总要别人替她拿主意。", "target_word": "被动式", "complexity_tier": "T3", "furigana": "tā xí guàn le bèi dòng shì de chǔ shì fāng shì, zǒng yào bié rén tì tā ná zhǔ yi.", "sentence_source": "generated"}, {"text": "公司想改变被动式的管理方法。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题时，他总是用被动式的办法，等人帮忙。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被动式的人很少自己找事做。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做销售不能用被动式，要主动找客人。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们习惯了被动式的学习，不会自己想。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种被动式的态度，对工作没有帮助。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从被动式变成了主动式，进步很快。", "target_word": "被动式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "做事不主动，等别人安排、推动的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb351630-da49-476b-8754-b40ebd05cc45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被动式", "is_correct": true, "explanation": "被动式：指做事不主动、等别人安排推动的方式，与“总等别人安排”相符"}, {"text": "主动式", "is_correct": false, "explanation": "语义：“主动式”指主动做事，与“总等别人安排”正相矛盾"}, {"text": "自主式", "is_correct": false, "explanation": "语义：“自主式”指自己拿主意，与“总等别人安排”正相反"}, {"text": "手工式", "is_correct": false, "explanation": "搭配：“手工式”多指靠手工完成的生产方法，不用来说人的工作方式"}], "explanations": {"被动式": "被动式：指做事不主动、等别人安排推动的方式，与“总等别人安排”相符", "主动式": "语义：“主动式”指主动做事，与“总等别人安排”正相矛盾", "自主式": "语义：“自主式”指自己拿主意，与“总等别人安排”正相反", "手工式": "搭配：“手工式”多指靠手工完成的生产方法，不用来说人的工作方式"}, "sentence_index": 0, "correct_answer": "被动式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的处事方式是被动式，凡事都自己拿主意。", "explanation": "这里应该用〈自主式〉。被动式指等别人安排推动，句中“凡事都自己拿主意”是自主做事。"}, {"text": "他的做法是被动式，不等别人安排。", "explanation": "这里应该用〈主动式〉。句子说他不等别人安排，是主动做事，而被动式指等别人推动"}, {"text": "这种管理方式是一只被动式。", "explanation": "这里的量词不对。〈只〉用于动物等，被动式是做事方式，应该用〈种〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被动式", "is_correct": true, "explanation": "被动式：指等人来找、不主动出击的做法，与“不能用”和“要主动找客人”形成对比"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“用”后接方法或手段，“天气”不能用作销售的方式"}, {"text": "咸味", "is_correct": false, "explanation": "语义：“咸味”是口味，不能用作销售的做法"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是物体，不能作为销售的做法"}], "explanations": {"被动式": "被动式：指等人来找、不主动出击的做法，与“不能用”和“要主动找客人”形成对比", "天气": "搭配：“用”后接方法或手段，“天气”不能用作销售的方式", "咸味": "语义：“咸味”是口味，不能用作销售的做法", "石头": "语义：“石头”是物体，不能作为销售的做法"}, "sentence_index": 6, "correct_answer": "被动式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是主动找事做，工作方式是被动式。", "explanation": "这里应该用〈主动式〉。“总是主动找事做”与被动式“等别人安排”相矛盾。"}, {"text": "他的工作方式是一座被动式。", "explanation": "这里的量词不对。〈座〉用于山、楼房等大型固定物，被动式指做事方式，应该用〈种〉"}, {"text": "他的做事风格是一块被动式。", "explanation": "这里的量词不对。〈块〉用于块状的东西，被动式指做事方式，应该用〈种〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的工作习惯是一只被动式，总等别人安排。", "corrected_sentence": "他的工作习惯是一种被动式，总等别人安排。", "error_description": "错误：“一只被动式”。正确：“一种被动式”。“只”用于动物等，“被动式”是做事的方式，应该用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团队的工作方式从被动式转变了主动式。", "corrected_sentence": "这个团队的工作方式从被动式转变成了主动式。", "error_description": "错误：“转变了主动式”。正确：“转变成了主动式”。表示变成另一种事物时，“转变”后面要用“成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
