INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种很硬、有花纹的石头，常用来做桌面或地板。", "primary_collocate": null, "pronunciation": "dà lǐ shí", "ipa": "ta˥˩ li˨˩˦ ʂɻ̩˧˥", "syllable_count": 3, "sentences": [{"text": "我家的餐桌是大理石的，又重又凉。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店大厅的地面是用大理石铺的。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块大理石上有很漂亮的花纹。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用大理石做一张新桌子。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大理石地板擦干净后，亮得像镜子。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的台面换成了大理石。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种石头叫大理石，常常有灰色的花纹。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不喜欢大理石，因为它冬天太凉。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手间里的洗手台是白色大理石做的。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在商店里看了很多种大理石。", "target_word": "大理石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "大理石桌面", "label": "复合"}, {"form": "大理石地板", "label": "复合"}], "register": "中性", "sense_fingerprint": "有花纹的硬石头，常做桌面地板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb351630-da49-476b-8754-b40ebd05cc45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大理石", "is_correct": true, "explanation": "大理石：很硬、很重的石材，又重又凉，符合句意。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头较轻，也不凉，与“又重又凉”矛盾。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料很轻，与“又重”矛盾。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：纸不能用来做餐桌。"}], "explanations": {"大理石": "大理石：很硬、很重的石材，又重又凉，符合句意。", "木头": "语义：木头较轻，也不凉，与“又重又凉”矛盾。", "塑料": "语义：塑料很轻，与“又重”矛盾。", "纸": "搭配：纸不能用来做餐桌。"}, "sentence_index": 0, "correct_answer": "大理石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想买一只大理石做新桌子。", "explanation": "这里应该用〈块〉。大理石是块状石材，要用“块”计量，不用“只”。"}, {"text": "他想去大理石旅游一次。", "explanation": "这里应该用〈大理〉。大理是云南的地名，大理石是石材，不能用来指地方。"}, {"text": "他想用大理石刷一张新桌子。", "explanation": "这里应该用〈油漆〉。“刷”用于油漆等涂料，大理石是固体石材，不能用来刷桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大理石", "is_correct": true, "explanation": "大理石：一种有灰色花纹的石头，符合句意。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花不是石头，也没有这样的花纹。"}, {"text": "面包", "is_correct": false, "explanation": "体貌：面包是软的，没有坚硬的石头外观和灰色花纹。"}, {"text": "泡沫", "is_correct": false, "explanation": "语义：泡沫不是石头，与“叫……常常有灰色的花纹”不符。"}], "explanations": {"大理石": "大理石：一种有灰色花纹的石头，符合句意。", "棉花": "语义：棉花不是石头，也没有这样的花纹。", "面包": "体貌：面包是软的，没有坚硬的石头外观和灰色花纹。", "泡沫": "语义：泡沫不是石头，与“叫……常常有灰色的花纹”不符。"}, "sentence_index": 6, "correct_answer": "大理石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她想用大理石织一件毛衣。", "explanation": "这里应该用〈毛线〉。“织”需要线状材料，大理石是硬块，不能用来织毛衣。"}, {"text": "他想用大理石裁一件衣服。", "explanation": "这里应该用〈剪刀〉。“裁”要用剪刀之类的工具，大理石不能用来裁衣服。"}, {"text": "妈妈用大理石洗了衣服。", "explanation": "这里应该用〈洗衣粉〉。“洗”要用洗衣粉、肥皂等洗涤剂，大理石不能用来洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在门口铺了一块白色地大理石。", "corrected_sentence": "他在门口铺了一块白色的大理石。", "error_description": "错误形式：白色地大理石。正确形式：白色的大理石。修饰名词要用“的”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在商店里看了完很多种大理石。", "corrected_sentence": "他在商店里看完了很多种大理石。", "error_description": "结果补语位置错误：“看完”是动词加结果补语，应说“看完了”，不说“看了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a440626b-66c8-4374-99ae-c758e907532e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
