INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一套很多想法放在一起，用来讲清楚一个事情。", "primary_collocate": null, "pronunciation": "lǐ lùn tǐ xì", "ipa": "li˨˩ lwən˥˩ tʰi˨˩ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "他有自己的理论体系。", "target_word": "理论体系", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个理论体系可以讲清楚很多事情。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用一套理论体系解释天气。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想懂这件事，先看它的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书里有完整的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "理论体系不是一句话，是很多想法。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我学了一个新的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个科学家都想建立自己的理论体系。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这些想法连成了一个理论体系。", "target_word": "理论体系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了理论体系，大家就能看懂这个问题。", "target_word": "理论体系", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "许多想法组成的一套，用来讲清楚一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b8958f0-ffe2-4271-bc78-1dc054604ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理论体系", "is_correct": true, "explanation": "理论体系：许多想法组成的一套，可以说「自己的」，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不是一套想法，不能与“理论体系”互换。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「有」不与「天气」搭配，天气是客观现象。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气为人人共享，不能说「自己的空气」。"}], "explanations": {"理论体系": "理论体系：许多想法组成的一套，可以说「自己的」，符合句意。", "太阳": "语义：太阳是天体，不是一套想法，不能与“理论体系”互换。", "天气": "搭配：「有」不与「天气」搭配，天气是客观现象。", "空气": "语义：空气为人人共享，不能说「自己的空气」。"}, "sentence_index": 0, "correct_answer": "理论体系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想出了一棵理论体系。", "explanation": "「棵」用于植物，理论体系是抽象的，应用「套」。"}, {"text": "这套理论体系很可靠，全城都能用水。", "explanation": "这里应该用〈供水体系〉。理论体系指学科中的概念，不能给全城供水。"}, {"text": "他喝了一口理论体系。", "explanation": "这里是把理论体系当成了饮品来用。理论体系是一套想法，不是饮品，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理论体系", "is_correct": true, "explanation": "理论体系：可以「学」，符合「我学了一个新的」的语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然环境，不能「学」。"}, {"text": "午餐", "is_correct": false, "explanation": "搭配：「学」的对象是知识或技能，不说「学了一个新的午餐」。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，不是可以学习的对象，与「学」不合。"}], "explanations": {"理论体系": "理论体系：可以「学」，符合「我学了一个新的」的语境。", "天空": "语义：天空是自然环境，不能「学」。", "午餐": "搭配：「学」的对象是知识或技能，不说「学了一个新的午餐」。", "窗户": "语义：窗户是建筑构件，不是可以学习的对象，与「学」不合。"}, "sentence_index": 6, "correct_answer": "理论体系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部理论体系能查到很多词。", "explanation": "这里应该用〈词典〉。理论体系讲概念和命题，不用来查词。"}, {"text": "他端来一碗理论体系。", "explanation": "这里应该用〈套〉。「碗」是盛食物的量词，理论体系是抽象的，应用「套」。"}, {"text": "他把理论体系穿在身上。", "explanation": "这里是把理论体系当成了衣物来用。理论体系是一套想法，不是衣物，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用了一把理论体系来讲清楚这件事。", "corrected_sentence": "他用了一套理论体系来讲清楚这件事。", "error_description": "量词错误：「理论体系」应配「套」，「把」不能用于理论体系。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直在完善了自己的理论体系。", "corrected_sentence": "他一直在完善自己的理论体系。", "error_description": "体貌错误：“一直在”表示持续进行，不能与表示完成的“了”同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
