INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "对温度的高低进行控制。", "primary_collocate": null, "pronunciation": "wēn kòng", "ipa": "wən˥ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个杯子有温控，水一直很热。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空调的温控很简单。", "target_word": "温控", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天房间太热，要靠温控降温。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温控好的房间，冬天也很暖和。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个烤箱的温控不太准，蛋糕烤坏了。", "target_word": "温控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的房间需要好一点的温控。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家用手机就能管理温控。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "养热带鱼要注意水的温控。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服带着温控功能，冷热都不怕。", "target_word": "温控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机房里的温控很重要，机器不能太热。", "target_word": "温控", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "控制温度高低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b8958f0-ffe2-4271-bc78-1dc054604ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温控", "is_correct": true, "explanation": "温控：控制温度高低，与“杯子有温控，水一直很热”相符。"}, {"text": "字母", "is_correct": false, "explanation": "语义：字母与控制水温无关，杯子有字母不能使水保持热度。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体是文字的样式，与保温功能无关。"}, {"text": "歌词", "is_correct": false, "explanation": "搭配：“杯子有歌词”搭配不当，杯子的功能不指歌词。"}], "explanations": {"温控": "温控：控制温度高低，与“杯子有温控，水一直很热”相符。", "字母": "语义：字母与控制水温无关，杯子有字母不能使水保持热度。", "字体": "语义：字体是文字的样式，与保温功能无关。", "歌词": "搭配：“杯子有歌词”搭配不当，杯子的功能不指歌词。"}, "sentence_index": 0, "correct_answer": "温控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的温控很高，我们去游泳吧。", "explanation": "这里应该用〈气温〉。温控指控制温度的动作，不能形容天气的高低。"}, {"text": "他发烧了，温控很高。", "explanation": "这里应该用〈体温〉。温控不能形容人的体温高低，说人的体温要用体温。"}, {"text": "这个温度计能显示精确的温控。", "explanation": "这里应该用〈读数〉。温控指调节温度的动作，不能被显示；温度计显示的是读数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温控", "is_correct": true, "explanation": "温控：用手机控制温度的功能，与“我家用手机就能管理温控”相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，手机无法管理。"}, {"text": "时尚", "is_correct": false, "explanation": "语义：时尚不是可被管理的对象，与温度控制无关。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不是可以用手机管理的对象。"}], "explanations": {"温控": "温控：用手机控制温度的功能，与“我家用手机就能管理温控”相符。", "月亮": "语义：月亮是天体，手机无法管理。", "时尚": "语义：时尚不是可被管理的对象，与温度控制无关。", "春天": "语义：春天是季节，不是可以用手机管理的对象。"}, "sentence_index": 6, "correct_answer": "温控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个杯子装了一把温控，水很快就凉了。", "explanation": "量词用错。温控是控制过程，不能用“把”计量，应说“一套温控系统”。"}, {"text": "厨房里多了一根温控。", "explanation": "量词用错。“根”用于条状物，温控不能用“根”计量。"}, {"text": "我的新冰箱配了一颗温控。", "explanation": "量词用错。“颗”用于粒状物，温控不能用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把温控高调一点，房间会更暖和。", "corrected_sentence": "把温控调高一点，房间会更暖和。", "error_description": "“高调”应为“调高”。表示调节到更高，动词“调”在前，结果补语“高”在后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前用过这只温控。", "corrected_sentence": "我们以前用过这种温控。", "error_description": "量词错误：“温控”应配“种”，“只”用于动物或成对器物中的一个，不能用于“温控”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4e277-4461-49be-8fb2-4b479753ab00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
