INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "突然发生，很厉害。", "primary_collocate": null, "pronunciation": "bào fā xìng", "ipa": "pau˥˩ fa˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种病毒的暴发性很厉害。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洪的暴发性让人害怕。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生担心这种病有暴发性。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说地震也有暴发性。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴发性的大雨一下就是三个小时。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴发性疾病来得很快。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种暴发性疾病传得很快。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小河有暴发性，下雨时不要去玩。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为暴发性强，医院没有准备好。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要注意这场大雨的暴发性。", "target_word": "暴发性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暴發性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "来得突然而且很厉害的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb29fdd9-6bf5-4058-81eb-b0541dac5101') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暴发性", "is_correct": true, "explanation": "正确：暴发性指来得突然而且很厉害，“这种病毒的暴发性很厉害”符合语义。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色是外观特征，不能用“很厉害”来描述。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能用“很厉害”描述病毒的特征，句子语义不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是病毒的属性，“这种病毒的年龄很厉害”语义不通。"}], "explanations": {"暴发性": "正确：暴发性指来得突然而且很厉害，“这种病毒的暴发性很厉害”符合语义。", "颜色": "体貌：颜色是外观特征，不能用“很厉害”来描述。", "价格": "语义：价格不能用“很厉害”描述病毒的特征，句子语义不通。", "年龄": "语义：年龄不是病毒的属性，“这种病毒的年龄很厉害”语义不通。"}, "sentence_index": 0, "correct_answer": "暴发性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的老师有暴发性，所以大家都很喜欢她。", "explanation": "用法错误：暴发性形容疾病或事件突然猛烈，不用来形容人，这里应该说“性格”等词。"}, {"text": "这种暴发性很慢地传开。", "explanation": "这里混淆了〈渐进〉的意思。暴发性指来得快而猛，不能用来描述逐渐传开的过程。"}, {"text": "这把椅子的暴发性很强，很结实。", "explanation": "这里应该用〈结实〉。暴发性指疾病或事件来得突然、很猛烈，不能用来形容椅子的牢固程度；说椅子牢固应用“结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴发性", "is_correct": true, "explanation": "正确：暴发性指来得很快而猛，“这种暴发性疾病传得很快”符合语义。"}, {"text": "慢性", "is_correct": false, "explanation": "语义：慢性病发展缓慢，与“传得很快”矛盾。"}, {"text": "遗传性", "is_correct": false, "explanation": "语义：遗传性疾病通过基因传递，不靠快速传播，与“传得很快”的语义不符。"}, {"text": "老年性", "is_correct": false, "explanation": "搭配：“老年性疾病”多指与衰老相关的病症，不与“传得很快”搭配。"}], "explanations": {"暴发性": "正确：暴发性指来得很快而猛，“这种暴发性疾病传得很快”符合语义。", "慢性": "语义：慢性病发展缓慢，与“传得很快”矛盾。", "遗传性": "语义：遗传性疾病通过基因传递，不靠快速传播，与“传得很快”的语义不符。", "老年性": "搭配：“老年性疾病”多指与衰老相关的病症，不与“传得很快”搭配。"}, "sentence_index": 6, "correct_answer": "暴发性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种材料的暴发性很好，可以用很多年。", "explanation": "这里应该用〈持久性〉。暴发性指突然猛烈地发生，不能用来形容材料耐用的特点。"}, {"text": "我家的小狗有暴发性，一叫就是一个小时。", "explanation": "用法错误：暴发性指疾病或事件的特点，不能用来描述小狗的行为，应说“叫得很厉害”。"}, {"text": "这张照片的暴发性很强，大家都很喜欢。", "explanation": "用法错误：照片不是突发的疾病或事件，不能说“暴发性强”，应说“清晰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次洪水的暴发性把村子措手不及。", "corrected_sentence": "这次洪水的暴发性让村子措手不及。", "error_description": "用法错误：“措手不及”前应用“让”引出对象，不能用“把”，应说“这次洪水的暴发性让村子措手不及。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场大雨的暴发性强很，大家要小心。", "corrected_sentence": "这场大雨的暴发性很强，大家要小心。", "error_description": "程度副词位置错误：形容词谓语前应使用“很”，应说“很强”，不能说“强很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
