INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "光子是构成光的基本单位，是一种很小的粒子。", "primary_collocate": null, "pronunciation": "guāng zǐ", "ipa": "kuaŋ˥ tsɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "光子是让我们看见东西的小粒子。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一开，就有很多光子飞出来。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光子进到眼睛里，我们就能看见东西。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光子太小了，我们看不见它。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上看到了光子的图片。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拉上窗帘后，屋里几乎没有光子进来。", "target_word": "光子", "complexity_tier": "T3", "furigana": "guāng zǐ", "sentence_source": "generated"}, {"text": "太阳每秒送来无数光子。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说光就是光子。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光子的速度比汽车快得多。", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道光子是什么吗？", "target_word": "光子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "光子能量", "label": "复合"}], "register": "中性", "sense_fingerprint": "构成光的基本单位的很小粒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "光子", "is_correct": true, "explanation": "光子 guāng zǐ 指让我们看见东西的小粒子，是本题的正确答案。"}, {"text": "公子", "is_correct": false, "explanation": "公子 gōng zǐ 与 guāng zǐ 韵母不同（ong 与 ang），意思是贵族子弟。"}, {"text": "筐子", "is_correct": false, "explanation": "筐子 kuāng zi 与 guāng 声母不同（k 与 g），意思是箩筐。"}, {"text": "框子", "is_correct": false, "explanation": "框子 kuàng zi 与 guāng 声母不同（k 与 g），声调也不同（去声），意思是框架。"}, {"text": "管子", "is_correct": false, "explanation": "管子 guǎn zi 与 guāng zǐ 韵母不同（an 与 ang），声调也不同，意思是管道。"}], "explanations": {"光子": "光子 guāng zǐ 指让我们看见东西的小粒子，是本题的正确答案。", "公子": "公子 gōng zǐ 与 guāng zǐ 韵母不同（ong 与 ang），意思是贵族子弟。", "筐子": "筐子 kuāng zi 与 guāng 声母不同（k 与 g），意思是箩筐。", "框子": "框子 kuàng zi 与 guāng 声母不同（k 与 g），声调也不同（去声），意思是框架。", "管子": "管子 guǎn zi 与 guāng zǐ 韵母不同（an 与 ang），声调也不同，意思是管道。"}, "sentence_index": null, "correct_answer": "光子"}, "level_3": {"options": [{"text": "光子", "is_correct": true, "explanation": "句子给出的定义是能让我们看见东西的小粒子，只有光子符合。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是器官，不是能让我们看见东西的小粒子。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不是小粒子，句子的定义与它不符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“小粒子”不能修饰窗户这样的大型物体。"}], "explanations": {"光子": "句子给出的定义是能让我们看见东西的小粒子，只有光子符合。", "眼睛": "语义：眼睛是器官，不是能让我们看见东西的小粒子。", "太阳": "语义：太阳是天体，不是小粒子，句子的定义与它不符。", "窗户": "搭配：“小粒子”不能修饰窗户这样的大型物体。"}, "sentence_index": 0, "correct_answer": "光子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把光子擦得干干净净。", "explanation": "这里应该用〈玻璃〉。擦拭的是玻璃这类器物，光子是粒子，不能被擦。"}, {"text": "书桌上放着一只光子。", "explanation": "这里应该用〈个〉。量词“只”多用于动物或成对物品中的一件，光子是粒子，不能用“只”。"}, {"text": "我把光子关掉了，屋里一下子黑了。", "explanation": "这里应该用〈灯〉。关掉的是灯这类发光装置，光子是粒子，不能被关掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光子", "is_correct": true, "explanation": "太阳送来的是光的粒子，只有光子能与“无数”和“送来”的句意相合。"}, {"text": "雨点", "is_correct": false, "explanation": "搭配：“送来”多用于光、热等，不说送来雨点。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：太阳不会送来雪花，与太阳的光热义冲突。"}, {"text": "子弹", "is_correct": false, "explanation": "语义：太阳不会送来子弹，句子的意思不成立。"}], "explanations": {"光子": "太阳送来的是光的粒子，只有光子能与“无数”和“送来”的句意相合。", "雨点": "搭配：“送来”多用于光、热等，不说送来雨点。", "雪花": "语义：太阳不会送来雪花，与太阳的光热义冲突。", "子弹": "语义：太阳不会送来子弹，句子的意思不成立。"}, "sentence_index": 6, "correct_answer": "光子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树上结满了光子。", "explanation": "这里应该用〈果实〉。光子是粒子，不能像果实那样挂在树上。"}, {"text": "妈妈在厨房里把光子切成了块。", "explanation": "这里应该用〈面包〉。光子是粒子，不能被切成块，切的是面包这类食物。"}, {"text": "我的光子比小明高一头。", "explanation": "这里应该用〈个子〉。光子不是人，不能用来描述身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一台能记录一只光子的仪器。", "corrected_sentence": "这是一台能记录一个光子的仪器。", "error_description": "量词错误：光子是粒子，应说“一个光子”，不能说“一只光子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋子里有两光子在飞。", "corrected_sentence": "屋子里有两个光子在飞。", "error_description": "量词漏掉：数词“两”后要加量词“个”，应说“两个光子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
