INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26845, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "突然发生。", "primary_collocate": null, "pronunciation": "bào fā", "ipa": "pɑʊ̯˥˩ fa˥", "syllable_count": 2, "sentences": [{"text": "那个国家去年爆发了战争。", "target_word": "爆发", "complexity_tier": "T3", "furigana": "nà gè guó jiā qù nián bào fā le zhàn zhēng", "sentence_source": "generated"}, {"text": "新年前，这个城市爆发了流感。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里下大雨，山洪爆发了。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里爆发出一阵笑声。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛后，球迷之间爆发了争吵。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那座火山明天可能爆发。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辛亥革命在一九一一年爆发。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忍了很久，终于爆发了，大声喊了出来。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这个地方爆发过一次严重的疫情。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家为了边界问题爆发了冲突。", "target_word": "爆发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爆发了", "label": "体标"}, {"form": "爆发过", "label": "体标"}, {"form": "爆发力", "label": "复合"}, {"form": "爆發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情或情绪突然发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb29fdd9-6bf5-4058-81eb-b0541dac5101') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26845, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爆发", "is_correct": true, "explanation": "正确：“爆发”指战争突然发生，“爆发了战争”符合句意。"}, {"text": "生产", "is_correct": false, "explanation": "语义：战争不是产品，不能说“生产了战争”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“战争”不说“打扫”，二者不搭配。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求可以吃的东西作宾语，战争不能被吃。"}], "explanations": {"爆发": "正确：“爆发”指战争突然发生，“爆发了战争”符合句意。", "生产": "语义：战争不是产品，不能说“生产了战争”。", "打扫": "搭配：“战争”不说“打扫”，二者不搭配。", "吃": "配价：“吃”要求可以吃的东西作宾语，战争不能被吃。"}, "sentence_index": 0, "correct_answer": "爆发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下周学校就要爆发了。", "explanation": "这里应该用〈开学〉。学期开始要用“开学”，“爆发”指突然发生的事件。"}, {"text": "我们学校爆发于一九〇〇年。", "explanation": "这里应该用〈创办〉。学校成立不用“爆发”，“爆发”指事件突然发生。"}, {"text": "一颗炸弹爆发了。", "explanation": "这里应该用〈爆炸〉。炸弹炸开要用“爆炸”，“爆发”不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爆发", "is_correct": true, "explanation": "正确：“爆发”指革命在某一年发生，“辛亥革命在一九一一年爆发”是通行的说法。"}, {"text": "沉睡", "is_correct": false, "explanation": "语义：沉睡是睡着不醒，不能用来说革命的发生。"}, {"text": "盛开", "is_correct": false, "explanation": "搭配：“盛开”用于花朵，不说革命盛开。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是人的行为，革命不会唱歌，句子说不通。"}], "explanations": {"爆发": "正确：“爆发”指革命在某一年发生，“辛亥革命在一九一一年爆发”是通行的说法。", "沉睡": "语义：沉睡是睡着不醒，不能用来说革命的发生。", "盛开": "搭配：“盛开”用于花朵，不说革命盛开。", "唱歌": "语义：唱歌是人的行为，革命不会唱歌，句子说不通。"}, "sentence_index": 6, "correct_answer": "爆发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜晚爆发了。", "explanation": "这里应该用〈降临〉。夜晚到来要用“降临”，“爆发”指事件突然发生。"}, {"text": "种子在春天爆发了。", "explanation": "这里应该用〈发芽〉。种子长出芽要用“发芽”，“爆发”不表示这种变化。"}, {"text": "这家商店下周爆发。", "explanation": "这里应该用〈开业〉。商店开张要用“开业”，“爆发”指事件突然发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室里突然爆发了出一阵争吵。", "corrected_sentence": "会议室里突然爆发出一阵争吵。", "error_description": "体标与补语错误：“了”不能放在补语“出”前面，应说“爆发出一阵争吵”或“爆发出了一阵争吵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个小镇前年爆发了过一场山洪。", "corrected_sentence": "那个小镇前年爆发过一场山洪。", "error_description": "体标错误：“过”表示经历，不能和“了”同时用在“爆发”后面，应说“爆发过一场山洪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
