INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26850, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能源安全就是保证大家有足够的电和油来用，不会突然没有。", "primary_collocate": null, "pronunciation": "néng yuán ān quán", "ipa": "nɤŋ˧˥ ɥɛn˧˥ an˥ tɕʰɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "能源安全就是有足够的电和油。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有能源安全，晚上可能没有电。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了能源安全。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了能源安全，国家准备了很多油。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能源安全让我们每天都有电用。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市很注意能源安全。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校今天的课是关于能源安全的，讲的是怎样保证电和油不断供。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想知道能源安全是什么意思。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节约用电也是为了能源安全。", "target_word": "能源安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能源安全出了问题，冬天就会缺少暖气和电力。", "target_word": "能源安全", "complexity_tier": "T3", "furigana": "néng yuán ān quán chū le wèn tí, dōng tiān jiù huì quē shǎo nuǎn qì hé diàn lì。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国家能源安全", "label": "复合"}], "register": "正式", "sense_fingerprint": "保证有足够的电和油可用，不会突然没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粮食安全", "is_correct": false, "explanation": "语义：“能源安全”指保证有足够的电和油可用，“粮食安全”指食物供应，句子的定义不符。"}, {"text": "能源安全", "is_correct": true, "explanation": "能源安全：保证大家有足够的电和油来用，不会突然没有，与句子定义相符。"}, {"text": "油井", "is_correct": false, "explanation": "语义：“油井”是一种设施，不是保证电和油可用的状态，与句子定义不符。"}, {"text": "环境保护", "is_correct": false, "explanation": "语义：“环境保护”是另一个概念，不是保证电和油可用，与句子定义不符。"}], "explanations": {"粮食安全": "语义：“能源安全”指保证有足够的电和油可用，“粮食安全”指食物供应，句子的定义不符。", "能源安全": "能源安全：保证大家有足够的电和油来用，不会突然没有，与句子定义相符。", "油井": "语义：“油井”是一种设施，不是保证电和油可用的状态，与句子定义不符。", "环境保护": "语义：“环境保护”是另一个概念，不是保证电和油可用，与句子定义不符。"}, "sentence_index": 0, "correct_answer": "能源安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石油价格上涨后，我们遇到了能源安全。", "explanation": "这里应该用〈能源危机〉。能源安全指稳定供应的状态，不指已经发生的危机，不能说“遇到”。"}, {"text": "这个国家的能源安全有一千万吨。", "explanation": "这里应该用〈能源储备〉。能源安全是状态，不能用数量计量；有一千万吨的是储存的能源。"}, {"text": "最近能源安全上涨了不少。", "explanation": "这里应该用〈能源价格〉。“上涨”用于价格、物价，不能用于能源安全这种状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "八卦", "is_correct": false, "explanation": "语义：“八卦”是闲话，与讲怎样保证电和油不断供的课程内容不符。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”偏口语，且与讲怎样保证电和油不断供的课程内容不符。"}, {"text": "能源安全", "is_correct": true, "explanation": "能源安全：学校课程的主题，与后半句讲的电和油供应相符。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：“宠物”与讲怎样保证电和油不断供的课程内容不符。"}], "explanations": {"八卦": "语义：“八卦”是闲话，与讲怎样保证电和油不断供的课程内容不符。", "笑话": "语义：“笑话”偏口语，且与讲怎样保证电和油不断供的课程内容不符。", "能源安全": "能源安全：学校课程的主题，与后半句讲的电和油供应相符。", "宠物": "语义：“宠物”与讲怎样保证电和油不断供的课程内容不符。"}, "sentence_index": 6, "correct_answer": "能源安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市拥有一只稳定的能源安全。", "explanation": "这里应该用〈种〉。“只”是动物量词，不能用来计量“能源安全”。"}, {"text": "这座城市拥有一棵稳定的能源安全。", "explanation": "这里应该用〈种〉。“棵”用于树木，不能用来计量“能源安全”。"}, {"text": "这座城市拥有一本稳定的能源安全。", "explanation": "这里应该用〈种〉。“本”用于书籍，不能用来计量“能源安全”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年能源安全了很稳定。", "corrected_sentence": "今年能源安全很稳定。", "error_description": "错误形式是在名词“能源安全”后多加了“了”，写作“能源安全了很稳定”；正确形式是“能源安全很稳定”。形容词作谓语时，“了”不能紧跟在作主语的名词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只能源安全，大家都很关心。", "corrected_sentence": "这种能源安全，大家都很关心。", "error_description": "“只”是动物量词，不能计量抽象的“能源安全”；应为“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
