INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "石油是一种重要的能源，如果大家没有足够的石油，就会发生大问题，这就是石油危机。", "primary_collocate": null, "pronunciation": "shí yóu wēi jī", "ipa": "ʂɨ˧˥ iou̯˧˥ weɪ̯˥ tɕi˥", "syllable_count": 4, "sentences": [{"text": "没有足够的石油，就会出现石油危机。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油危机来了，很多汽车没油可用。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油危机让大家的生活变得很困难。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不再遇到石油危机，国家开始用太阳能。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说石油危机的时候，人们排队买汽油。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是石油危机时的故事。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油危机使汽油变得特别贵。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里，老师给我们介绍了石油危机。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷还记得当年的石油危机。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发生石油危机时，政府要求大家少开车。", "target_word": "石油危机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "石油危機", "label": "繁体"}, {"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "石油不够用而引起的大问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb29fdd9-6bf5-4058-81eb-b0541dac5101') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石油危机", "is_correct": true, "explanation": "正确：石油危机是石油不足引发的问题，可以作“出现”的宾语，符合句意。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，与“石油不够用”没有因果关系，句子说不通。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是雨后的天象，不会因为没有石油而出现。"}, {"text": "乌龙", "is_correct": false, "explanation": "语域：“乌龙”是口语俗语，不适合这种说明性的句子。"}], "explanations": {"石油危机": "正确：石油危机是石油不足引发的问题，可以作“出现”的宾语，符合句意。", "地震": "语义：地震是自然灾害，与“石油不够用”没有因果关系，句子说不通。", "彩虹": "语义：彩虹是雨后的天象，不会因为没有石油而出现。", "乌龙": "语域：“乌龙”是口语俗语，不适合这种说明性的句子。"}, "sentence_index": 0, "correct_answer": "石油危机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在石油危机上钻井。", "explanation": "这里应该用〈油田〉。危机是事件，不能钻井；钻井的地方是油田。"}, {"text": "石油危机在海上航行。", "explanation": "这里应该用〈油轮〉。危机不会航行，在海上航行的是油轮。"}, {"text": "这孩子不爱吃饭，只爱吃石油危机。", "explanation": "这里应该用〈零食〉。“吃”的对象是食物，危机是事件，不能吃；孩子爱吃的是零食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石油危机", "is_correct": true, "explanation": "正确：石油危机能引起物价变化，可以作“使汽油变贵”的施事。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是日子，不会使汽油变得特别贵。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“使汽油变贵”要求能影响价格的因素作施事，小猫不搭配这一说法。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是娱乐活动，与汽油价格没有因果关系。"}], "explanations": {"石油危机": "正确：石油危机能引起物价变化，可以作“使汽油变贵”的施事。", "生日": "语义：生日是日子，不会使汽油变得特别贵。", "小猫": "搭配：“使汽油变贵”要求能影响价格的因素作施事，小猫不搭配这一说法。", "演唱会": "语义：演唱会是娱乐活动，与汽油价格没有因果关系。"}, "sentence_index": 6, "correct_answer": "石油危机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石油危机睡着了。", "explanation": "这里应该用〈孩子〉。“睡着”说的是人或动物，危机不会睡觉；睡着的是孩子。"}, {"text": "石油危机很辛苦。", "explanation": "这里应该用〈石油工人〉。“辛苦”说的是人，不能用来形容危机。"}, {"text": "石油危机在周末关门了。", "explanation": "这里应该用〈加油站〉。危机不会开门或关门，关门的是加油站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那一代人都经历了过石油危机。", "corrected_sentence": "那一代人都经历过石油危机。", "error_description": "体标错误：“过”表示经历，不能和“了”同时用在“经历”后面，应说“经历过石油危机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家曾经历过过石油危机。", "corrected_sentence": "这个国家曾经历过石油危机。", "error_description": "体标重复：“经历过”的“过”只用一次，多加的一个“过”是错误的。正确形式是“这个国家曾经历过石油危机。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc86f948-514e-4663-8f54-2518f42741d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
