INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26854, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个东西猛烈地碰在一起。", "primary_collocate": null, "pronunciation": "zhuàng jī", "ipa": "ʈʂwɑŋ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "两个玻璃球撞击后，发出清脆的声音。", "target_word": "撞击", "complexity_tier": "T3", "furigana": "zhuàng jī", "sentence_source": "generated"}, {"text": "孩子们用两根棍子互相撞击，玩得很开心。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车进站时，车厢互相撞击了一下。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰块撞击杯壁，叮叮地响。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两颗小球撞击后，向两边滚开了。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把两块石头撞击在一起，想生火。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹着风铃，它们互相撞击，声音很好听。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨撞击屋顶的声音让我睡不着。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两辆小车在游戏里撞击了好几次。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台球撞击的声音在房间里很响。", "target_word": "撞击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撞击了", "label": "体标（了）"}, {"form": "撞击着", "label": "体标（着）"}, {"form": "撞击过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "两个东西猛烈碰在一起，常发出声响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撞击", "is_correct": true, "explanation": "撞击指两个玻璃球碰在一起并发出清脆的声音，与句意相合。"}, {"text": "缠绕", "is_correct": false, "explanation": "语义：缠绕是绕住的意思，两个玻璃球缠绕不会发出清脆的声音。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：玻璃球熔化后不会再碰撞发声，与句中的声音描写冲突。"}, {"text": "切割", "is_correct": false, "explanation": "配价：“切割”需要工具和被切之物，这里缺少相应的成分。"}], "explanations": {"撞击": "撞击指两个玻璃球碰在一起并发出清脆的声音，与句意相合。", "缠绕": "语义：缠绕是绕住的意思，两个玻璃球缠绕不会发出清脆的声音。", "熔化": "语义：玻璃球熔化后不会再碰撞发声，与句中的声音描写冲突。", "切割": "配价：“切割”需要工具和被切之物，这里缺少相应的成分。"}, "sentence_index": 0, "correct_answer": "撞击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们两个人轻轻撞击了一下手，笑着说再见。", "explanation": "这里应该用〈击掌〉。撞击力度大，轻轻相碰的动作要说击掌。"}, {"text": "妈妈撞击着我，让我觉得很温暖。", "explanation": "这里应该用〈拥抱〉。撞击带有猛烈相碰的意思，温暖的动作要说拥抱。"}, {"text": "我用抹布撞击桌子，把灰尘擦干净了。", "explanation": "这里应该用〈抹〉。撞击指两物猛烈相碰，抹桌子这类轻柔的清洁动作要用抹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撞击", "is_correct": true, "explanation": "撞击指风铃互相碰上并发出好听的声音，与句意相合。"}, {"text": "撕扯", "is_correct": false, "explanation": "语义：撕扯是用力拉扯，风铃互相撕扯不会发出好听的声音。"}, {"text": "翻滚", "is_correct": false, "explanation": "语义：风铃不会翻滚，句中“声音很好听”也无法与翻滚成立。"}, {"text": "挥舞", "is_correct": false, "explanation": "搭配：“挥舞”的主语一般是人或手，风铃不能与“互相”搭配挥舞。"}], "explanations": {"撞击": "撞击指风铃互相碰上并发出好听的声音，与句意相合。", "撕扯": "语义：撕扯是用力拉扯，风铃互相撕扯不会发出好听的声音。", "翻滚": "语义：风铃不会翻滚，句中“声音很好听”也无法与翻滚成立。", "挥舞": "搭配：“挥舞”的主语一般是人或手，风铃不能与“互相”搭配挥舞。"}, "sentence_index": 6, "correct_answer": "撞击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的手指撞击着钢琴，弹出了一首好听的曲子。", "explanation": "这里应该用〈演奏〉。撞击指两物猛烈相碰，用手指按键演奏钢琴要用演奏。"}, {"text": "我今天撞击了一双新鞋。", "explanation": "这里应该用〈穿〉。撞击不能用于鞋子，穿鞋要用穿。"}, {"text": "两个朋友在路上撞击了一会儿，然后分开了。", "explanation": "这里应该用〈聊〉。撞击指猛烈相碰，朋友之间说话要用聊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两块石头互相了撞击，冒出了火花。", "corrected_sentence": "两块石头互相撞击，冒出了火花。", "error_description": "体标错误：“了”误加在状语“互相”和动词“撞击”之间，应删去，正确说法是“两块石头互相撞击”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两只杯子了撞击后，发出清脆的声音。", "corrected_sentence": "两只杯子撞击后，发出清脆的声音。", "error_description": "体标错误：“了”误加在主语“两只杯子”和动词“撞击”之间，应删去，正确说法是“两只杯子撞击后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
