INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电流是电在电线里流动，就像水流在水管里一样。", "primary_collocate": null, "pronunciation": "diàn liú", "ipa": "tjɛn˥˩ ljou˧˥", "syllable_count": 2, "sentences": [{"text": "电线里有电流，不要用手去摸。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电流在电线里走，就像水在管子里流。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯亮的时候，电线里有电流通过。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电了，电线里没有电流了。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不懂，以为电流是看得见的东西。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把充电线插上，电流就进手机了。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，电流太大，电线会变热。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电流从插座进入电视机。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿手碰插座，电流容易让人受伤。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管里有水流，电线里有电流。", "target_word": "电流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}, {"form": "电流表", "label": "复合"}], "register": "中性", "sense_fingerprint": "电在电线里流动，像水在水管里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e92c63b-3679-442a-a17d-628878172573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26856, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电流", "is_correct": true, "explanation": "diàn liú，电在电线里流动，即正确答案。"}, {"text": "限流", "is_correct": false, "explanation": "xiàn（第四声）与 diàn（第四声）声母不同（x 与 d），意思是限制流量。"}, {"text": "断流", "is_correct": false, "explanation": "duàn（第四声）与 diàn（第四声）声母相同，韵母仅介音不同（uan 与 ian），意思是河流断绝。"}, {"text": "变流", "is_correct": false, "explanation": "biàn（第四声）与 diàn（第四声）韵母相同、声母不同（b 与 d），意思是变换电流。"}], "explanations": {"电流": "diàn liú，电在电线里流动，即正确答案。", "限流": "xiàn（第四声）与 diàn（第四声）声母不同（x 与 d），意思是限制流量。", "断流": "duàn（第四声）与 diàn（第四声）声母相同，韵母仅介音不同（uan 与 ian），意思是河流断绝。", "变流": "biàn（第四声）与 diàn（第四声）韵母相同、声母不同（b 与 d），意思是变换电流。"}, "sentence_index": null, "correct_answer": "电流"}, "level_3": {"options": [{"text": "电流", "is_correct": true, "explanation": "正确：电线里的电流有触电危险，所以不要用手去摸，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：电线里不会有可以用手去摸的空气，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见，无法用手去摸，与句意矛盾。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“摸”不能用于“香味”，与“用手去摸”搭配不当。"}], "explanations": {"电流": "正确：电线里的电流有触电危险，所以不要用手去摸，句意通顺。", "空气": "语义：电线里不会有可以用手去摸的空气，句意不通。", "声音": "语义：声音看不见，无法用手去摸，与句意矛盾。", "香味": "搭配：“摸”不能用于“香味”，与“用手去摸”搭配不当。"}, "sentence_index": 0, "correct_answer": "电流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根电流很粗，能承受更大的功率。", "explanation": "这里应该用〈电线〉。电线是导线，有粗细；电流是电的流动，没有粗细。"}, {"text": "墙里的电流得重新铺一下。", "explanation": "这里应该用〈电线〉。电线是可以铺设的导线；电流是电的流动，不能铺设。"}, {"text": "这节电池的电流是三伏。", "explanation": "这里应该用〈电压〉。伏是电压的单位，电流的单位是安培。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电流", "is_correct": true, "explanation": "正确：电流太大时电线会发热，符合句意。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数太大与电线变热无关，句意不通。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声太大不会使电线变热，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”说“大”不符合习惯，与“太大”搭配不当。"}], "explanations": {"电流": "正确：电流太大时电线会发热，符合句意。", "人数": "语义：人数太大与电线变热无关，句意不通。", "歌声": "语义：歌声太大不会使电线变热，句意不通。", "脚步": "搭配：“脚步”说“大”不符合习惯，与“太大”搭配不当。"}, "sentence_index": 6, "correct_answer": "电流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河里的电流很急。", "explanation": "这里应该用〈水流〉。“急”形容水的流动；电流在导线里流动，不在河里，也不能用“急”来形容。"}, {"text": "这台风扇插上电流就能转起来。", "explanation": "这里应该用〈电源〉。插上的应是供电的电源；电流是电的流动，不能被插上。"}, {"text": "这台机器的电流开关坏了。", "explanation": "这里应该用〈电源〉。电源是供电的装置，可以有开关；电流是电的流动，不能作开关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根电线里通过了很强地电流。", "corrected_sentence": "这根电线里通过了很强的电流。", "error_description": "结构助词错误：“很强”修饰名词“电流”时要用“的”，应说“很强的电流”；“地”用于修饰动词，不能说“很强地电流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电线里通过了一把电流。", "corrected_sentence": "电线里通过了一股电流。", "error_description": "量词错误：“电流”应搭配量词“股”，“把”用于有柄的东西，不能修饰“电流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
