INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电能是一种可以点亮灯泡、让电视工作的力量。", "primary_collocate": null, "pronunciation": "diàn néng", "ipa": "tjɛn˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "电能让灯泡亮起来。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电视机需要电能才能工作。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机的电能用光了，就开不了机。", "target_word": "电能", "complexity_tier": "T3", "furigana": "diàn néng", "sentence_source": "generated"}, {"text": "电能可以让风扇转起来。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "用电能烧水又快又干净。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台冰箱一天要用很多电能。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能板能把阳光变成电能。", "target_word": "电能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关灯能省下不少电能。", "target_word": "电能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电能让我们的生活更方便。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小火车靠电能在轨道上跑。", "target_word": "电能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "电能表", "label": "复合"}], "register": "通俗", "sense_fingerprint": "能点亮灯泡、让电器工作的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a88376a6-aa5b-449c-a391-acd929036bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "搭配：“亮起来”说的是灯、光，不搭配“感情”。"}, {"text": "风扇", "is_correct": false, "explanation": "语义：风扇转动，不能使灯泡发光。"}, {"text": "电能", "is_correct": true, "explanation": "正确：电能可以让灯泡发光，与“让灯泡亮起来”相符。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸不能供电，也不能让灯泡亮起来。"}], "explanations": {"感情": "搭配：“亮起来”说的是灯、光，不搭配“感情”。", "风扇": "语义：风扇转动，不能使灯泡发光。", "电能": "正确：电能可以让灯泡发光，与“让灯泡亮起来”相符。", "报纸": "语义：报纸不能供电，也不能让灯泡亮起来。"}, "sentence_index": 0, "correct_answer": "电能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天吃饭，身体里的电能很充足。", "explanation": "这里应该用〈能量〉。电能专指由电产生的能量，人的精力不说“电能”。"}, {"text": "这节电池的电能是一点五伏。", "explanation": "这里应该用〈电压〉。“伏”计量的是电压，电能应以“度”或“千瓦时”计量，不能用伏数来说。"}, {"text": "这台电风扇的电能是六十瓦。", "explanation": "这里应该用〈功率〉。“瓦”计量的是功率，电能应以“度”或“千瓦时”计量，不能用瓦数来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面粉", "is_correct": false, "explanation": "语义：太阳能板不能把阳光变成面粉。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“变成”后接能量或物质，“温度”是量度，不能作为转化结果。"}, {"text": "电能", "is_correct": true, "explanation": "正确：太阳能板把阳光转化后得到的是电能，与“变成”相符。"}, {"text": "木头", "is_correct": false, "explanation": "语义：阳光不会变成木头。"}], "explanations": {"面粉": "语义：太阳能板不能把阳光变成面粉。", "温度": "搭配：“变成”后接能量或物质，“温度”是量度，不能作为转化结果。", "电能": "正确：太阳能板把阳光转化后得到的是电能，与“变成”相符。", "木头": "语义：阳光不会变成木头。"}, "sentence_index": 6, "correct_answer": "电能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的电能有三百大卡。", "explanation": "这里应该用〈热量〉。食物所含的能量要用“大卡”计量，说“热量”；电能指由电产生的能量，不能用来形容食物。"}, {"text": "这艘帆船靠风的电能在海上前进。", "explanation": "这里应该用〈动力〉。帆船借风力前进，要说“动力”，电能是电的能量。"}, {"text": "这根导线里的电能是五安。", "explanation": "这里应该用〈电流〉。“安”计量的是电流，电能应以“度”或“千瓦时”计量，不能用安数来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块电池的电能已经耗了完。", "corrected_sentence": "这块电池的电能已经耗完了。", "error_description": "错误：“耗了完”；正确：“耗完了”。结果补语“完”紧跟动词“耗”，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块太阳能板能把阳光转化电能。", "corrected_sentence": "这块太阳能板能把阳光转化成电能。", "error_description": "错误：“转化电能”；正确：“转化成电能”。“转化”后须接“成”引出结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
