INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电子是小小的、带负电的东西，在电里跑来跑去。", "primary_collocate": null, "pronunciation": "diàn zǐ", "ipa": "tjɛn˥˩ tsɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "电子很小，我们用眼睛看不到它。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，电子在电线里跑来跑去。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子带负电，和正电互相吸引。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池里的电子一动，灯就亮了。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本上画着很多小小的电子。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子跑得很快，一秒钟能跑很远。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不明白电子为什么总在电线里动。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子从电池的一头跑到另一头。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明问老师：“电子长什么样子？”", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有电子，灯就不会亮。", "target_word": "电子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个电子", "label": "量词（个）"}, {"form": "電子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很小、带负电、在电中跑来跑去的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc1cec68-d878-4094-9209-243e8af8fb55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：电子（diàn zǐ），小小的、带负电的东西。"}, {"text": "点子", "is_correct": false, "explanation": "diǎn（第三声）与 diàn（第四声）声调不同，“点子”意思是主意。"}, {"text": "链子", "is_correct": false, "explanation": "liàn 与 diàn 声母不同（l 与 d），“链子”意思是链条。"}, {"text": "辫子", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 与 d），“辫子”意思是编起来的头发。"}, {"text": "片子", "is_correct": false, "explanation": "piàn 与 diàn 声母不同（p 与 d），“片子”意思是影片或片状的东西。"}, {"text": "面子", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 与 d），“面子”意思是颜面。"}], "explanations": {"电子": "正确：电子（diàn zǐ），小小的、带负电的东西。", "点子": "diǎn（第三声）与 diàn（第四声）声调不同，“点子”意思是主意。", "链子": "liàn 与 diàn 声母不同（l 与 d），“链子”意思是链条。", "辫子": "biàn 与 diàn 声母不同（b 与 d），“辫子”意思是编起来的头发。", "片子": "piàn 与 diàn 声母不同（p 与 d），“片子”意思是影片或片状的东西。", "面子": "miàn 与 diàn 声母不同（m 与 d），“面子”意思是颜面。"}, "sentence_index": null, "correct_answer": "电子"}, "level_3": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：电子很小，肉眼看不到，与句意相符。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体型庞大，与“很小”和“看不到”矛盾。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜又大又显眼，用眼睛看得到，与句意不合。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是大型机械，肉眼很容易看到，与句中描述不符。"}], "explanations": {"电子": "正确：电子很小，肉眼看不到，与句意相符。", "大象": "体貌：大象体型庞大，与“很小”和“看不到”矛盾。", "西瓜": "语义：西瓜又大又显眼，用眼睛看得到，与句意不合。", "汽车": "语义：汽车是大型机械，肉眼很容易看到，与句中描述不符。"}, "sentence_index": 0, "correct_answer": "电子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今晚停电子了，屋里一片漆黑。", "explanation": "这里应该用〈电〉。“停”搭配的是电（停电），电子是小小的粒子，不能说停电子。"}, {"text": "电子断了，灯就不亮了。", "explanation": "这里应该用〈电流〉。断的是电流或电路，电子是小小的粒子，不说“断电子”。"}, {"text": "这个原子里有两辆电子。", "explanation": "这里应该用〈个〉。“辆”用于车，电子应说“两个电子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电子", "is_correct": true, "explanation": "正确：句中的主语是电子，指会运动的微观粒子。"}, {"text": "石碑", "is_correct": false, "explanation": "语义：“石碑”是静止的石刻，不会在电线里运动，与句中的电子语境不合。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：“墙壁”是建筑构件，不会在电线里运动，与句中的电子语境不合。"}, {"text": "高山", "is_correct": false, "explanation": "体貌：“高山”巨大稳固，不会在电线里运动，与“电子”这一微观粒子的语境不符。"}], "explanations": {"电子": "正确：句中的主语是电子，指会运动的微观粒子。", "石碑": "语义：“石碑”是静止的石刻，不会在电线里运动，与句中的电子语境不合。", "墙壁": "语义：“墙壁”是建筑构件，不会在电线里运动，与句中的电子语境不合。", "高山": "体貌：“高山”巨大稳固，不会在电线里运动，与“电子”这一微观粒子的语境不符。"}, "sentence_index": 6, "correct_answer": "电子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电线外面包着一层电子，不导电。", "explanation": "这里应该用〈橡胶〉。电子不能作为包覆电线的绝缘材料，包电线用橡胶。"}, {"text": "电子太高，灯泡会烧坏。", "explanation": "这里应该用〈电压〉。“高”说的是电压高低，电子是小小的粒子，不说“电子太高”。"}, {"text": "这个原子核外有三只电子。", "explanation": "这里应该用〈个〉。量词“只”不用于电子，应说“三个电子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个电池里有三只电子在跑。", "corrected_sentence": "这个电池里有三个电子在跑。", "error_description": "量词错误：电子应用量词“个”，“只”不用于电子。应说“三个电子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两电子跑得很快。", "corrected_sentence": "这两个电子跑得很快。", "error_description": "量词漏掉：指示代词加数词“这两”后要加量词“个”，应说“这两个电子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e13668d-4735-4d8f-89cd-ed05b42e9fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
