INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26866, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一层一层地堆起来。", "primary_collocate": null, "pronunciation": "dié céng", "ipa": "tjɛ˧˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "工人把薄板叠层压合，做成了一块厚板。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "gōng rén bǎ báo bǎn dié céng yā hé, zuò chéng le yí kuài hòu bǎn.", "sentence_source": "generated"}, {"text": "先把薄布叠层粘合，再裁成小块。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "xiān bǎ báo bù dié céng zhān hé, zài cái chéng xiǎo kuài.", "sentence_source": "generated"}, {"text": "这些纸板要叠层压实，然后再裁切。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "zhè xiē zhǐ bǎn yào dié céng yā shí, rán hòu zài cái qiē.", "sentence_source": "generated"}, {"text": "工厂把铁片叠层焊接，做成了金属箱。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "gōng chǎng bǎ tiě piàn dié céng hàn jiē, zuò chéng le jīn shǔ xiāng.", "sentence_source": "generated"}, {"text": "这些薄片经过叠层压制，会变得更厚。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "zhè xiē báo piàn jīng guò dié céng yā zhì, huì biàn de gèng hòu.", "sentence_source": "generated"}, {"text": "我们把石片叠层堆砌，做成了一座小塔。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "wǒ men bǎ shí piàn dié céng duī qì, zuò chéng le yí zuò xiǎo tǎ.", "sentence_source": "generated"}, {"text": "电池片叠层封装后，能多吸收一些光。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "diàn chí piàn dié céng fēng zhuāng hòu, néng duō xī shōu yì xiē guāng.", "sentence_source": "generated"}, {"text": "师傅正把木片叠层胶合，做成一块厚板。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "shī fu zhèng bǎ mù piàn dié céng jiāo hé, zuò chéng yí kuài hòu bǎn.", "sentence_source": "generated"}, {"text": "这些薄膜需要叠层加压，然后再使用。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "zhè xiē báo mó xū yào dié céng jiā yā, rán hòu zài shǐ yòng.", "sentence_source": "generated"}, {"text": "把面片叠层压平，再放进锅里蒸。", "target_word": "叠层", "complexity_tier": "T3", "furigana": "bǎ miàn piàn dié céng yā píng, zài fàng jìn guō lǐ zhēng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "疊層", "label": "繁体"}, {"form": "叠层了", "label": "体标"}, {"form": "叠层过", "label": "体标"}], "register": "中性", "sense_fingerprint": "叠层|动作|一层层堆起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92b8e895-07d2-430a-a35a-f19f0da65d06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叠层", "is_correct": true, "explanation": "「把薄板叠层压合」指把薄板一层层堆起来再压合，符合句意。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：切割是把薄板分开，与「压合成厚板」的结果相反，不能与「压合」搭配。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干是去除水分，与「做成一块厚板」的过程无关。"}, {"text": "涂色", "is_correct": false, "explanation": "语义：涂色是给表面上颜色，与「压合成厚板」不相关。"}], "explanations": {"叠层": "「把薄板叠层压合」指把薄板一层层堆起来再压合，符合句意。", "切割": "搭配：切割是把薄板分开，与「压合成厚板」的结果相反，不能与「压合」搭配。", "烘干": "语义：烘干是去除水分，与「做成一块厚板」的过程无关。", "涂色": "语义：涂色是给表面上颜色，与「压合成厚板」不相关。"}, "sentence_index": 0, "correct_answer": "叠层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他叠层地跑完了整个马拉松。", "explanation": "用法错误：「叠层」是把薄片一层层堆起来的动作，不能用来形容跑步。"}, {"text": "他把碗叠层放进柜子里。", "explanation": "这里应该用〈摞〉。叠层强调一层层压起来的薄片或板材，碗一般说「摞」。"}, {"text": "煤炭在地上叠层成山。", "explanation": "这里应该用〈堆积〉。煤炭成山是堆积，「叠层」多用于薄片或板材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叠层", "is_correct": true, "explanation": "「电池片叠层封装」指把电池片一层层叠起来封装，符合句意。"}, {"text": "切碎", "is_correct": false, "explanation": "语义：切碎的电池片不能再整体封装，与“叠层封装”的意思矛盾。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：雕刻是在材料上刻出图案，与封装电池片无关。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：擦拭是清洁表面，与「封装后能多吸收光」的意思不搭。"}], "explanations": {"叠层": "「电池片叠层封装」指把电池片一层层叠起来封装，符合句意。", "切碎": "语义：切碎的电池片不能再整体封装，与“叠层封装”的意思矛盾。", "雕刻": "语义：雕刻是在材料上刻出图案，与封装电池片无关。", "擦拭": "搭配：擦拭是清洁表面，与「封装后能多吸收光」的意思不搭。"}, "sentence_index": 6, "correct_answer": "叠层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把衣服叠层整齐放进箱子。", "explanation": "这里应该用〈折叠〉。整理衣服要说「折叠」，「叠层」强调一层层堆起来。"}, {"text": "他把杯子叠层摆在桌上。", "explanation": "这里应该用〈摆放〉。杯子之间不形成一层层叠加，应说「摆放」。"}, {"text": "她叠层地读完了整本书。", "explanation": "用法错误：「叠层」是把薄片一层层堆起来的动作，不能用来形容读书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先把铁皮叠层了焊牢。", "corrected_sentence": "先把铁皮叠层焊牢。", "error_description": "体标位置错误：“了”插在连续动词“叠层”和“焊牢”之间，句子不通顺，应说「先把铁皮叠层焊牢」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师纸板叠层压实。", "corrected_sentence": "老师把纸板叠层压实。", "error_description": "漏了“把”：「纸板」作为处置对象，句中必须用“把”，应说「老师把纸板叠层压实」，不能说「老师纸板叠层压实」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35b39b2-c628-4526-b903-c99983e867e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
