INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26872, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种像石头一样的材料，可以用来做太阳能板，把阳光变成电。", "primary_collocate": null, "pronunciation": "gài tài kuàng", "ipa": "kai˥˩ tʰai˥˩ kʰuaŋ˥˩", "syllable_count": 3, "sentences": [{"text": "钙钛矿像石头，可以做太阳能板。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种钙钛矿能把阳光变成电。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一块钙钛矿。", "target_word": "钙钛矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钙钛矿很轻，也很薄。", "target_word": "钙钛矿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在书里读到过钙钛矿。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上的板子是用钙钛矿做的。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钙钛矿可以让电变得更便宜。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解什么是钙钛矿。", "target_word": "钙钛矿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钙钛矿太阳能板在阳光下工作得很好。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，钙钛矿有很大的用处。", "target_word": "钙钛矿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鈣鈦礦", "label": "繁体"}, {"form": "钙钛矿电池", "label": "复合"}], "register": "中性", "sense_fingerprint": "像石头的材料，做太阳能板把阳光变成电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钙钛矿", "is_correct": true, "explanation": "正确。钙钛矿是一种像石头的材料，可以做太阳能板。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花松软，不像石头，也做不了太阳能板。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵轻飘，与“像石头”的说法正相反。"}, {"text": "羽毛", "is_correct": false, "explanation": "搭配：“做太阳能板”要用坚硬、能发电的材料，羽毛不能这样用。"}], "explanations": {"钙钛矿": "正确。钙钛矿是一种像石头的材料，可以做太阳能板。", "棉花": "语义：棉花松软，不像石头，也做不了太阳能板。", "云朵": "语义：云朵轻飘，与“像石头”的说法正相反。", "羽毛": "搭配：“做太阳能板”要用坚硬、能发电的材料，羽毛不能这样用。"}, "sentence_index": 0, "correct_answer": "钙钛矿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只钙钛矿。", "explanation": "这里应该用〈块〉。钙钛矿是材料，量词要用“块”，“只”多用于动物或某些器物。"}, {"text": "屋顶上装了很多钙钛矿。", "explanation": "这里应该用〈太阳能板〉。钙钛矿是材料，装在屋顶上的应是做好的板子。"}, {"text": "我用这块钙钛矿包了饺子。", "explanation": "这里应该用〈饺子皮〉。钙钛矿是材料，不能用来包饺子，包饺子用的应是饺子皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钙钛矿", "is_correct": true, "explanation": "正确。钙钛矿能让电变得更便宜，符合句子的语境。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文字作品，不能让电变得更便宜。"}, {"text": "胡萝卜", "is_correct": false, "explanation": "语义：胡萝卜是蔬菜，与“让电变得更便宜”毫无关系。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“让……变得更便宜”要求能影响成本的事物，友谊不能这样用。"}], "explanations": {"钙钛矿": "正确。钙钛矿能让电变得更便宜，符合句子的语境。", "诗歌": "语义：诗歌是文字作品，不能让电变得更便宜。", "胡萝卜": "语义：胡萝卜是蔬菜，与“让电变得更便宜”毫无关系。", "友谊": "搭配：“让……变得更便宜”要求能影响成本的事物，友谊不能这样用。"}, "sentence_index": 6, "correct_answer": "钙钛矿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天要补充钙钛矿。", "explanation": "这里应该用〈钙〉。钙是人体需要的营养素，钙钛矿是材料，不能用来补充。"}, {"text": "农民给庄稼施钙钛矿。", "explanation": "这里应该用〈肥料〉。施的是肥料，钙钛矿是材料，不能用来施肥。"}, {"text": "把钙钛矿倒进锅里。", "explanation": "这里应该用〈面粉〉。钙钛矿不能吃，也不能用来做饭，倒进锅里的应是食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只钙钛矿很便宜。", "corrected_sentence": "这块钙钛矿很便宜。", "error_description": "量词用错：钙钛矿是材料，应说“这块钙钛矿”；“只”多用于动物或某些器物，不能用来数材料。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们钙钛矿做成了板子。", "corrected_sentence": "我们把钙钛矿做成了板子。", "error_description": "漏掉“把”：“做成”的对象“钙钛矿”需要用“把”提到动词前，去掉“把”后句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
