INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电池能让玩具动起来。", "primary_collocate": null, "pronunciation": "diàn chí", "ipa": "tjɛn˥˩ ʈʂʰʅ˧˥", "syllable_count": 2, "sentences": [{"text": "弟弟的玩具车里有电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把电池装进去，小车就跑了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩具不动了，可能是电池坏了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了新电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗玩具要用两节电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开玩具，你会看到电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池放对了，机器人就会走路。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有电池，玩具不能动。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从桌子上拿起一节电池。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池用完了，玩具车停下来了。", "target_word": "电池", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "节", "label": "量词"}, {"form": "電池", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让玩具动起来的电池", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a88376a6-aa5b-449c-a391-acd929036bee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电池", "is_correct": true, "explanation": "电池，diàn chí，让玩具动起来的装置。"}, {"text": "电磁", "is_correct": false, "explanation": "c 与 ch 声母不同，diàn cí 意思是电磁。"}, {"text": "电石", "is_correct": false, "explanation": "sh 与 ch 声母不同，diàn shí 意思是电石，一种化工原料。"}, {"text": "滇池", "is_correct": false, "explanation": "声调混淆：滇池 diān chí，首音节 diān 与 diàn 仅声调不同；滇池是云南湖名。"}], "explanations": {"电池": "电池，diàn chí，让玩具动起来的装置。", "电磁": "c 与 ch 声母不同，diàn cí 意思是电磁。", "电石": "sh 与 ch 声母不同，diàn shí 意思是电石，一种化工原料。", "滇池": "声调混淆：滇池 diān chí，首音节 diān 与 diàn 仅声调不同；滇池是云南湖名。"}, "sentence_index": null, "correct_answer": "电池"}, "level_3": {"options": [{"text": "电池", "is_correct": true, "explanation": "玩具车里装的是电池，才能让小车动起来。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不会装在玩具车里让它动起来。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，与玩具车的动力无关。"}, {"text": "雨伞", "is_correct": false, "explanation": "体貌：玩具车体积太小，装不下雨伞。"}], "explanations": {"电池": "玩具车里装的是电池，才能让小车动起来。", "面条": "语义：面条是食物，不会装在玩具车里让它动起来。", "白菜": "语义：白菜是蔬菜，与玩具车的动力无关。", "雨伞": "体貌：玩具车体积太小，装不下雨伞。"}, "sentence_index": 0, "correct_answer": "电池"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天早上用电池煮面条。", "explanation": "这里应该用〈水〉。电池不能用来煮东西；“煮面条”要用水和锅。"}, {"text": "我每天晚上用电池刷牙。", "explanation": "这里应该用〈牙刷〉。电池不能刷牙，“刷牙”要用牙刷。"}, {"text": "我每天睡觉前用电池盖被子。", "explanation": "这里不能用电池。电池不能用来盖身体；“盖被子”的覆盖物要是被子、毯子之类的织物，不能是电池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电池", "is_correct": true, "explanation": "电池放对了，机器人才会走路，句中的“电池”指让机器运转的装置。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服不能让机器人走路，与“放对了”的语境不符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不能为机器人提供动力。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“放对了”指装置的安装，铅笔不能让机器人走路。"}], "explanations": {"电池": "电池放对了，机器人才会走路，句中的“电池”指让机器运转的装置。", "衣服": "语义：衣服不能让机器人走路，与“放对了”的语境不符。", "饼干": "语义：饼干是食物，不能为机器人提供动力。", "铅笔": "搭配：“放对了”指装置的安装，铅笔不能让机器人走路。"}, "sentence_index": 6, "correct_answer": "电池"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河边钓了一条电池。", "explanation": "这里应该用〈鱼〉。“钓”的对象是鱼，电池不能钓。"}, {"text": "我吃了一个电池。", "explanation": "这里应该用〈苹果〉。“吃”的对象是食物，电池不能吃。"}, {"text": "爸爸在院子里种了一棵电池。", "explanation": "这里应该用〈树〉。“种”的对象是植物，电池不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把电池装了好，玩具车就能跑了。", "corrected_sentence": "他把电池装好了，玩具车就能跑了。", "error_description": "补语位置错误。结果补语“好”要紧跟动词，应说“装好了”，不能说“装了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我买了两本电池。", "corrected_sentence": "妈妈给我买了两节电池。", "error_description": "量词错误。电池的量词应用“节”；“本”用于书册等，不能用来数电池。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1d683fb-779a-498c-9f3a-53c4588d421e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26880, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚硬", "is_correct": true, "explanation": "反义：坚硬指质地硬，与柔软、柔性相对。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：明亮描述光线或颜色，与柔性没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "无关：潮湿描述含水的状态，与柔性没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：清晰描述明显程度，与柔性没有反义关系。"}], "correct_answer": "坚硬", "explanations": {"坚硬": "反义：坚硬指质地硬，与柔软、柔性相对。", "明亮": "无关：明亮描述光线或颜色，与柔性没有反义关系。", "潮湿": "无关：潮湿描述含水的状态，与柔性没有反义关系。", "清晰": "无关：清晰描述明显程度，与柔性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
