INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组件是组成一个东西的各个小部分。", "primary_collocate": null, "pronunciation": "zǔ jiàn", "ipa": "tsu˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "桌子的组件都放在盒子里。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具有十个组件。", "target_word": "组件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请先看看组件够不够。", "target_word": "组件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸按图把组件装好了。", "target_word": "组件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个组件上都有一个号码。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "少了一个组件，书架装不好。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑的组件都是新的。", "target_word": "组件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把组件放进了盒子里。", "target_word": "组件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢拼这些组件。", "target_word": "组件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些组件可以自己换。", "target_word": "组件", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "组成物品的小部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb540fec-9cec-4bcb-8643-5a997deb09c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26882, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件（zǔ jiàn）指组成物品的小部分，是本词的读音和意思。"}, {"text": "主见", "is_correct": false, "explanation": "主见（zhǔ jiàn）：声母 zh 与 z 不同，意思是自己的见解。"}, {"text": "主件", "is_correct": false, "explanation": "主件（zhǔ jiàn）：声母 zh 与 z 不同，意思是主要的零件。"}, {"text": "组间", "is_correct": false, "explanation": "组间（zǔ jiān）：jiàn 与 jiān 声调不同（第四声与第一声），意思是组与组之间。"}, {"text": "足见", "is_correct": false, "explanation": "足见（zú jiàn）：zǔ 与 zú 声调不同（第三声与第二声），意思是足以看出。"}], "explanations": {"组件": "组件（zǔ jiàn）指组成物品的小部分，是本词的读音和意思。", "主见": "主见（zhǔ jiàn）：声母 zh 与 z 不同，意思是自己的见解。", "主件": "主件（zhǔ jiàn）：声母 zh 与 z 不同，意思是主要的零件。", "组间": "组间（zǔ jiān）：jiàn 与 jiān 声调不同（第四声与第一声），意思是组与组之间。", "足见": "足见（zú jiàn）：zǔ 与 zú 声调不同（第三声与第二声），意思是足以看出。"}, "sentence_index": null, "correct_answer": "组件"}, "level_3": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件：组成物品的小部分。「桌子的组件」指桌子的各个部分，与语境相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是桌子的组成部分，不能说「桌子的歌曲都放在盒子里」。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是可以喝的东西，不是桌子的一部分，不会放进盒子里。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「桌子的天气」不成搭配，天气不是可以装进盒子的东西。"}], "explanations": {"组件": "组件：组成物品的小部分。「桌子的组件」指桌子的各个部分，与语境相符。", "歌曲": "语义：歌曲不是桌子的组成部分，不能说「桌子的歌曲都放在盒子里」。", "饮料": "语义：饮料是可以喝的东西，不是桌子的一部分，不会放进盒子里。", "天气": "搭配：「桌子的天气」不成搭配，天气不是可以装进盒子的东西。"}, "sentence_index": 0, "correct_answer": "组件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个组件有五十名成员，每周活动一次。", "explanation": "这里应该用〈社团〉。社团是由学生或爱好者组成的团体，有成员；组件指物品的小部分，不能指团体。"}, {"text": "孩子把一个组件塞进了嘴里。", "explanation": "这里应该用〈糖果〉。组件指组成物品的小部分，不能吃；放进嘴里的甜食要说糖果。"}, {"text": "这所学校有八个组件，各自管理一个年级。", "explanation": "这里应该用〈年级〉。年级是学校的教学单位；组件指物品的小部分，不能指学校的年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组件", "is_correct": true, "explanation": "组件：组成电脑的小部分。「这台电脑的组件」指电脑的各个部分，与语境相符。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，不是电脑的组成部分，「这台电脑的早餐」与语境不符。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，不属于电脑的组成部分。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：「电脑的蔬菜」不成搭配，蔬菜与电脑没有组成关系。"}], "explanations": {"组件": "组件：组成电脑的小部分。「这台电脑的组件」指电脑的各个部分，与语境相符。", "早餐": "语义：早餐是食物，不是电脑的组成部分，「这台电脑的早餐」与语境不符。", "诗歌": "语义：诗歌是文学作品，不属于电脑的组成部分。", "蔬菜": "搭配：「电脑的蔬菜」不成搭配，蔬菜与电脑没有组成关系。"}, "sentence_index": 6, "correct_answer": "组件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上都用一个组件刷牙。", "explanation": "这里应该用〈牙刷〉。组件指组成物品的小部分，刷牙要用牙刷。"}, {"text": "妈妈用组件切了一个西瓜。", "explanation": "这里应该用〈刀〉。切西瓜要用刀；组件是物品的小部分，不能用来切东西。"}, {"text": "他每天早上都把一个组件戴在手腕上。", "explanation": "这里应该用〈手表〉。手表能戴在手腕上；组件是物品的小部分，不能用来戴在手上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "盒子里有三只组件。", "corrected_sentence": "盒子里有三个组件。", "error_description": "量词错误：「组件」应用量词「个」，不用「只」。「只」一般用于动物，说「三只组件」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书架上有一条组件掉了。", "corrected_sentence": "书架上有一个组件掉了。", "error_description": "量词错误：「组件」应用量词「个」，不能用「条」来数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
