INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26884, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "特质是指一个人或事物自己特别有的地方，和别人不一样。", "primary_collocate": null, "pronunciation": "tè zhì", "ipa": "tʰɤ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "诚实是她最重要的特质。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料有一个特质，就是很轻。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耐心是好老师必须有的特质。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个城市都有自己的特质。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身上有一种安静的特质。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司很看重员工的特质。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导者的特质有很多种。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的特质是爱问问题。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术家常常有与众不同的特质。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老城保留了自己独特的特质。", "target_word": "特质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种特质", "label": "量词"}, {"form": "人格特质", "label": "复合"}, {"form": "特質", "label": "繁体"}], "register": "书面", "sense_fingerprint": "特质：人或事物独有的、与别人不同的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特质", "is_correct": true, "explanation": "正确。特质指人独有的、区别于他人的特点，“诚实是她最重要的特质”成立。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“最重要的”修饰的应是品质或特点，颜色不能这样说。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位不是品质，不能说“诚实是最重要的座位”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“最重要的”不能修饰价格，“诚实是她最重要的价格”不通。"}], "explanations": {"特质": "正确。特质指人独有的、区别于他人的特点，“诚实是她最重要的特质”成立。", "颜色": "语义：“最重要的”修饰的应是品质或特点，颜色不能这样说。", "座位": "语义：座位不是品质，不能说“诚实是最重要的座位”。", "价格": "搭配：“最重要的”不能修饰价格，“诚实是她最重要的价格”不通。"}, "sentence_index": 0, "correct_answer": "特质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子身上有一只特质，很突出。", "explanation": "这里应该用〈种〉。特质是抽象的，量词要用“种”或“个”，不用“只”。"}, {"text": "他把特质放进了冰箱。", "explanation": "这里应该用〈牛奶〉。特质是抽象的，不能放进冰箱，放进冰箱的应是牛奶这类食物。"}, {"text": "他的特质是一米八。", "explanation": "这里应该用〈身高〉。身高是数值，特质是人或事物的特点，不能用数字来说明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特质", "is_correct": true, "explanation": "正确。“领导者的特质”指领导者独有的特点，“有很多种”说的正是特质。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不能说“有很多种”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是数值，没有“有很多种”的说法。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重可以说有多少，不能用“有很多种”来描述。"}], "explanations": {"特质": "正确。“领导者的特质”指领导者独有的特点，“有很多种”说的正是特质。", "年龄": "语义：年龄是岁数，不能说“有很多种”。", "身高": "语义：身高是数值，没有“有很多种”的说法。", "体重": "搭配：体重可以说有多少，不能用“有很多种”来描述。"}, "sentence_index": 6, "correct_answer": "特质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天做了一个特质，很重要。", "explanation": "这里应该用〈决定〉。“做”搭配“决定”，特质是固有的特点，不能被“做”出来。"}, {"text": "我家的特质在城东。", "explanation": "这里应该用〈地址〉。地址说的是位置，特质不能指位置。"}, {"text": "这台电脑的特质很高。", "explanation": "这里应该用〈质量〉。“很高”用来评价质量，特质指事物独有的特点，不能用来评价高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师有一只很特别的特质。", "corrected_sentence": "这位老师有一种很特别的特质。", "error_description": "量词用错：特质是抽象名词，应说“一种特质”；“只”不能用来数特质。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家有自己特质。", "corrected_sentence": "这位画家有自己的特质。", "error_description": "漏掉“的”：“自己”修饰“特质”时需要“的”连接，去掉后不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26886, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单面", "is_correct": true, "explanation": "单面：只有一个面可用，与“双面”形成反义。"}, {"text": "纸张", "is_correct": false, "explanation": "纸张是材料名称，与“双面”没有反义关系。"}, {"text": "地毯", "is_correct": false, "explanation": "地毯是物品名称，与“双面”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是建筑部件，与“双面”没有反义关系。"}], "correct_answer": "单面", "explanations": {"单面": "单面：只有一个面可用，与“双面”形成反义。", "纸张": "纸张是材料名称，与“双面”没有反义关系。", "地毯": "地毯是物品名称，与“双面”没有反义关系。", "窗户": "窗户是建筑部件，与“双面”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26886, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单面", "is_correct": true, "explanation": "单面：只有一个面可用，与“双面”形成反义。"}, {"text": "书包", "is_correct": false, "explanation": "书包是装东西的用具，与“双面”没有反义关系。"}, {"text": "信封", "is_correct": false, "explanation": "信封是装信件的纸袋，与“双面”没有反义关系。"}, {"text": "盒子", "is_correct": false, "explanation": "盒子是容器，与“双面”没有反义关系。"}], "correct_answer": "单面", "explanations": {"单面": "单面：只有一个面可用，与“双面”形成反义。", "书包": "书包是装东西的用具，与“双面”没有反义关系。", "信封": "信封是装信件的纸袋，与“双面”没有反义关系。", "盒子": "盒子是容器，与“双面”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "双面就是有两个面。", "primary_collocate": null, "pronunciation": "shuāng miàn", "ipa": "ʂwɑŋ˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这本笔记本可以双面写。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张海报是双面的。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一件双面穿的衣服。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地毯双面都很好看。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把作业双面复印。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸双面都能写字。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一条双面围巾。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜单是双面的。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子双面都画着小花。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求双面打印作业。", "target_word": "双面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "双面的", "label": "定语形式"}, {"form": "双面性", "label": "复合"}, {"form": "雙面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "双面：物体的两边都有可用的面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双面", "is_correct": true, "explanation": "双面：两面都可以写字，与“可以……写”相合。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块遇热即化，不能用来写字，“可以……写”不通。"}, {"text": "水彩", "is_correct": false, "explanation": "搭配：水彩多用于作画，不用来在笔记本上写字。"}, {"text": "钢琴", "is_correct": false, "explanation": "配价：“写”需要书写工具作为方式，钢琴不能充当书写工具。"}], "explanations": {"双面": "双面：两面都可以写字，与“可以……写”相合。", "冰块": "语义：冰块遇热即化，不能用来写字，“可以……写”不通。", "水彩": "搭配：水彩多用于作画，不用来在笔记本上写字。", "钢琴": "配价：“写”需要书写工具作为方式，钢琴不能充当书写工具。"}, "sentence_index": 0, "correct_answer": "双面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他双面托着盘子，慢慢走过来。", "explanation": "这里应该用〈双手〉。双面指物体的两个面，不能用来指人的双手。"}, {"text": "他双面站在门口，等着朋友。", "explanation": "这里应该用〈双脚〉。双面指物体的两个面，不能用来指人站立的双脚。"}, {"text": "他们双面都喝醉了。", "explanation": "这里应该用〈两人〉。双面只指物体的两面，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双面", "is_correct": true, "explanation": "双面：围巾两面都能用，修饰“围巾”，句意通顺。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃易碎，不能织成围巾，“玻璃围巾”句意不通。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头硬且不能做围巾，“木头围巾”与常识相悖。"}, {"text": "铁", "is_correct": false, "explanation": "搭配：“铁”不作围巾的材料，“铁围巾”搭配不当。"}], "explanations": {"双面": "双面：围巾两面都能用，修饰“围巾”，句意通顺。", "玻璃": "语义：玻璃易碎，不能织成围巾，“玻璃围巾”句意不通。", "木头": "语义：木头硬且不能做围巾，“木头围巾”与常识相悖。", "铁": "搭配：“铁”不作围巾的材料，“铁围巾”搭配不当。"}, "sentence_index": 6, "correct_answer": "双面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月他拿到了双面工资。", "explanation": "这里应该用〈双倍〉。双面指物体的两个面或两方面的特性，不能用来说工资加倍。"}, {"text": "这家商店每周双面休息。", "explanation": "这里应该用〈双休〉。双面只指两面，不能用来说每周休息两天。"}, {"text": "那只鸭子下了一个双面蛋。", "explanation": "这里应该用〈双黄〉。双面只描述物体的两面，不能用来说蛋黄成双。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请双面复印了这份合同。", "corrected_sentence": "请双面复印这份合同。", "error_description": "错误：祈使句“请……”后不能带“了”。“复印了”应为“复印”，正确句为“请双面复印这份合同。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地毯双面了都能用。", "corrected_sentence": "这块地毯双面都能用。", "error_description": "错误：“双面”作状语修饰“能用”时其后不能加“了”。“双面了都能用”不通，应为“双面都能用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
