INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26888, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "颠覆是指船、车等整个翻倒过来。", "primary_collocate": null, "pronunciation": "diān fù", "ipa": "tjɛn˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "大风把小船颠覆了。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条船在海上颠覆了。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海浪颠覆了那条渔船。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很急，木筏颠覆了。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴雨中，货车在路边颠覆了。", "target_word": "颠覆", "complexity_tier": "T3", "furigana": "bào yǔ zhōng, huò chē zài lù biān diān fù le.", "sentence_source": "generated"}, {"text": "他的小船在河中间颠覆了。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大浪来了，船马上就颠覆了。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浪太大，船可能会颠覆。", "target_word": "颠覆", "complexity_tier": "T3", "furigana": "làng tài dà, chuán kěnéng huì diān fù.", "sentence_source": "generated"}, {"text": "台风让很多渔船颠覆了。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那艘游船昨天在湖上颠覆了。", "target_word": "颠覆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颠覆了", "label": "体标"}, {"form": "颠覆过", "label": "体标"}, {"form": "顛覆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "颠覆：船、车等整个翻倒过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "颠覆", "is_correct": true, "explanation": "正确答案：颠覆 diān fù，指船、车等整个翻倒。"}, {"text": "天赋", "is_correct": false, "explanation": "tiān（第一声）与 diān 声母不同（t 与 d），意思是天生的才能。"}, {"text": "担负", "is_correct": false, "explanation": "dān（第一声）与 diān 少了介音 i，意思是承担。"}, {"text": "垫付", "is_correct": false, "explanation": "diàn（第四声）与 diān（第一声）声调不同，意思是先替别人付钱。"}], "explanations": {"颠覆": "正确答案：颠覆 diān fù，指船、车等整个翻倒。", "天赋": "tiān（第一声）与 diān 声母不同（t 与 d），意思是天生的才能。", "担负": "dān（第一声）与 diān 少了介音 i，意思是承担。", "垫付": "diàn（第四声）与 diān（第一声）声调不同，意思是先替别人付钱。"}, "sentence_index": null, "correct_answer": "颠覆"}, "level_3": {"options": [{"text": "颠覆", "is_correct": true, "explanation": "颠覆：指船、车等整个翻倒，与“大风”“小船”的语境相合。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指人为修理，大风不能修船，句意不通。"}, {"text": "卖", "is_correct": false, "explanation": "配价：“卖”需要卖方和买方两个参与者，句中没有买方，大风也不能卖船。"}, {"text": "刷", "is_correct": false, "explanation": "搭配：“刷”多指涂漆、刷洗，不能用来描述大风造成的结果。"}], "explanations": {"颠覆": "颠覆：指船、车等整个翻倒，与“大风”“小船”的语境相合。", "修": "语义：“修”指人为修理，大风不能修船，句意不通。", "卖": "配价：“卖”需要卖方和买方两个参与者，句中没有买方，大风也不能卖船。", "刷": "搭配：“刷”多指涂漆、刷洗，不能用来描述大风造成的结果。"}, "sentence_index": 0, "correct_answer": "颠覆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大风把那棵大树颠覆了。", "explanation": "这里应该用〈吹倒〉。颠覆只用于船、车等整个翻倒，不能用来说树木倒下。"}, {"text": "推土机把那堵墙颠覆了。", "explanation": "这里应该用〈推倒〉。颠覆指船、车等整个翻倒，墙这类建筑物不能用颠覆。"}, {"text": "他一生气就颠覆了桌子。", "explanation": "这里应该用〈掀翻〉。颠覆用于船、车等交通工具整个翻倒，不能用于桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颠覆", "is_correct": true, "explanation": "颠覆：指船整个翻倒，与“大浪来了”“马上就”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：船不能唱歌，“唱”与句中的主语“船”完全不搭。"}, {"text": "绕", "is_correct": false, "explanation": "配价：“绕”需要绕行的对象，如“绕过礁石”，单独说“船马上就绕了”缺少必要成分。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”的受事多是人或可击打的物，船不能被“打”成句中所说的状态，搭配不当。"}], "explanations": {"颠覆": "颠覆：指船整个翻倒，与“大浪来了”“马上就”的语境相合。", "唱": "语义：船不能唱歌，“唱”与句中的主语“船”完全不搭。", "绕": "配价：“绕”需要绕行的对象，如“绕过礁石”，单独说“船马上就绕了”缺少必要成分。", "打": "搭配：“打”的受事多是人或可击打的物，船不能被“打”成句中所说的状态，搭配不当。"}, "sentence_index": 6, "correct_answer": "颠覆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一不小心把一盆水颠覆了。", "explanation": "这里应该用〈泼〉。颠覆指船、车等整个翻倒，洒出的液体要用泼。"}, {"text": "他在冰上一滑，颠覆了。", "explanation": "这里应该用〈摔倒〉。颠覆指船、车整个翻倒，不能用来指人摔倒。"}, {"text": "他累得一下子颠覆了。", "explanation": "这里应该用〈躺倒〉。颠覆用于船、车，不能用来说人躺下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条船装得太满，可能会颠覆过。", "corrected_sentence": "这条船装得太满，可能会颠覆。", "error_description": "体标误用：「过」表示已然经历，不能用于尚未发生的“可能会”事件，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴风雨把渔船颠覆。", "corrected_sentence": "暴风雨把渔船颠覆了。", "error_description": "错误：“把”字句中“颠覆”后缺少“了”，句子不完整。应为“把渔船颠覆了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
