INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "发电量就是机器或电厂发出电的多少。", "primary_collocate": null, "pronunciation": "fā diàn liàng", "ipa": "fa˥ tjɛn˥˩ ljɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这家电厂一天的发电量很大。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，太阳能板的发电量很少。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风越大，风车的发电量越多。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家屋顶的发电量够用。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天看一次机器的发电量。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电厂的发电量不够，城市就会停电。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太阳强，发电量会变多。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机器的发电量比旧机器高。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写了这个月的发电量。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道这座小水电站的发电量。", "target_word": "发电量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总发电量", "label": "复合"}, {"form": "年发电量", "label": "复合"}, {"form": "發電量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机器或电厂发出来的电有多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb540fec-9cec-4bcb-8643-5a997deb09c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发电量", "is_correct": true, "explanation": "正确。电厂一天发出的电量很大，与“发电量”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色没有大小之分，也不能按“一天”计算。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命指存在的时长，不能按“一天”来说“很大”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”用于人或动物，不能用于电厂。"}], "explanations": {"发电量": "正确。电厂一天发出的电量很大，与“发电量”相符。", "颜色": "体貌：颜色没有大小之分，也不能按“一天”计算。", "寿命": "语义：寿命指存在的时长，不能按“一天”来说“很大”。", "身高": "搭配：“身高”用于人或动物，不能用于电厂。"}, "sentence_index": 0, "correct_answer": "发电量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗的发电量是二十公斤。", "explanation": "这里应该用〈体重〉。公斤是重量单位，狗的重量要说体重；发电量指发出的电能。"}, {"text": "我家到学校的发电量是两公里。", "explanation": "这里应该用〈距离〉。两地之间的远近要说距离，发电量是电能总量。"}, {"text": "这台机器的发电量是一万元。", "explanation": "这里应该用〈价格〉。元是货币单位，机器的钱数要说价格，发电量不用钱计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发电量", "is_correct": true, "explanation": "正确。太阳强时发出的电能会增多，与“变多”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“变多”来计量，与“太阳强”的因果关系也不合。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：温度说升高或降低，不说“变多”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会因天气而变多，句子意思混乱。"}], "explanations": {"发电量": "正确。太阳强时发出的电能会增多，与“变多”相符。", "天气": "语义：天气不能用“变多”来计量，与“太阳强”的因果关系也不合。", "温度": "搭配：温度说升高或降低，不说“变多”。", "年龄": "语义：年龄不会因天气而变多，句子意思混乱。"}, "sentence_index": 6, "correct_answer": "发电量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的发电量每月五万件。", "explanation": "这里应该用〈产量〉。件是产品数量单位，工厂的产出要说产量；发电量是电能总量。"}, {"text": "这部电影的发电量是一个半小时。", "explanation": "这里应该用〈时长〉。小时是时间单位，电影的播放时间要说时长，发电量指电能总量。"}, {"text": "屋里的发电量是二十五摄氏度。", "explanation": "这里应该用〈温度〉。摄氏度是温度单位，屋里的冷热程度要说温度，发电量不能用温度描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台老风车的发电量跟新的少。", "corrected_sentence": "这台老风车的发电量比新的少。", "error_description": "比较词误用：比较多少要用“比”，“跟”不能引出比较对象。正确形式为“发电量比新的少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座电站的发电量下降地厉害。", "corrected_sentence": "那座电站的发电量下降得厉害。", "error_description": "结构助词误用：“下降”后引出补语须用“得”，不能用“地”。正确形式为“下降得厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17e1226-46c7-4778-a6aa-e35530f95a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
