INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "数量、大小、或程度像翻倍一样快速增加。", "primary_collocate": null, "pronunciation": "chéng jǐ hé", "ipa": "ʈʂʰɤŋ³⁵ tɕi²¹⁴ xɤ³⁵", "syllable_count": 3, "sentences": [{"text": "这座城市的人口呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机用户的数量呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒传播得很快，病例呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的新视频呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，他的工作压力呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细菌在热天里呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客的人数在假期呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的客人呈几何增长，老板很高兴。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的作业量呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的汽车数量呈几何增长。", "target_word": "呈几何", "complexity_tier": "T3", "furigana": "lù shàng de qìchē shùliàng chéng jǐhé zēngzhǎng", "sentence_source": "generated"}], "morphological_forms": [{"form": "呈几何级数", "label": "复合"}, {"form": "呈几何增长", "label": "复合"}], "register": "书面", "sense_fingerprint": "数量像翻倍一样快速增长，多接级数增长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cff4beb-2454-4408-ae79-6e87aa30b10c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呈几何", "is_correct": true, "explanation": "“呈几何”修饰“增长”，表示人口像翻倍一样快速增加，符合句意。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”指不再前进，与“增长”方向相反，句意矛盾。"}, {"text": "萎缩", "is_correct": false, "explanation": "语义：“萎缩”指缩小，与“增长”相反，“人口萎缩增长”自相矛盾。"}, {"text": "衰减", "is_correct": false, "explanation": "语义：衰减指减少，与“增长”方向相反，“人口衰减增长”自相矛盾。"}], "explanations": {"呈几何": "“呈几何”修饰“增长”，表示人口像翻倍一样快速增加，符合句意。", "停滞": "语义：“停滞”指不再前进，与“增长”方向相反，句意矛盾。", "萎缩": "语义：“萎缩”指缩小，与“增长”相反，“人口萎缩增长”自相矛盾。", "衰减": "语义：衰减指减少，与“增长”方向相反，“人口衰减增长”自相矛盾。"}, "sentence_index": 0, "correct_answer": "呈几何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的存款呈几何增长，每个月只多一千元。", "explanation": "这里应该用〈呈线性〉。几何增长指数量翻倍式地加快，每月固定增加一千元要用〈呈线性〉。"}, {"text": "这个孩子的身高每年只长一厘米，却呈几何增长。", "explanation": "这里应该用〈稳步增长〉。“呈几何”表示翻倍式的快速增长，与“每年只长一厘米”矛盾。"}, {"text": "他的工资呈几何增长，每年只涨一点点。", "explanation": "这里应该用〈小幅上涨〉。“呈几何”表示翻倍式的快速增长，与“每年只涨一点点”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呈几何", "is_correct": true, "explanation": "“呈几何”修饰“增长”，表示人数像翻倍一样快速增加，与“假期”里客流激增的语境相符。"}, {"text": "锐减", "is_correct": false, "explanation": "语义：“锐减”指急剧减少，与“增长”相反，句意矛盾。"}, {"text": "回落", "is_correct": false, "explanation": "语义：“回落”指下降，与“增长”方向冲突，句子无法成立。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”是动作，不能与“增长”搭配来表示人数的变化。"}], "explanations": {"呈几何": "“呈几何”修饰“增长”，表示人数像翻倍一样快速增加，与“假期”里客流激增的语境相符。", "锐减": "语义：“锐减”指急剧减少，与“增长”相反，句意矛盾。", "回落": "语义：“回落”指下降，与“增长”方向冲突，句子无法成立。", "游览": "搭配：“游览”是动作，不能与“增长”搭配来表示人数的变化。"}, "sentence_index": 6, "correct_answer": "呈几何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的学生人数始终没变，却呈几何增长。", "explanation": "这里应该用〈保持稳定〉。“呈几何”指数量翻倍式地快速增加，人数始终不变时不能用，应说“保持稳定”。"}, {"text": "我的汉语水平呈几何增长，每天只学五分钟。", "explanation": "这里应该用〈缓慢进步〉。“呈几何”表示数量翻倍式的快速增长，与“每天只学五分钟”的节奏矛盾。"}, {"text": "这条街的房价呈几何上升，今年和去年差不多。", "explanation": "这里应该用〈保持平稳〉。“呈几何”表示翻倍式的快速增长，房价与去年持平时不能用“呈几何”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近两年，手机的销量呈几何减少。", "corrected_sentence": "最近两年，手机的销量呈几何增长。", "error_description": "错误在于「呈几何」后接了「减少」：「呈几何」只表示数量像翻倍一样快速增长，应改为「呈几何增长」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月病例呈几何了增长。", "corrected_sentence": "这个月病例呈几何增长。", "error_description": "错误形式是「呈几何了增长」，正确形式是「呈几何增长」：「了」不能插在「呈几何」和「增长」之间，多余的「了」使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86635e38-5915-4314-90db-e832f39de107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
