INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "划船时用来拨水的棍子。", "primary_collocate": null, "pronunciation": "jiǎng", "ipa": "tɕjɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "划船的时候，我们每人用一支桨往前划。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船没有桨，就走不动。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用桨拨水，船慢慢向前走。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支桨又长又重，我拿不动。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桨放在船里，别让它掉到水里。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次划船，不会用桨。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在小船上，用两支桨划水。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷做了一支桨送给我。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用桨用力一划，水花溅了出来。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖上的船夫摇着桨，唱着歌。", "target_word": "桨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "对", "label": "量词"}, {"form": "船桨", "label": "复合"}, {"form": "槳", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划船时用来拨水的棍子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ae084-1987-4b16-afb3-69290c5fa6f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26912, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "桨", "is_correct": true, "explanation": "jiǎng，划船时用来拨水的棍子，为正确答案。"}, {"text": "江", "is_correct": false, "explanation": "声调不同：jiāng（第一声）与 jiǎng（第三声）不同，意思是江河。"}, {"text": "降", "is_correct": false, "explanation": "声调不同：jiàng（第四声）意思是下降，与 jiǎng 不同。"}, {"text": "浆", "is_correct": false, "explanation": "声调不同：jiāng（第一声）意思是液体，如豆浆。"}, {"text": "酱", "is_correct": false, "explanation": "声调不同：jiàng（第四声）意思是酱料，与 jiǎng 不同。"}], "explanations": {"桨": "jiǎng，划船时用来拨水的棍子，为正确答案。", "江": "声调不同：jiāng（第一声）与 jiǎng（第三声）不同，意思是江河。", "降": "声调不同：jiàng（第四声）意思是下降，与 jiǎng 不同。", "浆": "声调不同：jiāng（第一声）意思是液体，如豆浆。", "酱": "声调不同：jiàng（第四声）意思是酱料，与 jiǎng 不同。"}, "sentence_index": null, "correct_answer": "桨"}, "level_3": {"options": [{"text": "桨", "is_correct": true, "explanation": "正确：“用……往前划”的工具是桨。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔用于写字，不能用来往前划。"}, {"text": "枪", "is_correct": false, "explanation": "语义：枪不能用来往前划，与划船无关。"}, {"text": "烟", "is_correct": false, "explanation": "搭配：“用一支烟往前划”不成立，烟不能用来划船。"}], "explanations": {"桨": "正确：“用……往前划”的工具是桨。", "笔": "语义：笔用于写字，不能用来往前划。", "枪": "语义：枪不能用来往前划，与划船无关。", "烟": "搭配：“用一支烟往前划”不成立，烟不能用来划船。"}, "sentence_index": 0, "correct_answer": "桨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用桨挖土，很快就挖出了一个坑。", "explanation": "这里应该用〈铲子〉。挖土要用铲子，桨是划船用的工具。"}, {"text": "他把桨甩进湖里，等着钓一条鱼。", "explanation": "这里应该用〈鱼竿〉。钓鱼要用鱼竿，桨是划船时用来拨水的棍子。"}, {"text": "我们在船上放了一座桨。", "explanation": "这里应该用〈支〉。桨是细长的工具，按“支”计量；“座”用于山、桥等大型固定物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26912, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "桨", "is_correct": true, "explanation": "jiǎng，划船时用来拨水的棍子，为正确答案。"}, {"text": "姜", "is_correct": false, "explanation": "声调不同：jiāng（第一声）意思是生姜，与 jiǎng 不同。"}, {"text": "将", "is_correct": false, "explanation": "声调不同：jiāng（第一声）意思是将要或将军，与 jiǎng 不同。"}, {"text": "剪", "is_correct": false, "explanation": "韵母不同：jiǎn 的韵母是 ian，与 iang 不同，意思是剪刀。"}, {"text": "减", "is_correct": false, "explanation": "韵母不同：jiǎn 的韵母是 ian，与 iang 不同，意思是减少。"}], "explanations": {"桨": "jiǎng，划船时用来拨水的棍子，为正确答案。", "姜": "声调不同：jiāng（第一声）意思是生姜，与 jiǎng 不同。", "将": "声调不同：jiāng（第一声）意思是将要或将军，与 jiǎng 不同。", "剪": "韵母不同：jiǎn 的韵母是 ian，与 iang 不同，意思是剪刀。", "减": "韵母不同：jiǎn 的韵母是 ian，与 iang 不同，意思是减少。"}, "sentence_index": null, "correct_answer": "桨"}, "level_3": {"options": [{"text": "桨", "is_correct": true, "explanation": "正确：“用……划水”的工具是桨。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔用于写字，不能用来划水。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔用于写字，不能用来划水。"}, {"text": "雪茄", "is_correct": false, "explanation": "语义：雪茄不能用来划水，“用两支雪茄划水”不成立。"}], "explanations": {"桨": "正确：“用……划水”的工具是桨。", "粉笔": "语义：粉笔用于写字，不能用来划水。", "钢笔": "语义：钢笔用于写字，不能用来划水。", "雪茄": "语义：雪茄不能用来划水，“用两支雪茄划水”不成立。"}, "sentence_index": 6, "correct_answer": "桨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船夫站在船头，用桨给鱼开膛。", "explanation": "这里应该用〈刀〉。开膛要用刀，桨是划船用的工具。"}, {"text": "我在湖边买了一个桨。", "explanation": "这里应该用〈支〉。桨是细长的工具，按“支”计量，“个”不适用。"}, {"text": "我家的墙上挂着一粒桨。", "explanation": "这里应该用〈支〉。“粒”用于很小的颗粒状东西，桨应按“支”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每人划一个桨，很快就到了对岸。", "corrected_sentence": "我们每人划一支桨，很快就到了对岸。", "error_description": "量词错误：桨是细长的工具，应说“一支桨”，不说“一个桨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把桨弄了丢，只好走回去。", "corrected_sentence": "他把桨弄丢了，只好走回去。", "error_description": "语序错误：结果补语“丢”要紧跟动词“弄”，“了”放在句末，应说“弄丢了”，不说“弄了丢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
