INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能指挥或管理其他东西的部分。", "primary_collocate": null, "pronunciation": "kòng zhì xì tǒng", "ipa": "kʰʊŋ˥˩ ʈʂɨ˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "大脑是身体的控制系统。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小盒子是机器人的控制系统。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "控制系统管着整台机器的动作。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑的控制系统坏了，机器人就不动了。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经就像身体里的控制系统。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "控制系统发出命令，手臂就动起来。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的控制系统会告诉发动机该怎么做。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人没有了控制系统，就不能自己走路。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个遥控器就是玩具车的控制系统。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的控制系统管理各种应用。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套控制系统", "label": "量词"}, {"form": "控制系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "整体中负责指挥、管理其他部分的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '385e789d-21ea-49b5-b03e-4cf712cdbae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "控制系统", "is_correct": true, "explanation": "大脑指挥和管理身体的各个部分，与“身体的控制系统”的含义一致。"}, {"text": "血液", "is_correct": false, "explanation": "语义：血液负责运输物质，不指挥身体的其他部分。"}, {"text": "皮肤", "is_correct": false, "explanation": "语义：皮肤覆盖并保护身体，不指挥其他部分。"}, {"text": "肠胃", "is_correct": false, "explanation": "搭配：肠胃负责消化食物，与“指挥、管理其他部分”的功能不搭。"}], "explanations": {"控制系统": "大脑指挥和管理身体的各个部分，与“身体的控制系统”的含义一致。", "血液": "语义：血液负责运输物质，不指挥身体的其他部分。", "皮肤": "语义：皮肤覆盖并保护身体，不指挥其他部分。", "肠胃": "搭配：肠胃负责消化食物，与“指挥、管理其他部分”的功能不搭。"}, "sentence_index": 0, "correct_answer": "控制系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个控制系统很好吃。", "explanation": "这里应该用〈点心〉。控制系统是技术装置，不能吃，“好吃”只用于食物。"}, {"text": "她的控制系统很会唱歌。", "explanation": "这里应该用〈歌手〉。控制系统不会唱歌，会唱歌的是人。"}, {"text": "这个控制系统每天早上都去上学。", "explanation": "这里应该用〈学生〉。控制系统是技术装置，不会去上学，去上学的是学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控制系统", "is_correct": true, "explanation": "控制系统发出指令，与“会告诉发动机该怎么做”一致。"}, {"text": "油箱", "is_correct": false, "explanation": "语义：油箱只储存燃油，不会发出指令。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎只接触路面，不会向发动机发出指令。"}, {"text": "车灯", "is_correct": false, "explanation": "搭配：“告诉”要求能发出指令的主体，车灯只能照明，不能告诉发动机。"}], "explanations": {"控制系统": "控制系统发出指令，与“会告诉发动机该怎么做”一致。", "油箱": "语义：油箱只储存燃油，不会发出指令。", "轮胎": "语义：轮胎只接触路面，不会向发动机发出指令。", "车灯": "搭配：“告诉”要求能发出指令的主体，车灯只能照明，不能告诉发动机。"}, "sentence_index": 6, "correct_answer": "控制系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用控制系统切菜。", "explanation": "这里应该用〈菜刀〉。控制系统负责指挥其他部分，切菜要用菜刀。"}, {"text": "学生用控制系统写字。", "explanation": "这里应该用〈铅笔〉。控制系统负责管理其他部分，写字要用铅笔。"}, {"text": "我每天用控制系统剪纸。", "explanation": "这里应该用〈剪刀〉。控制系统负责指挥其他部分，剪纸要用剪刀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机器人身上装了一辆控制系统。", "corrected_sentence": "机器人身上装了一套控制系统。", "error_description": "量词用错：“辆”用于车辆。控制系统是成套的装置，应说“一套控制系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汽车里装了一条控制系统。", "corrected_sentence": "汽车里装了一套控制系统。", "error_description": "量词用错：“条”用于细长的东西。控制系统是成套的装置，应说“一套控制系统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
