INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西坏了，不能用了。", "primary_collocate": null, "pronunciation": "gù zhàng", "ipa": "ku⁵¹ ʈʂɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "电脑突然出了故障，文件都打不开。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱出了故障，牛奶都坏了。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视有故障，一点声音也没有。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车常常出故障，我不想骑了。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打印机又出故障了，你能来看看吗？", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门铃有故障，按了半天也不响。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投影仪出故障了，今天不能放视频。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车在路上出了故障，爸爸打电话叫人来修。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表有故障，时间总是不对。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为空调故障，教室里热得让人睡不着。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "故障率", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西坏了、不能用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a6d8aef-a14f-4db1-9f94-df23b2e8ce72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26922, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "故障", "is_correct": true, "explanation": "正确答案：故障 gù zhàng，指东西坏了、不能用了。"}, {"text": "鼓掌", "is_correct": false, "explanation": "鼓掌 gǔ zhǎng 的两个音节声调都与 gù zhàng 不同（均为第三声），意思是拍手。"}, {"text": "鼓胀", "is_correct": false, "explanation": "鼓胀 gǔ zhàng 第一音节声调不同（第三声），意思是鼓起、膨胀。"}, {"text": "姑丈", "is_correct": false, "explanation": "姑丈 gū zhàng 第一音节声调不同（第一声），意思是姑父。"}, {"text": "腹胀", "is_correct": false, "explanation": "腹胀 fù zhàng 声母不同（f 与 g），意思是肚子胀。"}], "explanations": {"故障": "正确答案：故障 gù zhàng，指东西坏了、不能用了。", "鼓掌": "鼓掌 gǔ zhǎng 的两个音节声调都与 gù zhàng 不同（均为第三声），意思是拍手。", "鼓胀": "鼓胀 gǔ zhàng 第一音节声调不同（第三声），意思是鼓起、膨胀。", "姑丈": "姑丈 gū zhàng 第一音节声调不同（第一声），意思是姑父。", "腹胀": "腹胀 fù zhàng 声母不同（f 与 g），意思是肚子胀。"}, "sentence_index": null, "correct_answer": "故障"}, "level_3": {"options": [{"text": "故障", "is_correct": true, "explanation": "正确：“出了故障”说明电脑突然坏了，所以文件打不开。"}, {"text": "名字", "is_correct": false, "explanation": "语义：电脑不会“出名字”，“名字”与电脑坏了无关，句子说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“出”不能与“脾气”搭配，应说“发脾气”，而且电脑没有脾气。"}, {"text": "体力", "is_correct": false, "explanation": "语义：“体力”指人的力气，不能用来说电脑出了问题。"}], "explanations": {"故障": "正确：“出了故障”说明电脑突然坏了，所以文件打不开。", "名字": "语义：电脑不会“出名字”，“名字”与电脑坏了无关，句子说不通。", "脾气": "搭配：“出”不能与“脾气”搭配，应说“发脾气”，而且电脑没有脾气。", "体力": "语义：“体力”指人的力气，不能用来说电脑出了问题。"}, "sentence_index": 0, "correct_answer": "故障"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶前几天出了故障，住了三天院。", "explanation": "这里应该用〈生病〉。故障指东西不能正常工作，不能用来说人生病。"}, {"text": "这个孩子有坏故障，总爱撒谎。", "explanation": "这里应该用〈毛病〉。故障指东西坏了不能用，孩子的不良习惯要说坏毛病。"}, {"text": "我们在山里故障了，天黑前没能回家。", "explanation": "这里应该用〈迷路〉。故障只用于东西，人走错了路不能说故障。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "故障", "is_correct": true, "explanation": "正确：“出故障”指投影仪坏了、不能用，所以今天不能放视频。"}, {"text": "座位", "is_correct": false, "explanation": "语义：投影仪不会“出座位”，“座位”不能表示设备坏了。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“出”不能与“钥匙”搭配表示设备出问题，说不通。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：“眼泪”是人眼中流出的液体，与投影仪坏了无关。"}], "explanations": {"故障": "正确：“出故障”指投影仪坏了、不能用，所以今天不能放视频。", "座位": "语义：投影仪不会“出座位”，“座位”不能表示设备坏了。", "钥匙": "搭配：“出”不能与“钥匙”搭配表示设备出问题，说不通。", "眼泪": "语义：“眼泪”是人眼中流出的液体，与投影仪坏了无关。"}, "sentence_index": 6, "correct_answer": "故障"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开车闯红灯，出了严重的故障。", "explanation": "这里应该用〈事故〉。故障指东西坏了不能用，开车违章造成的意外伤害要说事故。"}, {"text": "他做题时犯了故障，结果全错了。", "explanation": "这里应该用〈错误〉。故障指东西坏了不能用，人做题时的过失要说犯错误。"}, {"text": "他在篮球场上出现了故障，被对手追上了。", "explanation": "这里应该用〈失误〉。故障指东西出问题，运动员场上的失误要说失误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗衣机突然出了一台故障，不能脱水了。", "corrected_sentence": "洗衣机突然出了一次故障，不能脱水了。", "error_description": "量词错误：“故障”是一次性的事件，应该说“一次故障”；“台”用于机器等具体物件，不能用来计数故障。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台冰箱昨晚突然犯了故障，牛奶都坏了。", "corrected_sentence": "这台冰箱昨晚突然发生了故障，牛奶都坏了。", "error_description": "搭配错误：“犯”用于“犯错误”，不能与“故障”搭配；应说“发生故障”或“出故障”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
