INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大陆架是海底靠近陆地的浅水区域。", "primary_collocate": null, "pronunciation": "dà lù jià", "ipa": "ta˥˩ lu˥˩ tɕia˥˩", "syllable_count": 3, "sentences": [{"text": "大陆架是靠近陆地的浅海底。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大陆架的水比较浅，阳光能照到海底。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多渔船在大陆架上捕鱼。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的大陆架上有很多小鱼。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大陆架的外面，海水一下子变得很深。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在书上看到了大陆架的照片。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家有一片很大的大陆架。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大陆架离海岸不远，船很容易到。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家去大陆架下面找石油。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在地图上找到了那片大陆架。", "target_word": "大陆架", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "大陸架", "label": "繁体"}], "register": "书面", "sense_fingerprint": "海底靠近陆地的浅水区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef9cf912-3233-4a4e-8b9e-0ce8bdd8a849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大陆架", "is_correct": true, "explanation": "正确：大陆架指海底靠近陆地的浅水区域，正好符合句意。"}, {"text": "海沟", "is_correct": false, "explanation": "语义：“海沟”指很深的海底，与“浅海底”矛盾。"}, {"text": "沙滩", "is_correct": false, "explanation": "搭配：“沙滩”是陆地上的沙地，不能说是“浅海底”。"}, {"text": "海岸", "is_correct": false, "explanation": "语义：“海岸”是陆地与海的交界线，不是海底，与句意矛盾。"}], "explanations": {"大陆架": "正确：大陆架指海底靠近陆地的浅水区域，正好符合句意。", "海沟": "语义：“海沟”指很深的海底，与“浅海底”矛盾。", "沙滩": "搭配：“沙滩”是陆地上的沙地，不能说是“浅海底”。", "海岸": "语义：“海岸”是陆地与海的交界线，不是海底，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "大陆架"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的大陆架很深，鱼很少。", "explanation": "这里应该用〈海底〉。大陆架是靠近陆地的浅水区，很深的海底要说“海底”。"}, {"text": "大陆架上有很多人在散步。", "explanation": "这里应该用〈海岸〉。人在海岸上散步，大陆架是海底，不能用来散步。"}, {"text": "船长指着那把大陆架说：这里很浅。", "explanation": "这里应该用〈片〉。大陆架是成片的海底区域，量词要用“片”；“把”多用于有柄的器具，不能用于它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大陆架", "is_correct": true, "explanation": "正确：“一片很大的”指面积大的海底区域，与大陆架搭配。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”是抽象的情感，没有面积，不能说“一片很大的”。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”是人数，不能用“一片很大的”来形容。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是声音作品，不能说有“一片很大的”。"}], "explanations": {"大陆架": "正确：“一片很大的”指面积大的海底区域，与大陆架搭配。", "友谊": "语义：“友谊”是抽象的情感，没有面积，不能说“一片很大的”。", "人口": "搭配：“人口”是人数，不能用“一片很大的”来形容。", "歌曲": "语义：“歌曲”是声音作品，不能说有“一片很大的”。"}, "sentence_index": 6, "correct_answer": "大陆架"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一带的大陆架很陡，海水很深。", "explanation": "这里应该用〈大陆坡〉。大陆坡陡峭、海水深；大陆架平缓、较浅，不能用来形容陡坡。"}, {"text": "游客在大陆架上晒太阳。", "explanation": "这里应该用〈沙滩〉。晒太阳要在沙滩上；大陆架在海底，不能用于晒太阳。"}, {"text": "我们在地图上找到了一座大陆架。", "explanation": "这里应该用〈片〉。大陆架是成片的海底区域，量词要用“片”；“座”多用于山、楼房等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一座大陆架上长着很多海草。", "corrected_sentence": "这一片大陆架上长着很多海草。", "error_description": "“大陆架”指成片的海底区域，量词要用“片”；“座”多用于山、楼房等，不能用于大陆架。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家在大陆架旁边的钓鱼。", "corrected_sentence": "科学家在大陆架旁边钓鱼。", "error_description": "方位词“旁边”后不能直接加“的”接动词“钓鱼”，“的”多余，应去掉，说“在大陆架旁边钓鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
