INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "转矩是让东西转起来的力量。", "primary_collocate": null, "pronunciation": "zhuǎn jǔ", "ipa": "tʂuan˨˩˦ tɕy˨˩˦", "syllable_count": 2, "sentences": [{"text": "拧螺丝需要足够的转矩。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的转矩大，上坡很有力。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动机的转矩不够，风扇转不动。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用长扳手可以得到更大的转矩。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门把手离门轴远，同样的转矩只需较小的力气。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车上坡时，蹬踏板需要更大的转矩。", "target_word": "转矩", "complexity_tier": "T3", "furigana": "qí chē shàng pō shí, dēng tà bǎn xū yào gèng dà de zhuǎn jǔ.", "sentence_source": "generated"}, {"text": "螺丝太紧，我施加的转矩不够大。", "target_word": "转矩", "complexity_tier": "T3", "furigana": "luó sī tài jǐn, wǒ shī jiā de zhuǎn jǔ bú gòu dà.", "sentence_source": "generated"}, {"text": "发动机的转矩越大，卡车拉得越多。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小电机转矩小，带不动重东西。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师在测试电动机的转矩。", "target_word": "转矩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技术语", "sense_fingerprint": "转矩：让机器或零件转动起来的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d86f571-e8f9-490c-a880-a6de728f335c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转矩", "is_correct": true, "explanation": "“转矩”指让东西转起来的力量，拧螺丝需要的正是这种力量，句意通顺。"}, {"text": "温度", "is_correct": false, "explanation": "语义：拧螺丝需要的是转动的力，与温度无关，不能说需要足够的温度。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“足够的”一般修饰力量、数量，不能修饰颜色。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体所占的空间，与拧螺丝所需的转动力无关。"}], "explanations": {"转矩": "“转矩”指让东西转起来的力量，拧螺丝需要的正是这种力量，句意通顺。", "温度": "语义：拧螺丝需要的是转动的力，与温度无关，不能说需要足够的温度。", "颜色": "搭配：“足够的”一般修饰力量、数量，不能修饰颜色。", "体积": "语义：体积指物体所占的空间，与拧螺丝所需的转动力无关。"}, "sentence_index": 0, "correct_answer": "转矩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发动机的转矩达到每分钟三千转。", "explanation": "这里应该用〈转速〉。转矩表示转动力的大小，每分钟转多少圈要用转速。"}, {"text": "他的转矩很大，能举起一百斤。", "explanation": "这里应该用〈力气〉。转矩指使物体转动的力，形容人的力气大要说力气，不能说转矩。"}, {"text": "这辆车的转矩很快，一小时能跑一百公里。", "explanation": "这里应该用〈速度〉。转矩不是速度，说车跑得快要用速度，不能用转矩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转矩", "is_correct": true, "explanation": "“转矩”指使东西转动的力，螺丝太紧时施加的正是这种力，句意通顺。"}, {"text": "味道", "is_correct": false, "explanation": "语义：施加的是转动的力，不是味道，句意不通。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“施加”多用于力、压力，不能用于音量。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：螺丝紧不紧与湿度无关，句意不通。"}], "explanations": {"转矩": "“转矩”指使东西转动的力，螺丝太紧时施加的正是这种力，句意通顺。", "味道": "语义：施加的是转动的力，不是味道，句意不通。", "音量": "搭配：“施加”多用于力、压力，不能用于音量。", "湿度": "语义：螺丝紧不紧与湿度无关，句意不通。"}, "sentence_index": 6, "correct_answer": "转矩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电动机的转矩达到了五千瓦。", "explanation": "这里应该用〈功率〉。功率表示做功的快慢，单位是瓦；转矩是转动力的大小，不用瓦来计量。"}, {"text": "这块电池能储存很多转矩。", "explanation": "这里应该用〈能量〉。能量可以储存；转矩描述转动力的大小，不能储存。"}, {"text": "火箭的转矩很大，能把它送上天。", "explanation": "这里应该用〈推力〉。火箭直线上升靠推力，转矩是使物体转动的力，不能用来推火箭直线向上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "用扳手可以给螺丝转矩。", "corrected_sentence": "用扳手可以给螺丝施加转矩。", "error_description": "错误：“转矩”是名词，不能直接作动词用。应为“施加转矩”，需用“施加”带出转矩这个宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电机能产生一只很大的转矩。", "corrected_sentence": "电机能产生一种很大的转矩。", "error_description": "错误：“只”用于动物、手等个体，转矩是抽象的力，量词应用“种”。应为“一种很大的转矩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
