INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机上一起工作的人。", "primary_collocate": null, "pronunciation": "jī zǔ", "ipa": "tɕi˥ tsu˨˩˦", "syllable_count": 2, "sentences": [{"text": "机组在飞机上工作了十个小时。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的机组一共有七个人。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机组里有飞行员，也有乘务员。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机晚点了，机组向大家道歉。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机组人员穿着蓝色的制服。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机组提醒乘客关上手机。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机组很年轻，大家都很热情。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起飞前，机组要开一个小会。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在机组工作，常常飞国外。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机组帮助老人找到了座位。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "机组人员", "label": "复合"}, {"form": "机组成员", "label": "复合"}], "register": "中性", "sense_fingerprint": "机组：在同一架飞机上一起工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d86f571-e8f9-490c-a880-a6de728f335c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机组", "is_correct": true, "explanation": "“机组”指在同一架飞机上一起工作的人，可以作主语，句意通顺。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不在飞机上工作，句意不通。"}, {"text": "机场", "is_correct": false, "explanation": "搭配：“在飞机上工作”的主语应是人员，不能是机场。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不在飞机上工作，与飞机无关，句意不通。"}], "explanations": {"机组": "“机组”指在同一架飞机上一起工作的人，可以作主语，句意通顺。", "学生": "语义：学生不在飞机上工作，句意不通。", "机场": "搭配：“在飞机上工作”的主语应是人员，不能是机场。", "农民": "语义：农民不在飞机上工作，与飞机无关，句意不通。"}, "sentence_index": 0, "correct_answer": "机组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机组负责指挥飞机起降。", "explanation": "这里应该用〈空管人员〉。指挥起降是地面管制人员的工作，机组是在飞机上工作的人，不负责指挥。"}, {"text": "全部旅客的登机手续都由机组办理。", "explanation": "这里应该用〈地勤〉。办理登机手续是地勤人员的工作，机组是在飞机上工作的人，不负责这项工作。"}, {"text": "机组一共买了两百张票。", "explanation": "这里应该用〈乘客〉。买票的是乘客，机组是在飞机上工作的人，不会买票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机组", "is_correct": true, "explanation": "“机组”指一起工作的人，可以说年轻，也与“大家都很热情”相呼应。"}, {"text": "机身", "is_correct": false, "explanation": "语义：机身是飞机的部件，不能说年轻、热情，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有热情，句意不通。"}, {"text": "老人", "is_correct": false, "explanation": "搭配：“很年轻”形容人时与“老人”矛盾，句意不通。"}], "explanations": {"机组": "“机组”指一起工作的人，可以说年轻，也与“大家都很热情”相呼应。", "机身": "语义：机身是飞机的部件，不能说年轻、热情，句意不通。", "电脑": "语义：电脑没有热情，句意不通。", "老人": "搭配：“很年轻”形容人时与“老人”矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "机组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机组负责给飞机加油。", "explanation": "这里应该用〈地勤〉。加油是地勤人员的工作，机组是飞机上一起工作的人，不负责给飞机加油。"}, {"text": "机组每天在工地上砌墙。", "explanation": "这里应该用〈工人〉。砌墙是建筑工人的工作，机组是飞机上一起工作的人，不会在工地上砌墙。"}, {"text": "机组在路上开了一整天车。", "explanation": "这里应该用〈司机〉。司机在路上开车，机组是在飞机上工作的人，不会在路上开车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只机组值得信赖。", "corrected_sentence": "一个机组值得信赖。", "error_description": "错误：“机组”指一群人，量词应用“个”，不能用“只”；应为“一个机组值得信赖。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "起飞前，机组们要先检查安全设备。", "corrected_sentence": "起飞前，机组要先检查安全设备。", "error_description": "错误：“机组”本身表示一群人，后面不能加“们”。应为“机组要先检查安全设备”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
