INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "能猜出以后的事情的本事", "primary_collocate": null, "pronunciation": "yù cè xìng", "ipa": "y⁵¹ tsʰɤ⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "老农凭经验练出预测性，一看云就知道要下雨。", "target_word": "预测性", "complexity_tier": "T3", "furigana": "lǎo nóng píng jīng yàn liàn chū yù cè xìng, yī kàn yún jiù zhī dào yào xià yǔ.", "sentence_source": "generated"}, {"text": "研究比赛数据能提高预测性，她常猜对结果。", "target_word": "预测性", "complexity_tier": "T3", "furigana": "yán jiū bǐ sài shù jù néng tí gāo yù cè xìng, tā cháng cāi duì jié guǒ.", "sentence_source": "generated"}, {"text": "做投资需要预测性，要看得远。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年积累的预测性，让大家很吃惊。", "target_word": "预测性", "complexity_tier": "T3", "furigana": "duō nián jī lěi de yù cè xìng, ràng dà jiā hěn chī jīng.", "sentence_source": "generated"}, {"text": "孩子缺乏预测性，不知道玩火会出事。", "target_word": "预测性", "complexity_tier": "T3", "furigana": "hái zi quē fá yù cè xìng, bù zhī dào wán huǒ huì chū shì.", "sentence_source": "generated"}, {"text": "长期积累经验，能让预测性明显提高。", "target_word": "预测性", "complexity_tier": "T3", "furigana": "cháng qī jī lěi jīng yàn, néng ràng yù cè xìng míng xiǎn tí gāo.", "sentence_source": "generated"}, {"text": "下棋能练出预测性，因为要想好下一步。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋和看比赛都能锻炼预测性，帮助判断形势。", "target_word": "预测性", "complexity_tier": "T3", "furigana": "xià qí hé kàn bǐ sài dōu néng duàn liàn yù cè xìng, bāng zhù pàn duàn xíng shì.", "sentence_source": "generated"}, {"text": "长期观察比赛，能培养出惊人的预测性。", "target_word": "预测性", "complexity_tier": "T3", "furigana": "cháng qī guān chá bǐ sài, néng péi yǎng chū jīng rén de yù cè xìng.", "sentence_source": "generated"}, {"text": "要提高预测性，就得多看多想。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预测性维护", "label": "复合"}], "register": "书面", "sense_fingerprint": "人能猜出以后会发生什么的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a6d8aef-a14f-4db1-9f94-df23b2e8ce72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预测性", "is_correct": true, "explanation": "正确：“练出预测性”指凭经验练出了预判天气的本事，与句意相符。"}, {"text": "皮肤", "is_correct": false, "explanation": "语义：“皮肤”不是靠练习能练出的能力，与预判天气无关。"}, {"text": "胡子", "is_correct": false, "explanation": "体貌：“胡子”是外貌特征，不能用“练出”来指预判天气的本事。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“练”可以搭配“本领、技术”等，不能说“练出工资”。"}], "explanations": {"预测性": "正确：“练出预测性”指凭经验练出了预判天气的本事，与句意相符。", "皮肤": "语义：“皮肤”不是靠练习能练出的能力，与预判天气无关。", "胡子": "体貌：“胡子”是外貌特征，不能用“练出”来指预判天气的本事。", "工资": "搭配：“练”可以搭配“本领、技术”等，不能说“练出工资”。"}, "sentence_index": 0, "correct_answer": "预测性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很有预测性，把题目讲了三遍。", "explanation": "这里应该用〈耐心〉。预测性指能提前猜出事情的本事，把题目讲三遍是耐心，不是预测。"}, {"text": "他的预测性很好，去年的事情都记得。", "explanation": "这里应该用〈记性〉。预测性指能提前猜出以后的事，记住过去的事要说记性。"}, {"text": "小王的预测性很好，一眼就看出谁的画是真品。", "explanation": "这里应该用〈眼力〉。预测性指能猜出以后的事情的本事，辨别眼前东西的真假要说眼力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预测性", "is_correct": true, "explanation": "正确：下棋能练出提前判断形势的能力，因为要想好下一步，“预测性”与之相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温与下棋练出的判断能力无关，句子说不通。"}, {"text": "雨量", "is_correct": false, "explanation": "语义：雨量指降水的多少，与下棋的练习无关。"}, {"text": "亲戚", "is_correct": false, "explanation": "搭配：“练出”不能搭配“亲戚”，说不通。"}], "explanations": {"预测性": "正确：下棋能练出提前判断形势的能力，因为要想好下一步，“预测性”与之相符。", "体温": "语义：体温与下棋练出的判断能力无关，句子说不通。", "雨量": "语义：雨量指降水的多少，与下棋的练习无关。", "亲戚": "搭配：“练出”不能搭配“亲戚”，说不通。"}, "sentence_index": 6, "correct_answer": "预测性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的预测性很好，能看清远处的字。", "explanation": "这里应该用〈视力〉。能看清远处是视力，预测性指提前猜出事情。"}, {"text": "这个学生的预测性很强，老师一点就通。", "explanation": "这里应该用〈理解力〉。预测性指能猜出以后的事情的本事，听懂道理、一学就会要说理解力。"}, {"text": "这只狗的预测性很灵，能闻出远处的食物。", "explanation": "这里应该用〈嗅觉〉。能闻出食物是嗅觉，预测性指能提前猜出事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老船长有一幅很强的预测性，一看海面就知道会起风。", "corrected_sentence": "这位老船长有很强的预测性，一看海面就知道会起风。", "error_description": "量词错误：“预测性”是抽象能力，不能用“幅”（用于字画）计量，应直接说“有很强的预测性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个训练营能增高学员的预测性，让他们提前看出风险。", "corrected_sentence": "这个训练营能提高学员的预测性，让他们提前看出风险。", "error_description": "搭配错误：“提高”用于能力、水平，“增高”只用于高度，不能与“预测性”搭配；应说“提高预测性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
