INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西的一头，比如笔的尖尖。", "primary_collocate": null, "pronunciation": "duān", "ipa": "twan˥", "syllable_count": 1, "sentences": [{"text": "这支笔的一端很尖。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手捏住针的这一端。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木棍的一端放在地上，另一端靠着墙。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你拉住绳子的那一端。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火柴的一端有红色的头。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扁担的两端各挂着一个桶。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把管子的一端放进水里。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼线的一端系着一个小钩。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜡烛的这一端要点火。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹竿的一端太细，不能用。", "target_word": "端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "端点", "label": "复合"}, {"form": "末端", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：细长物体的一头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff80419-2652-460d-9a29-0cfc782ab013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26938, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "端", "is_correct": true, "explanation": "正确。duān，指细长物体的一头。"}, {"text": "短", "is_correct": false, "explanation": "duǎn（第三声）与 duān（第一声）声调不同，意思是长度小。"}, {"text": "断", "is_correct": false, "explanation": "duàn（第四声）与 duān（第一声）声调不同，意思是断开。"}, {"text": "穿", "is_correct": false, "explanation": "chuān 与 duān 声母不同（ch 与 d），意思是穿过、穿上。"}, {"text": "酸", "is_correct": false, "explanation": "suān 与 duān 声母不同（s 与 d），意思是味道酸。"}], "explanations": {"端": "正确。duān，指细长物体的一头。", "短": "duǎn（第三声）与 duān（第一声）声调不同，意思是长度小。", "断": "duàn（第四声）与 duān（第一声）声调不同，意思是断开。", "穿": "chuān 与 duān 声母不同（ch 与 d），意思是穿过、穿上。", "酸": "suān 与 duān 声母不同（s 与 d），意思是味道酸。"}, "sentence_index": null, "correct_answer": "端"}, "level_3": {"options": [{"text": "端", "is_correct": true, "explanation": "正确。“一端”指笔的一头，与“很尖”呼应。"}, {"text": "圈", "is_correct": false, "explanation": "体貌：圆圈的形状与“很尖”的外形不符，笔的一头不是圆圈。"}, {"text": "层", "is_correct": false, "explanation": "搭配：“层”不能与“很尖”搭配，层是覆盖的薄层，不是可以尖的部分。"}, {"text": "片", "is_correct": false, "explanation": "语义：薄片平整，与“很尖”的特征相反。"}], "explanations": {"端": "正确。“一端”指笔的一头，与“很尖”呼应。", "圈": "体貌：圆圈的形状与“很尖”的外形不符，笔的一头不是圆圈。", "层": "搭配：“层”不能与“很尖”搭配，层是覆盖的薄层，不是可以尖的部分。", "片": "语义：薄片平整，与“很尖”的特征相反。"}, "sentence_index": 0, "correct_answer": "端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的端很精彩，大家都看入迷了。", "explanation": "这里应该用〈开头〉。端指东西的一头，不指比赛开始的阶段。"}, {"text": "这辆汽车的端很亮，夜里特别显眼。", "explanation": "这里应该用〈车头〉。端指东西的一头，汽车前部叫车头，不说车的“端”。"}, {"text": "他的端很帅，大家都夸他。", "explanation": "这里应该用〈长相〉。端指东西的一头，不指人的相貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26938, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "端", "is_correct": true, "explanation": "正确。duān，指细长物体的一头。"}, {"text": "专", "is_correct": false, "explanation": "zhuān 与 duān 声母不同（zh 与 d），意思是专门、专一。"}, {"text": "宽", "is_correct": false, "explanation": "kuān 与 duān 声母不同（k 与 d），意思是宽阔。"}, {"text": "欢", "is_correct": false, "explanation": "huān 与 duān 声母不同（h 与 d），意思是高兴、喜欢。"}, {"text": "钻", "is_correct": false, "explanation": "zuān 与 duān 声母不同（z 与 d），意思是钻进去。"}, {"text": "段", "is_correct": false, "explanation": "duàn（第四声）与 duān（第一声）声调不同，意思是一段、一截。"}], "explanations": {"端": "正确。duān，指细长物体的一头。", "专": "zhuān 与 duān 声母不同（zh 与 d），意思是专门、专一。", "宽": "kuān 与 duān 声母不同（k 与 d），意思是宽阔。", "欢": "huān 与 duān 声母不同（h 与 d），意思是高兴、喜欢。", "钻": "zuān 与 duān 声母不同（z 与 d），意思是钻进去。", "段": "duàn（第四声）与 duān（第一声）声调不同，意思是一段、一截。"}, "sentence_index": null, "correct_answer": "端"}, "level_3": {"options": [{"text": "端", "is_correct": true, "explanation": "正确。“一端”指管子的一头，与“放进水里”相符。"}, {"text": "层", "is_correct": false, "explanation": "搭配：“一层”不能用来指管子的一部分，与“放进水里”不搭配。"}, {"text": "环", "is_correct": false, "explanation": "语义：环是圆形，管子的一端不是圆环，句意不通。"}, {"text": "粒", "is_correct": false, "explanation": "量词：“粒”指颗粒状的小东西，管子不能用“粒”计量，句意不通。"}], "explanations": {"端": "正确。“一端”指管子的一头，与“放进水里”相符。", "层": "搭配：“一层”不能用来指管子的一部分，与“放进水里”不搭配。", "环": "语义：环是圆形，管子的一端不是圆环，句意不通。", "粒": "量词：“粒”指颗粒状的小东西，管子不能用“粒”计量，句意不通。"}, "sentence_index": 6, "correct_answer": "端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个杯子的端有一层茶叶，喝的时候别喝到。", "explanation": "这里应该用〈杯底〉。端指物体的一头，杯子底部要说“杯底”。"}, {"text": "这个瓶子的端很小，水不好倒。", "explanation": "这里应该用〈瓶口〉。端指一头的整体，瓶子开口处要说“瓶口”。"}, {"text": "这把椅子的端很稳，坐着不晃。", "explanation": "这里应该用〈椅腿〉。支撑椅子的部分叫椅腿，“端”指一头的整体，不用来指腿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根针的一条端磨得很尖。", "corrected_sentence": "这根针的一端磨得很尖。", "error_description": "错误在“端”前的量词：“端”不用“条”来计量。正确形式是“这根针的一端”，直接用“一端”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把竹竿了一端削尖了。", "corrected_sentence": "他把竹竿的一端削尖了。", "error_description": "错误在“竹竿”和“一端”之间：领属关系要用“的”，写成“了”不通。正确形式是“他把竹竿的一端削尖了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
