INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变聪明，比如机器可以自己学习做事。", "primary_collocate": null, "pronunciation": "zhì néng huà", "ipa": "ʈʂɻ̩˥˩ nɤŋ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "他想让家里的灯智能化。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表智能化以后，能记录睡觉的时间。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂智能化了，机器自己就能做事。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在把汽车智能化。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人智能化后，可以自己学习。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的教室也智能化了。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱智能化以后，会提醒你买牛奶。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给房子装上电脑，就能让它智能化。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老电视智能化后，可以上网看电影。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场智能化以后，机器会自己浇水。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "智能化了", "label": "体标"}, {"form": "智能化改造", "label": "复合"}], "register": "中性", "sense_fingerprint": "智能化：让东西变聪明，能自己学习做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a6d8aef-a14f-4db1-9f94-df23b2e8ce72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "智能化", "is_correct": true, "explanation": "正确。“让家里的灯智能化”指使灯具备自动控制能力，符合句意。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”只用于人或动物的身形，不能用于灯。"}, {"text": "哭泣", "is_correct": false, "explanation": "配价：“哭泣”通常以人或动物为主体，不能让灯作施事。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指身体不适，灯不会生病，此处语义不通。"}], "explanations": {"智能化": "正确。“让家里的灯智能化”指使灯具备自动控制能力，符合句意。", "发胖": "体貌：“发胖”只用于人或动物的身形，不能用于灯。", "哭泣": "配价：“哭泣”通常以人或动物为主体，不能让灯作施事。", "生病": "语义：“生病”指身体不适，灯不会生病，此处语义不通。"}, "sentence_index": 0, "correct_answer": "智能化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想让孩子智能化，每天多读书。", "explanation": "这里应该用〈变聪明〉。让人变得聪明要说“变聪明”；智能化只指让机器、物品具备判断和学习能力，不能用于孩子。"}, {"text": "这家洗衣店把衣服智能化得很干净。", "explanation": "这里应该用〈清洗〉。衣服洗干净要说清洗；智能化指让机器具备判断能力。"}, {"text": "这栋楼的墙已经智能化了，很结实。", "explanation": "这里应该用〈加固〉。墙变结实要说加固；智能化指使东西具备判断和学习能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "智能化", "is_correct": true, "explanation": "正确。“冰箱智能化以后”指冰箱具备判断、提醒功能，符合句意。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，与“提醒你买牛奶”的功能无关。"}, {"text": "漏水", "is_correct": false, "explanation": "语义：“冰箱漏水”之后不能接“会提醒你买牛奶”，语义冲突。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是人或动物的动作，冰箱不能作施事。"}], "explanations": {"智能化": "正确。“冰箱智能化以后”指冰箱具备判断、提醒功能，符合句意。", "生锈": "语义：“生锈”指金属被氧化，与“提醒你买牛奶”的功能无关。", "漏水": "语义：“冰箱漏水”之后不能接“会提醒你买牛奶”，语义冲突。", "咳嗽": "配价：“咳嗽”是人或动物的动作，冰箱不能作施事。"}, "sentence_index": 6, "correct_answer": "智能化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台空调能智能化温度，每天都很舒服。", "explanation": "这里应该用〈调节〉。温度要说调节；智能化是让机器具备判断能力，不能直接带温度作宾语。"}, {"text": "这篇文章已经智能化成英文了，大家都能看懂。", "explanation": "这里应该用〈翻译〉。文章换成另一种语言要说翻译；智能化不表示语言转换。"}, {"text": "农民每年都智能化很多蔬菜，卖给超市。", "explanation": "这里应该用〈种植〉。蔬菜的生长要说种植；智能化不能用于植物的种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想让这台旧空调智能化了，能自动调温。", "corrected_sentence": "我想让这台旧空调智能化，能自动调温。", "error_description": "“想”表示意愿，“让……智能化”尚未发生，不能在“智能化”后加“了”；应说“我想让这台旧空调智能化”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经把这间老仓库智能化了了，不用人看管。", "corrected_sentence": "我们已经把这间老仓库智能化了，不用人看管。", "error_description": "“了”重复：“智能化”后只用一个“了”表示完成，应说“把这间老仓库智能化了”，多出的那个“了”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自下而上", "is_correct": true, "explanation": "正确：“自下而上”与“自上而下”表示相反的方向，是词典列出的反义词。"}, {"text": "慢慢", "is_correct": false, "explanation": "“慢慢”表示速度缓慢，与方向无关。"}, {"text": "突然", "is_correct": false, "explanation": "“突然”表示发生得很快，与方向无关。"}, {"text": "偶尔", "is_correct": false, "explanation": "“偶尔”表示次数少，与方向无关。"}], "correct_answer": "自下而上", "explanations": {"自下而上": "正确：“自下而上”与“自上而下”表示相反的方向，是词典列出的反义词。", "慢慢": "“慢慢”表示速度缓慢，与方向无关。", "突然": "“突然”表示发生得很快，与方向无关。", "偶尔": "“偶尔”表示次数少，与方向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自下而上", "is_correct": true, "explanation": "正确：“自下而上”与“自上而下”表示相反的方向，是词典列出的反义词。"}, {"text": "渐渐", "is_correct": false, "explanation": "“渐渐”表示逐步变化，与方向无关。"}, {"text": "忽然", "is_correct": false, "explanation": "“忽然”表示出乎意料地发生，与方向无关。"}, {"text": "猛然", "is_correct": false, "explanation": "“猛然”表示突然而有力，与方向无关。"}], "correct_answer": "自下而上", "explanations": {"自下而上": "正确：“自下而上”与“自上而下”表示相反的方向，是词典列出的反义词。", "渐渐": "“渐渐”表示逐步变化，与方向无关。", "忽然": "“忽然”表示出乎意料地发生，与方向无关。", "猛然": "“猛然”表示突然而有力，与方向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "从上往下。", "primary_collocate": null, "pronunciation": "zì shàng ér xià", "ipa": "tsɨ˥˩ ʂaŋ˥˩ ɚ˧˥ ɕja˥˩", "syllable_count": 4, "sentences": [{"text": "水自上而下流过石头。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你自上而下擦这面玻璃。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自上而下看了一遍这张表。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水自上而下，流进了小河。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油漆要自上而下刷，才不会滴到地上。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光自上而下照在她身上。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架要自上而下一层一层地整理。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瀑布自上而下，声音很大。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自上而下读了一遍这篇短文。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师自上而下检查每一行字。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自下而上", "label": "反义"}], "register": "书面", "sense_fingerprint": "副词：动作或物体从上往下的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff80419-2652-460d-9a29-0cfc782ab013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自上而下", "is_correct": true, "explanation": "正确：“自上而下”作状语，说明水从上往下流，符合物理情境。"}, {"text": "呆呆地", "is_correct": false, "explanation": "语义：“呆呆地”形容人的神情或状态，不能用来描述水的流动。"}, {"text": "高兴地", "is_correct": false, "explanation": "搭配：“高兴”描述人的情绪，不能用来修饰水的流动。"}, {"text": "愤怒地", "is_correct": false, "explanation": "语义：“愤怒地”描述人的情绪反应，与水流过石头的情境不符。"}], "explanations": {"自上而下": "正确：“自上而下”作状语，说明水从上往下流，符合物理情境。", "呆呆地": "语义：“呆呆地”形容人的神情或状态，不能用来描述水的流动。", "高兴地": "搭配：“高兴”描述人的情绪，不能用来修饰水的流动。", "愤怒地": "语义：“愤怒地”描述人的情绪反应，与水流过石头的情境不符。"}, "sentence_index": 0, "correct_answer": "自上而下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蚂蚁自上而下爬上了树。", "explanation": "这里应该用〈自下而上〉。“爬上”是从下往上，而“自上而下”指从上往下，方向相反。"}, {"text": "他自上而下笑了一下。", "explanation": "这里应该用〈微微〉之类的词。这句把“自上而下”用来修饰“笑”，而“笑”没有空间位移，不存在从上往下的方向。"}, {"text": "灯自上而下放在桌上。", "explanation": "错用：“自上而下”描述的是动作从上往下移动的方式，不能用来说明“放在桌上”这种静止的摆放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
